// Database completo incantesimi D&D 5e (italiano)
// Ogni entry: { livello, scuola, classi, tempo, gittata, area?, danno?, tipoDanno?, conc?, rituale?, desc }

export const INCANTESIMI_DB = {
  "Riparare": { livello:0, scuola:"Trasmutazione", classi:["Artefice","Bardo","Chierico","Druido","Mago","Stregone"], tempo:"1 min", gittata:"Tocco", desc:"Questo incantesimo ripara una singola crepa o uno squarcio in un oggetto toccato dall'incantatore, come l'anello spezzato di una catena, due metà di una chiave spezzata, un mantello strappato o un otre forato.\n\nFintanto che la crepa o lo squarcio non è più grande di 30 cm in ogni dimensione, l'incantatore lo ripara senza lasciare traccia del danno precedente.\n\nQuesto incantesimo può fisicamente riparare un oggetto magico o un costrutto, ma non può ripristinare la magia in un oggetto del genere." },
  "Artificio Druidico": { livello:0, scuola:"Trasmutazione", classi:["Druido"], tempo:"1 Azione", gittata:"9m", desc:"Sussurrando agli spiriti della natura, l'incantatore crea uno degli effetti seguenti entro gittata. Sensore atmosferico. L'incantatore crea un Minuscolo e innocuo effetto sensoriale che predice il tempo atmosferico nel luogo in cui si trova per le successive 24 ore. L'effetto potrebbe manifestarsi come una sfera dorata in caso di cieli tersi, una nuvola in caso di pioggia, fiocchi di neve in caso di nevicate e così via. Questo effetto permane per 1 round. Fioritura. L'incantatore fa istantaneamente sbocciare un fiore, aprire un baccello o schiudere un germoglio. Effetto sensoriale. L'incantatore crea un effetto sensoriale innocuo, come la caduta di foglie, delle fate spettrali danzanti, una brezza leggera, il rumore di un piccolo animale o il debole odore di una puzzola. L'effetto deve poter essere contenuto in un cubo con spigolo di 1,5 metri. Trucchetto col fuoco. L'incantatore accende o spegne una candela, una torcia o un fuoco da campo." },
  "Randello Incantato": { livello:0, scuola:"Trasmutazione", classi:["Druido"], tempo:"1 Azione Bonus", gittata:"Tocco", danno:"1d8", tipoDanno:"Contundente", desc:"Il legno di un randello o di un bastone ferrato impugnato dall'incantatore è pervaso dal potere della natura. Per la durata dell’incantesimo, l'incantatore può usare la sua caratteristica da incantatore anziché la Forza per i tiri per colpire e i tiri per i danni effettuati negli attacchi in mischia usando quell'arma; inoltre, i danni dell’arma diventano un d8. L’arma diventa magica, se già non lo era. L’incantesimo termina se l'incantatore lo lancia di nuovo o se lascia andare l’arma." },
  "Folata": { livello:0, scuola:"Trasmutazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"9m", desc:"Una linea di vento forte lunga 18 metri e larga 3 metri si diffonde dall'incantatore in una direzione a sua scelta per la durata dell'incantesimo.\n\nOgni creatura che inizia il suo turno su quella linea deve superare un tiro salvezza su Forza, altrimenti sarà spinta di 4,5 metri più lontana dall'incantatore, nella stessa direzione della linea. Ogni creatura sulla linea deve spendere 60 cm di movimento per ogni 30 cm di cui si muove quando cerca di avvicinarsi all'incantatore.\n\nLa folata disperde i gas e i vapori ed estingue candele, torce e simili fiamme prive di protezione nell'area. Fa tremolare le fiamme protette come quelle delle lanterne e ha una probabilità del 50% di spegnerle.\n\nCon un'azione bonus in ogni suo turno prima che l'incantesimo termini, l'incantatore può cambiare la direzione in cui la linea si diffonde da sé." },
  "Colpo Accurato": { livello:0, scuola:"Divinazione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso / Mischia", danno:"1d6", tipoDanno:"Radiante", desc:"Guidato da un lampo di intuizione magica, l'incantatore effettua un attacco con l'arma utilizzata per lanciare l'incantesimo. Per determinare il tiro per colpire e il tiro per i danni, l'incantatore utilizza la sua caratteristica da incantatore invece che la Forza o la Destrezza. Se l'attacco infligge danni, possono essere danni radiosi o danni normali inflitti dall'arma (a scelta dell'incantatore). Trucchetto potenziato. A prescindere dal tipo di danni che l'incantatore sceglie (danni radiosi o danni normali dell'arma), l'attacco infligge danni radiosi extra quando l'incantatore raggiunge il 5º livello (1d6), l'11º livello (2d6) e il 17º livello (3d6).\n\n**Potenziamento per i Trucchetti.** A prescindere dal tipo di danni che l'incantatore sceglie (danni radiosi o danni normali dell'arma), l'attacco infligge danni radiosi extra quando l'incantatore raggiunge il 5º livello (1d6), l'11º livello (2d6) e il 17º livello (3d6)." },
  "Dardo Infuocato": { livello:0, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"36m", danno:"1d10", tipoDanno:"Fuoco", desc:"L'incantatore scaglia una scintilla di fuoco verso una creatura o un oggetto situato entro gittata, effettuando un attacco a distanza con questo incantesimo contro il bersaglio.\n\nSe colpisce, il bersaglio subisce 1d10 danni da fuoco.\n\nUn oggetto infiammabile colpito da questo incantesimo si incendia se non è indossato o trasportato.\n\nI danni di questo incantesimo aumentano di 1d10 quando l'incantatore arriva al 5° livello (2d10), 11° livello (3d10) e 17° livello (4d10)." },
  "Beffa Crudele": { livello:0, scuola:"Ammaliamento", classi:["Bardo"], tempo:"1 Azione", gittata:"18m", danno:"1d6", tipoDanno:"Psichico", desc:"L'incantatore pronuncia una sequenza di insulti mescolati a impercettibili ammaliamenti contro una creatura entro gittata che egli è in grado di vedere o di sentire. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti subisce 1d6 danni psichici e svantaggio al tiro per colpire successivo che effettua prima della fine del suo turno successivo. Trucchetto potenziato. I danni aumentano di 1d6 quando l'incantatore raggiunge il 5º livello (2d6), l'11º livello (3d6) e il 17º livello (4d6).\n\n**Potenziamento per i Trucchetti.** I danni aumentano di 1d6 quando l'incantatore raggiunge il 5º livello (2d6), l'11º livello (3d6) e il 17º livello (4d6)." },
  "Fiamma Sacra": { livello:0, scuola:"Invocazione", classi:["Chierico"], tempo:"1 Azione", gittata:"18m", danno:"1d8", tipoDanno:"Radiante", desc:"Un bagliore simile a una fiamma scende fino a una creatura entro gittata e che l'incantatore sia in grado di vedere.\n\nIl bersaglio deve superare un tiro salvezza su Destrezza, altrimenti subisce 1d8 danni radiosi. Il bersaglio non trae beneficio dalla copertura per questo tiro salvezza.\n\nI danni di questo incantesimo aumentano di 1d8 quando l'incantatore arriva al 5° livello (2d8), 11° livello (3d8) e 17° livello (4d8)." },
  "Frusta di Spine": { livello:0, scuola:"Trasmutazione", classi:["Druido"], tempo:"1 Azione", gittata:"9m", danno:"1d6", tipoDanno:"Perforante", desc:"Crei una lunga frusta simile a un rampicante coperta di spine ed effettui un attacco in mischia con questo incantesimo contro una creatura entro gittata (9 metri). Se l'attacco colpisce, il bersaglio subisce 1d6 danni perforanti e, se la creatura è di taglia Grande o inferiore, puoi trascinarla verso di te fino a un massimo di 3 metri in linea retta.\n\n**Potenziamento per i Trucchetti.** I danni di questo incantesimo aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6)." },
  "Guida": { livello:0, scuola:"Divinazione", classi:["Chierico","Druido"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"L'incantatore tocca una creatura consenziente. Una volta prima che l'incantesimo termini il bersaglio può tirare un d4 e aggiungere il risultato a una prova di caratteristica a sua scelta. Può tirare il dado prima o dopo avere effettuato la prova di caratteristica. Dopodiché l'incantesimo termina." },
  "Illusione Minore": { livello:0, scuola:"Illusione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"9m", area:"Cubo", desc:"L'incantatore crea un suono o un'immagine di un oggetto entro gittata che permane per la durata dell'incantesimo.\n\nL'illusione termina anche se l'incantatore la interrompe con un'azione o se lancia questo incantesimo di nuovo.\n\n- **Se l'incantatore crea un suono,** il suo volume può variare da un sussurro a un urlo. Può trattarsi della voce dell'incantatore, della voce di qualcun altro, del ruggito di un leone, di un rullo di tamburi o di un qualsiasi altro suono a sua scelta.\n\nIl suono può echeggiare ininterrottamente per tutta la durata, oppure l'incantatore può emettere suoni più discreti in momenti diversi prima che l'incantesimo termini.\n\n- **Se l'incantatore crea l'immagine di un oggetto** (come per esempio una sedia, una serie di impronte nel fango o uno scrigno), quell'oggetto non deve essere più grande di un cubo con spigolo di 1,5 metri.\n\nL'immagine non può emettere suoni, luci, odori o qualsiasi altro effetto sensoriale.\n\nUn'interazione fisica con l'immagine rivela che si tratta di un'illusione, in quanto gli oggetti la attraversano.\n\nSe una creatura usa la sua azione per esaminare il suono o l'immagine, può determinare che si tratta di un'illusione se effettua con successo una prova di Intelligenza (Indagare) contro la CD del tiro salvezza dell'incantesimo.\n\nSe una creatura discerne l'illusione per ciò che è, l'illusione si attenua per quella creatura." },
  "Interdizione alle Lame": { livello:0, scuola:"Abiurazione", classi:["Bardo","Chierico","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso", desc:"Tracci un sigillo protettivo nell'aria con un gesto della mano. Fino alla fine del tuo prossimo turno, ottieni resistenza contro i danni contundenti, perforanti e taglienti inflitti da attacchi con armi.\n\n*(Nelle regole 2024, Interdizione alle Lame è lanciabile come reazione quando vieni colpito da un attacco, sottraendo 1d4 al tiro per colpire dell'avversario).*" },
  "Luce": { livello:0, scuola:"Invocazione", classi:["Bardo","Chierico","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Tocco", desc:"L'incantatore tocca un oggetto non più grande di 3 metri in ogni dimensione.\n\nFinché l'incantesimo non termina, l'oggetto proietta luce intensa entro un raggio di 6 metri e luce fioca per altri 6 metri.\n\nLa luce può essere del colore desiderato dall'incantatore.\n\nCoprire completamente l'oggetto con qualcosa di opaco blocca la luce.\n\nL'incantesimo termina se l'incantatore lo lancia di nuovo o lo interrompe con un'azione.\n\nSe l'incantatore bersaglia un oggetto impugnato o posseduto da una creatura ostile, quella creatura deve superare un tiro salvezza su Destrezza per evitare l'incantesimo." },
  "Luci Danzanti": { livello:0, scuola:"Invocazione", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"36m", conc:true, desc:"fino a 1 minuto L'incantatore crea fino a quattro luci delle dimensioni di una torcia, facendole apparire come lanterne, torce o globi luminosi che fluttuano per la durata dell'incantesimo entro la sua gittata. In alternativa, l'incantatore può fondere le quattro luci in un'unica forma luminosa di taglia Media di aspetto simile a quello umano. Qualunque sia la forma scelta, ogni luce proietta luce fioca entro un raggio di 3 metri. Come azione bonus, l'incantatore può muovere le luci per un massimo di 18 metri fino a un punto entro gittata. Ogni luce deve trovarsi entro 6 metri da un'altra luce creata da questo incantesimo. Se una delle luci supera la gittata dell'incantesimo, svanisce." },
  "Mano Magica": { livello:0, scuola:"Evocazione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"9m", desc:"Una mano spettrale e fluttuante appare nel punto scelto all'interno del raggio. La mano dura per la durata o fino a quando non la scartate come azione. La mano svanisce se è mai più di 9 metri di distanza da te o se lanci di nuovo questo incantesimo.\n\nPuoi usare la tua azione per controllare la mano. Puoi usare la mano per manipolare un oggetto, aprire una porta o un contenitore sbloccato, riporre o recuperare un oggetto da un contenitore aperto o versare il contenuto da una fiala. Puoi muovere la mano fino a 9 metri ogni volta che la usi.\n\nLa mano non può attaccare, attivare oggetti magici o trasportare più di 10 chili." },
  "Messaggio": { livello:0, scuola:"Trasmutazione", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"36m", desc:"L'incantatore punta l'indice verso una creatura entro gittata e sussurra un messaggio, il bersaglio (e soltanto il bersaglio) sente il messaggio e può rispondere con un sussurro che soltanto l'incantatore può udire.\n\nL'incantatore può lanciare questo incantesimo attraverso gli oggetti solidi, se ha familiarità con il bersaglio e sa che si trova oltre la barriera.\n\nIl silenzio magico, 30 cm di pietra, 2,5 cm di metallo comune, una sottile lamina di piombo o 90 cm di legno bloccano l'incantesimo.\n\nl'incantesimo non deve necessariamente seguire una linea retta e può svilupparsi liberamente oltre gli angoli e attraverso le aperture." },
  "Morsa del Gelo": { livello:0, scuola:"Invocazione", classi:["Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", danno:"1d6", tipoDanno:"Freddo", desc:"Invochi un gelo intorpidente su una creatura visibile entro gittata (18 metri). Il bersaglio deve effettuare un tiro salvezza su Costituzione. Se fallisce, subisce 1d6 danni da freddo e ha svantaggio al prossimo tiro per colpire con un'arma che effettua prima della fine del suo turno successivo.\n\n**Potenziamento per i Trucchetti.** I danni aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6)." },
  "Prestidigitazione": { livello:0, scuola:"Trasmutazione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"3m", desc:"- **Tempo di lancio**: 1 azione\n\n- **Raggio**: 3 metri\n\n- **Componenti**: V, S\n\n- **Durata**: Fino a 1 ora\n\nQuesto incantesimo è un trucco magico che gli incantatori novizi usano per fare pratica. L'incantatore crea uno degli effetti magici seguenti entro gittata:\n\n- Crea un effetto sensoriale innocuo e istantaneo, come una pioggia di scintille, una folata di vento, una tenue melodia musicale o uno strano odore.\n\n- Accende o spegne istantaneamente una candela, una torcia o un piccolo fuoco da campo.\n\n- Pulisce o sporca istantaneamente un oggetto non più grande di un cubo con spigolo di 30 cm.\n\n- Riscalda, raffredda o condisce materiale non vivente del volume massimo di un cubo di spigolo di 30 cm per 1 ora.\n\n- Fa comparire un colore, un piccolo segno o un simbolo su un oggetto o una superficie per 1 ora.\n\n- Crea un ninnolo non magico o un'immagine illusoria che può stare nella sua mano e che permane fino alla fine del suo turno.\n\nSe l'incantatore lancia questo incantesimo più volte può tenere attivi fino a tre dei suoi effetti non istantanei contemporaneamente, e può congedare ognuno di questi effetti con un'azione." },
  "Produrre Fiamma": { livello:0, scuola:"Invocazione", classi:["Druido"], tempo:"1 Azione", gittata:"Sé stesso / 9m", danno:"1d8", tipoDanno:"Fuoco", desc:"Una fiamma tremolante compare nella mano dell'incantatore. La fiamma permane per la durata dell'incantesimo e non infligge danni né all'incantatore né al suo equipaggiamento. La fiamma proietta luce intensa entro un raggio di 3 metri e luce fioca per altri 3 metri.\n\nL'incantesimo termina se l'incantatore lo interrompe con un'azione o se lo lancia di nuovo.\n\nL'incantatore può anche attaccare con la fiamma, ponendo termine all'incantesimo. Quando l'incantatore lancia questo incantesimo, o usando un'azione in un turno successivo, può scagliare la fiamma contro una creatura situata entro 9 metri da lui. Effettua un attacco a distanza con questo incantesimo. Se colpisce, il bersaglio subisce 1d8 danni da fuoco.\n\nI danni di questo incantesimo aumentano di 1d8 quando l'incantatore arriva al 5° livello (2d8), 11° livello (3d8) e 17° livello (4d8)." },
  "Deflagrazione Occulta": { livello:0, scuola:"Invocazione", classi:["Warlock"], tempo:"1 Azione", gittata:"36m", danno:"1d10", tipoDanno:"Forza", desc:"L'incantatore scaglia un raggio di energia crepitante, effettuando un attacco a distanza con incantesimo contro una creatura o un oggetto entro gittata. Se il colpo va a segno, il bersaglio subisce 1d10 danni da forza. Trucchetto potenziato. L'incantesimo crea due raggi al 5º livello, tre raggi all'11º livello e quattro raggi al 17º livello. L'incantatore può indirizzare i raggi contro lo stesso bersaglio o contro bersagli differenti, effettuando un tiro per colpire separato per ogni raggio.\n\n**Potenziamento per i Trucchetti.** L'incantesimo crea due raggi al 5º livello, tre raggi all'11º livello e quattro raggi al 17º livello. L'incantatore può indirizzare i raggi contro lo stesso bersaglio o contro bersagli differenti, effettuando un tiro per colpire separato per ogni raggio." },
  "Raggio di Gelo": { livello:0, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"18m", danno:"1d8", tipoDanno:"Freddo", desc:"Un raggio gelido di luce azzurra e biancastra sfreccia verso una creatura entro gittata.\n\nL'incantatore effettua un attacco a distanza con questo incantesimo contro il bersaglio.\n\nSe lo colpisce, il bersaglio subisce 1d8 danni da freddo e la sua velocità è ridotta di 3 metri fino all'inizio del turno successivo dell'incantatore.\n\nI danni di questo incantesimo aumentano di 1d8 quando l'incantatore arriva al 5° livello (2d8), 11° livello (3d8) e 17° livello (4d8)." },
  "Resistenza": { livello:0, scuola:"Abiurazione", classi:["Chierico","Druido"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"L'incantatore tocca una creatura consenziente. Per una volta prima che l'incantesimo termini, il bersaglio può tirare un d4 e aggiungere il risultato ottenuto ad un tiro salvezza a sua scelta. Può tirare il dado prima o dopo avere effettuato il tiro salvezza. Dopodiché l'incantesimo termina." },
  "Rintocco dei Morti": { livello:0, scuola:"Necromanzia", classi:["Chierico","Mago","Warlock"], tempo:"1 Azione", gittata:"18m", danno:"1d8", tipoDanno:"Necrotico", desc:"Punti il dito verso una creatura visibile entro gittata (18 metri) e il suono di una cupa campana a morto risuona nell'aria attorno ad essa. Il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti subisce 1d8 danni necrotici. Se al momento del lancio il bersaglio è privo di anche un solo punto ferita, subisce invece 1d12 danni necrotici.\n\n**Potenziamento per i Trucchetti.** I danni aumentano di un dado quando raggiungi il 5° livello (2d8 o 2d12), l'11° livello (3d8 o 3d12) e il 17° livello (4d8 o 4d12)." },
  "Lama della Fiamma Verde": { livello:0, scuola:"Invocazione", classi:["Artefice","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso (1,5m)", danno:"1d8", tipoDanno:"Fuoco", desc:"Compi un attacco in mischia con un'arma come parte dell'azione utilizzata per lanciare questo incantesimo. Se colpisci il bersaglio, subisce i normali effetti dell'attacco con l'arma, e una fiammata verde balza dal bersaglio a una seconda creatura a tua scelta entro 1,5 metri da esso. La seconda creatura subisce danni da fuoco pari al tuo modificatore di caratteristica da incantatore.\n\n**Potenziamento per i Trucchetti.** Al 5° livello, l'attacco in mischia infligge 1d8 danni da fuoco extra al bersaglio primario e i danni da fuoco al secondo bersaglio aumentano a 1d8 + il modificatore di caratteristica da incantatore. Entrambi i tiri di danno aumentano di 1d8 all'11° livello (2d8 e 2d8) e al 17° livello (3d8 e 3d8)." },
  "Lama Tonante": { livello:0, scuola:"Invocazione", classi:["Artefice","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso (1,5m)", danno:"1d8", tipoDanno:"Tuono", desc:"Compi un attacco in mischia con un'arma come parte dell'azione utilizzata per lanciare questo incantesimo. Se colpisci il bersaglio, subisce i normali effetti dell'attacco con l'arma e viene avvolto da un'energia tonante instabile fino all'inizio del tuo prossimo turno. Se il bersaglio si muove volontariamente di 1,5 metri o più prima di allora, subisce immediatamente 1d8 danni da tuono e l'incantesimo ha termine.\n\n**Potenziamento per i Trucchetti.** Al 5° livello, l'attacco in mischia infligge 1d8 danni da tuono extra al bersaglio se colpisce, e il danno che il bersaglio subisce muovendosi aumenta a 2d8. Entrambi i tiri di danno aumentano di 1d8 all'11° livello (2d8 e 3d8) e al 17° livello (3d8 e 4d8)." },
  "Raffica di Spade": { livello:0, scuola:"Invocazione", classi:["Artefice","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso (1,5m)", danno:"1d6", tipoDanno:"Forza", desc:"Evochi una girandola di lame spettrali che volteggiano attorno a te e svaniscono all'istante. Ogni creatura entro 1,5 metri da te deve superare un tiro salvezza su Destrezza, altrimenti subisce 1d6 danni da forza.\n\n**Potenziamento per i Trucchetti.** I danni di questo incantesimo aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6)." },
  "Scheggia Mentale": { livello:0, scuola:"Ammaliamento", classi:["Artefice","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", danno:"1d6", tipoDanno:"Psichico", desc:"Scagli una freccia di energia psichica disorientante contro la mente di una creatura visibile entro gittata (18 metri). Il bersaglio deve superare un tiro salvezza su Intelligenza, altrimenti subisce 1d6 danni psichici e sottrae 1d4 al prossimo tiro salvezza che effettua prima della fine del tuo prossimo turno.\n\n**Potenziamento per i Trucchetti.** I danni di questo incantesimo aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6)." },
  "Attrazione di Fulmini": { livello:0, scuola:"Invocazione", classi:["Artefice","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"4,5m", danno:"1d8", tipoDanno:"Fulmine", desc:"Crei una sferzata di fulmini che scatta verso una creatura visibile entro gittata (4,5 metri). Il bersaglio deve superare un tiro salvezza su Forza, altrimenti viene trascinato fino a 3 metri in linea retta verso di te. Se il bersaglio finisce entro 1,5 metri da te, subisce 1d8 danni da fulmine.\n\n**Potenziamento per i Trucchetti.** I danni di questo incantesimo aumentano di 1d8 quando raggiungi il 5° livello (2d8), l'11° livello (3d8) e il 17° livello (4d8)." },
  "Spruzzo Velenoso": { livello:0, scuola:"Invocazione", classi:["Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"3m", danno:"1d12", tipoDanno:"Veleno", desc:"L'incantatore allunga la mano verso una creatura entro gittata e che egli sia in grado di vedere e proietta uno sbuffo di gas velenoso dal suo palmo.\n\nLa creatura deve superare un tiro salvezza su Costituzione, altrimenti subisce 1d12 danni da veleno.\n\nI danni di questo incantesimo aumentano di 1d12 quando l'incantatore arriva al 5° livello (2d12), 11° livello (3d12) e 17° livello (4d12)." },
  "Spruzzo Acido": { livello:0, scuola:"Invocazione", classi:["Artefice","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", danno:"1d6", tipoDanno:"Acido", desc:"L'incantatore scaglia una bolla di acido,scegliendo una creatura entro gittata oppure due creature entro gittata situate a non più di 1,5 metri l'una dall'altra.\n\nUn bersaglio deve superare un tiro salvezza su Destrezza, altrimenti subisce 1d6 danni da acido.\n\nI danni di questo incantesimo aumentano di 1d6 quando l'incantatore arriva al 5° livello (2d6), 11° livello (3d6) e 17° livello (4d6)." },
  "Stabilizzare": { livello:0, scuola:"Necromanzia", classi:["Chierico","Druido"], tempo:"1 Azione", gittata:"Tocco", desc:"L'incantatore tocca una creatura vivente a 0 punti ferita.\n\nQuella creatura diventa stabile.\n\nQuesto incantesimo non ha effetto sui costrutti o sui non morti." },
  "Taumaturgia": { livello:0, scuola:"Trasmutazione", classi:["Chierico"], tempo:"1 Azione", gittata:"9m", desc:"L'incantatore genera una meraviglia minore, una manifestazione di potere soprannaturale. Può creare uno degli effetti magici seguenti entro gittata:\n\n- La sua voce rimbomba con potenza tre volte superiore rispetto al normale per 1 minuto.\n\n- L'incantatore fa in modo che una fiamma tremi, si intensifichi, si affievolisca o cambi colore per 1 minuto.\n\n- L'incantatore genera un tremito innocuo sul terreno per 1 minuto.\n\n- L'incantatore crea un suono istantaneo che abbia origine da un punto entro gittata a sua scelta, come un rombo di tuono, il verso di un corvo o un sinistro sussurro.\n\n- L'incantatore fa in modo che una porta o una finestra non chiusa a chiave si spalanchi o si chiuda di colpo da sola.\n\n- L'incantatore altera l'aspetto dei suoi occhi per 1 minuto.\n\nSe l'incantatore lancia questo incantesimo più volte, può mantenere attivi fino a tre dei suoi effetti da 1 minuto simultaneamente e può congedare uno di quegli effetti con un'azione." },
  "Stretta Folgorante": { livello:0, scuola:"Invocazione", classi:["Artefice","Mago","Stregone"], tempo:"1 Azione", gittata:"Tocco", danno:"1d8", tipoDanno:"Fulmine", desc:"Un fulmine si sprigiona dalla mano dell'incantatore per trasmettere una scarica folgorante a una creatura da lui toccata.\n\nL'incantatore effettua un attacco in mischia con questo incantesimo contro il bersaglio.\n\nSe il bersaglio indossa un'armatura fatta di metallo l'incantatore dispone di vantaggio.\n\nSe colpisce, il bersaglio subisce 1d8 danni da fulmine e non può effettuare reazioni fino all'inizio del suo turno successivo.\n\nI danni di questo incantesimo aumentano di 1d8 quando l'incantatore arriva al 5° livello (2d8), 11° livello (3d8) e 17° livello (4d8)." },
  "Tocco Gelido": { livello:0, scuola:"Necromanzia", classi:["Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"36m", danno:"1d8", tipoDanno:"Necrotico", desc:"L'incantatore crea una mano scheletrica e spettrale nello spazio di una creatura entro gittata, effettuando un attacco a distanza con questo incantesimo contro quella creatura per colpirla con un flusso di gelo sepolcrale.\n\nSe viene colpito, il bersaglio subisce 1d8 danni necrotici e non può recuperare punti ferita fino all'inizio del turno successivo dell'incantatore. Fino ad allora, la mano si avvinghia al bersaglio.\n\nSe l'incantatore colpisce un bersaglio non morto, quel bersaglio subisce anche svantaggio ai suoi tiri per colpire contro l'incantatore fino alla fine del turno successivo di quest'ultimo.\n\nI danni di questo incantesimo aumentano di 1d8 quando l'incantatore arriva al 5° livello (2d8), 11° livello (3d8) e 17° livello (4d8)." },
  "Stregoneria Esplosiva": { livello:0, scuola:"Invocazione", classi:["Stregone"], tempo:"1 Azione", gittata:"36m", danno:"1d8", tipoDanno:"Variabile", desc:"L'incantatore proietta energia stregonesca verso una creatura o un oggetto entro gittata, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 1d8 danni di un tipo a scelta tra: acido, freddo, fuoco, fulmine, psichici, tuono o veleno. Se l'incantatore ottiene il risultato 8 su un d8, può tirare un altro d8 e aggiungere il risultato ai danni. Quando lancia l'incantesimo, l'incantatore può aggiungere ai danni dell'incantesimo un numero di d8 pari al suo modificatore di caratteristica da incantatore. Trucchetto potenziato. I danni di questo incantesimo aumentano di 1d8 quando l'incantatore raggiunge il 5º livello (2d8), l'11º livello (3d8) e il 17º livello (4d8).\n\n**Potenziamento per i Trucchetti.** I danni di questo incantesimo aumentano di 1d8 quando l'incantatore raggiunge il 5º livello (2d8), l'11º livello (3d8) e il 17º livello (4d8)." },
  "Ammaliare Persone": { livello:1, scuola:"Ammaliamento", classi:["Bardo","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"9m", desc:"L'incantatore tenta di affascinare un umanoide entro gittata e che egli sia in grado di vedere. L'umanoide deve effettuare un tiro salvezza su Saggezza e dispone di vantaggio se l'incantatore o i suoi compagni stanno combattendo contro di lui. Se lo fallisce, è affascinato dall'incantatore finché l'incantesimo non termina o finché l'incantatore o i suoi compagni non lo danneggiano in qualche modo. La creatura affascinata considera l'incantatore una figura conosciuta e amichevole. Quando l'incantesimo termina, la creatura capirà di essere stata affascinata dall'incantatore." },
  "Assorbire Elementi": { livello:1, scuola:"Abiurazione", classi:["Artefice","Druido","Mago","Ranger","Stregone"], tempo:"Reazione", gittata:"Sé stesso", danno:"1d6", tipoDanno:"Elementale", desc:"L'incantesimo cattura parte dell'energia in arrivo, attenuandone l'effetto su di te e immagazzinandola per il tuo prossimo attacco in mischia. Hai resistenza al tipo di danno scatenante (acido, freddo, fuoco, fulmine o tuono) fino all'inizio del tuo prossimo turno. Inoltre, la prima volta che colpisci con un attacco in mischia nel tuo prossimo turno, il bersaglio subisce 1d6 danni extra del tipo scatenante, e l'incantesimo ha termine.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, il danno extra aumenta di 1d6 per ogni slot di livello superiore al 1°." },
  "Armatura di Agathys": { livello:1, scuola:"Abiurazione", classi:["Warlock"], tempo:"1 Azione", gittata:"Sé stesso", danno:"5", tipoDanno:"Freddo", desc:"Una brina spettrale ti circonda, manifestandosi come gelo brillante sui tuoi abiti e il tuo equipaggiamento. Ottieni 5 punti ferita temporanei per la durata dell'incantesimo (1 ora). Se una creatura ti colpisce con un attacco in mischia mentre possiedi ancora questi punti ferita temporanei, la creatura subisce 5 danni da freddo.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, sia i punti ferita temporanei che i danni da freddo aumentano di 5 per ogni slot di livello superiore al 1°." },
  "Armatura Magica": { livello:1, scuola:"Abiurazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"Tocco", desc:"L'incantatore tocca una creatura consenziente che non indossi un'armatura, e una forza magica protettiva circonda quella creatura finché l'incantesimo non termina. La CA base del bersaglio diventa 13 + il suo modificatore di Destrezza. L'incantesimo termina se il bersaglio indossa un'armatura o se l'incantatore interrompe l'incantesimo con un'azione." },
  "Bacche Nutrienti": { livello:1, scuola:"Trasmutazione", classi:["Druido","Ranger"], tempo:"1 Azione", gittata:"Tocco", desc:"Fino a dieci bacche compaiono in mano all'incantatore e sono pervase di magia per la durata dell'incantesimo. Una creatura può usare la sua azione per mangiare una bacca. Mangiare una bacca ripristina 1 punto ferita e la bacca fornisce nutrimento sufficiente a sfamare una creatura per un giorno. Le bacche perdono il loro potere se non vengono mangiate entro 24 ore dal lancio di questo incantesimo." },
  "Benedizione": { livello:1, scuola:"Incantesimo", classi:["Chierico","Paladino"], tempo:"1 Azione", gittata:"9m", conc:true, desc:"fino a 1 minuto L'incantatore benedice fino a tre creature entro gittata. Se un bersaglio effettua un tiro per colpire o un tiro salvezza prima del termine dell'incantesimo, il bersaglio aggiunge a essi 1d4. Utilizzo di uno slot incantesimo di livello superiore. L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º.\n\n**Ai Livelli Superiori.** L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º." },
  "Braccia di Hadar": { livello:1, scuola:"Evocazione", classi:["Warlock"], tempo:"1 Azione", gittata:"Sé stesso", area:"Sfera", danno:"2d6", tipoDanno:"Necrotico", desc:"Invochi il potere di Hadar, l'Astro Oscuro. Viticci d'ombra erompono da te investendo un raggio di 3 metri. Ogni creatura in quell'area deve effettuare un tiro salvezza su Forza. Se lo fallisce, subisce 2d6 danni necrotici e non può compiere reazioni fino all'inizio del suo turno successivo. Se supera il tiro salvezza, subisce solo la metà di quei danni e non subisce altri effetti.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 1°." },
  "Caduta Morbida": { livello:1, scuola:"Trasmutazione", classi:["Bardo","Druido","Mago","Ranger","Stregone","Warlock"], tempo:"Reazione", gittata:"18m", desc:"L'incantatore sceglie fino a cinque creature in caduta entro gittata. La velocità di discesa di una creatura in caduta rallenta fino a 18 metri per round finché l'incantesimo non termina. Se la creatura atterra prima che l'incantesimo termini, essa non subisce alcun danno da caduta e può atterrare in piedi, e l'incantesimo termina per quella creatura." },
  "Calderone Caustico di Tasha": { livello:1, scuola:"Invocazione", classi:["Artefice","Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso (linea 9m)", area:"Linea", danno:"2d4", tipoDanno:"Acido", desc:"Un getto di acido corrosivo fuoriesce dalle tue mani protese in una linea lunga 9 metri e larga 1,5 metri in una direzione a tua scelta. Ogni creatura nella linea deve superare un tiro salvezza su Destrezza, altrimenti viene ricoperta di acido. Una creatura ricoperta di acido subisce 2d4 danni da acido all'inizio di ogni suo turno. La creatura ricoperta, o un'altra creatura a portata entro 1,5 metri da essa, può usare un'azione per raschiare via o risciacquare l'acido, terminando l'effetto.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 2d4 per ogni slot di livello superiore al 1°." },
  "Camuffarsi": { livello:1, scuola:"Illusione", classi:["Bardo","Mago","Ranger","Stregone"], tempo:"1 Azione", gittata:"Sé stesso", desc:"L'incantatore assume un aspetto diverso (che include i suoi abiti, armatura, armi e altri oggetti personali presenti sulla sua persona) per la durata dell'incantesimo o finché egli non usa la sua azione per terminarlo. Può apparire 30 cm più alto o più basso e apparire magro, grasso o di corporatura normale. Non può cambiare il suo tipo di corpo, quindi deve adottare una forma che usi la stessa disposizione basilare degli arti. Entro questi limiti, la natura dell'illusione dipende da lui. I cambiamenti apportati da questo incantesimo non passano il vaglio di un'ispezione fisica. Per esempio, se l'incantatore usa questo incantesimo per aggiungere un cappello in testa, gli oggetti passerebbero attraverso il cappello e chiunque tocchi l'incantatore non sentirebbe nulla o toccherebbe la testa e i capelli dell'incantatore. Se l'incantatore usa questo incantesimo per apparire più magro rispetto alla realtà, quando qualcuno protende la mano per toccarlo, urta l'incantatore quando la sua mano è apparentemente ancora a mezz'aria. Per capire che l'incantatore è camuffato, una creatura può usare la sua azione per ispezionare il suo aspetto e deve superare una prova di Intelligenza (Indagare) contro la CD del tiro salvezza dell'incantesimo." },
  "Colpo Ardente": { livello:1, scuola:"Invocazione", classi:["Paladino","Ranger"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"1d6", tipoDanno:"Fuoco", conc:true, desc:"La tua arma da mischia si accende di un calore rovente mentre pronunci una preghiera di giudizio. La prossima volta che colpisci una creatura con un attacco con arma da mischia prima del termine dell'incantesimo (concentrazione, fino a 1 minuto), l'arma infligge 1d6 danni da fuoco extra al bersaglio e lo incendia. All'inizio di ogni suo turno finché l'incantesimo non termina, il bersaglio deve effettuare un tiro salvezza su Costituzione: se fallisce, subisce 1d6 danni da fuoco; se lo supera, l'incantesimo ha termine. Il bersaglio o una creatura entro 1,5 metri può anche spegnere le fiamme come azione.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni da fuoco extra iniziali inflitti dall'attacco aumentano di 1d6 per ogni slot di livello superiore al 1°." },
  "Colpo Intrappolante": { livello:1, scuola:"Evocazione", classi:["Ranger"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"1d6", tipoDanno:"Perforante", conc:true, desc:"fino a 1 minuto Quando l'incantatore colpisce il bersaglio, su di esso appare un groviglio di rampicanti. Il bersaglio effettua un tiro salvezza su Forza, disponendo di vantaggio a questo tiro se è una creatura di taglia Grande o superiore. Se lo fallisce, il bersaglio è trattenuto fino al termine dell'incantesimo. Se lo supera, i rampicanti si ritraggono e avvizziscono, ponendo fine all'incantesimo. Finché è trattenuto, il bersaglio subisce 1d6 danni perforanti all'inizio di ogni suo turno. Il bersaglio o una creatura alla sua portata può usare un'azione per effettuare una prova di Forza (Atletica) contro la CD del tiro salvezza sull'incantesimo. In caso di successo, l'incantesimo termina. Utilizzo di uno slot incantesimo di livello superiore. I danni aumentano di 1d6 per ogni slot di livello superiore al 1º.\n\n**Ai Livelli Superiori.** I danni aumentano di 1d6 per ogni slot di livello superiore al 1º." },
  "Colpo Irato": { livello:1, scuola:"Invocazione", classi:["Paladino","Ranger"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"1d6", tipoDanno:"Psichico", conc:true, desc:"La tua arma si carica di furia spettrale. La prossima volta che colpisci con un attacco con arma da mischia prima del termine dell'incantesimo (concentrazione, fino a 1 minuto), l'attacco infligge 1d6 danni psichici extra al bersaglio. Inoltre, se il bersaglio è una creatura, deve superare un tiro salvezza su Saggezza, altrimenti è spaventato da te fino al termine dell'incantesimo. Con un'azione nel proprio turno, la creatura può effettuare una prova di Saggezza contro la CD dei tuoi incantesimi per riacquistare la calma e terminare l'incantesimo.\n\n**Ai Livelli Superiori.** Nelle regole 2024, i danni aumentano di 1d6 per ogni livello di slot superiore al 1°." },
  "Colpo Tonante": { livello:1, scuola:"Invocazione", classi:["Paladino","Ranger"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"2d6", tipoDanno:"Tuono", conc:true, desc:"La tua arma risuona di energia tonante. La prossima volta che colpisci con un attacco con arma da mischia prima del termine dell'incantesimo (concentrazione, fino a 1 minuto), l'arma risuona con un boato fragoroso udibile fino a 90 metri da te, e l'attacco infligge 2d6 danni da tuono extra al bersaglio. Inoltre, se il bersaglio è una creatura, deve superare un tiro salvezza su Forza, altrimenti viene spinto lontano da te di 3 metri e cade prono." },
  "Comando": { livello:1, scuola:"Ammaliamento", classi:["Chierico","Paladino","Warlock"], tempo:"1 Azione", gittata:"18m", desc:"L'incantatore rivolge un comando di una parola a una creatura entro gittata e che egli sia in grado di vedere. li bersaglio deve superare un tiro salvezza su Saggezza, altrimenti obbedirà al comando nel proprio turno successivo. L'incantesimo non ha effetto se il bersaglio è un non morto, se non capisce il linguaggio dell'incantatore o se il comando di quest'ultimo si rivela dannoso in modo diretto. Di seguito sono descritti alcuni tipici comandi assieme ai loro effetti. L'incantatore può impartire un comando diverso da quelli descritti di seguito. In quel caso è il DM a determinare come si comporta il bersaglio. Se il bersaglio non può eseguire il comando, l'incantesimo termina.\n\n**Avvicinati.** Il bersaglio si muove verso l'incantatore seguendo il percorso più breve e diretto, terminando il suo turno se giunge entro 1.5 metri da lui.\n\n**Fermo**. Il bersaglio non si muove e non effettua azioni. Una creatura volante rimane in aria, se è in grado di farlo. Se deve muoversi per rimanere in aria, vola della distanza minima richiesta per rimanere in aria. FuUJ, Il bersaglio usa il suo turno per allontanarsi dall'incantatore nel modo più rapido possibile.\n\n**Lascia**. Il bersaglio lascia cadere ciò che stava impugnando, poi termina il suo turno.\n\n**Supplica**. Il bersaglio cade a terra prono e termina il suo turno.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può influenzare una creatura aggiuntiva per ogni slot di livello superiore al l°. Le creature devono trovarsi a non più di 9 metri l'una dall'altra quando l'incantatore le bersaglia." },
  "Comprendere Linguaggi": { livello:1, scuola:"Divinazione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso", rituale:true, desc:"Per la durata dell'incantesimo, l'incantatore comprende il significato letterale di qualsiasi linguaggio parlato che è in grado di sentire. Comprende inoltre ogni linguaggio scritto che è in grado di vedere, ma deve toccare la superficie su cui sono scritte le parole. È necessario circa I minuto per leggere una pagina di testo. Questo incantesimo non decodifica i messaggi segreti di un testo o di un glifo, come un sigillo arcano, che non faccia parte di un linguaggio scritto." },
  "Comprensione dei Linguaggi": { livello:1, scuola:"Divinazione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso", rituale:true, desc:"Per la durata dell'incantesimo, l'incantatore comprende il significato letterale di qualsiasi linguaggio parlato che è in grado di sentire. Comprende inoltre ogni linguaggio scritto che è in grado di vedere, ma deve toccare la superficie su cui sono scritte le parole. È necessario circa I minuto per leggere una pagina di testo. Questo incantesimo non decodifica i messaggi segreti di un testo o di un glifo, come un sigillo arcano, che non faccia parte di un linguaggio scritto." },
  "Cura Ferite": { livello:1, scuola:"Invocazione", classi:["Bardo","Chierico","Druido","Paladino","Ranger"], tempo:"1 Azione", gittata:"Tocco", danno:"2d8", tipoDanno:"Guarigione", desc:"Una creatura toccata dall'incantatore recupera un numero di punti ferita pari a 1d8 + il modificatore di caratteristica da incantatore. Questo incantesimo non ha effetto sui costrutti o sui non morti.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, la guarigione aumenta di 1d8 per ogni slot di livello superiore al 1°." },
  "Dardo Guida": { livello:1, scuola:"Invocazione", classi:["Bardo","Chierico"], tempo:"1 Azione", gittata:"36m", danno:"4d6", tipoDanno:"Radiante", desc:"Effettua un attacco di incantesimo a distanza contro una creatura che puoi vedere. In un colpo, il bersaglio subisce 4d6 danni radiosi, e prima della fine del prossimo turno dell'incantatore, il successivo tiro di attacco effettuato su di esso viene compiuto con vantaggio.\n\n**Ai Livelli Superiori.** Il danno aumenta di 1d6 per ogni livello di slot superiore al 1°." },
  "Dardo Incantato": { livello:1, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"36m", danno:"1d4+1", tipoDanno:"Forza", desc:"L'incantatore crea tre dardi lucenti di forza magica.\n\nOgni dardo colpisce una creatura scelta dall'incantatore, situata entro gittata e che egli sia in grado di vedere.\n\nUn dardo infligge 1d4+1 danni da forza al suo bersaglio.\n\nTutti i dardi colpiscono simultaneamente e l'incantatore può dirigerli per colpire una sola creatura o più creature.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, l'incantesimo crea un dardo aggiuntivo per ogni slot di livello superiore al 1°." },
  "Eroismo": { livello:1, scuola:"Ammaliamento", classi:["Bardo","Paladino"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"Una creatura consenziente toccata dall'incantatore è animata da un grande coraggio. Finché l'incantesimo non termina, la creatura è immune alla condizione di spaventato e ottiene un ammontare di punti ferita temporanei pari al modificatore di caratteristica da incantatore all'inizio di ogni proprio turno. Quando l'incantesimo termina, il bersaglio perde tutti i punti ferita temporanei rimanenti forniti da questo incantesimo.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, l'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1°." },
  "Falsa Vita": { livello:1, scuola:"Necromanzia", classi:["Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso", desc:"L'incantatore si rafforza con un duplicato necromantico di vita e ottiene 1d4+4 punti ferita temporanei per la durata dell'incantesimo.\n\n**Ai livelli Superiori.** quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, ottiene 5 punti ferita temporanei per ogni slot di livello superiore al 1°." },
  "Favore Divino": { livello:1, scuola:"Invocazione", classi:["Paladino"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"1d4", tipoDanno:"Radiante", conc:true, desc:"Intonando una preghiera, l'incantatore è pervaso da un alone radioso di luce divina.Finché l'incantesimo non termina, i suoi attacchi con le armi infliggono 1d4 danni radiosi extra se colpiscono." },
  "Fulmine Stregato": { livello:1, scuola:"Invocazione", classi:["Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"9m", danno:"1d12", tipoDanno:"Fulmine", conc:true, desc:"Un raggio scoppiettante di energia azzurra balza verso una creatura visibile entro gittata (9 metri). Effettui un attacco con incantesimo a distanza contro quel bersaglio. Se colpisci, il bersaglio subisce 1d12 danni da fulmine, e per la durata (concentrazione, fino a 1 minuto) puoi usare la tua azione in ogni tuo turno successivo per infliggere automaticamente 1d12 danni da fulmine al bersaglio. L'incantesimo termina se usi la tua azione per fare qualsiasi altra cosa, se il bersaglio esce dalla gittata o se ottiene copertura totale rispetto a te.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, il danno iniziale aumenta di 1d12 per ogni slot di livello superiore al 1°." },
  "Fuoco Fatato": { livello:1, scuola:"Invocazione", classi:["Bardo","Druido","Warlock"], tempo:"1 Azione", gittata:"18m", area:"Cubo", conc:true, desc:"Ogni oggetto contenuto in un cubo con spigolo di 6 metri entro gittata viene evidenziato da un alone di luce blu, verde o viola (a scelta dell'incantatore).\n\nOgni creatura situata entro l'area quando l'incantesimo viene lanciato, viene a sua volta evidenziata dall'alone di luce se fallisce un tiro salvezza su Destrezza.\n\nPer la durata dell'incantesimo, gli oggetti e le creature influenzate proiettano luce fioca entro un raggio di 3 metri.\n\nOgni tiro per colpire contro una creatura o un oggetto influenzato dispone di vantaggio se l'attaccante è in grado di vederlo, e la creatura o l'oggetto influenzato non trae beneficio dal fatto di essere invisibile." },
  "Identificare": { livello:1, scuola:"Divinazione", classi:["Bardo","Mago"], tempo:"1 min", gittata:"Tocco", rituale:true, desc:"L'incantatore sceglie un oggetto che deve toccare durante il lancio dell'incantesimo.\n\nSe si tratta di un oggetto magico o di un altro oggetto infuso di magia, apprende le sue proprietà e come usarlo, se necessita di sintonia per usarlo e quante cariche contiene, se ne contiene.\n\nApprende se l'oggetto è influenzato da eventuali incantesimi e quali essi siano.\n\nSe l'oggetto è stato creato da un incantesimo, l'incantatore apprende quale incantesimo l'ha creato.\n\nSe invece tocca una creatura durante il lancio dell'incantesimo, apprende quali incantesimi influenzano attualmente quella creatura, se ce ne sono." },
  "Immagine Silenziosa": { livello:1, scuola:"Illusione", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"18m", area:"Cubo", conc:true, desc:"L'incantatore crea l'immagine di un oggetto, una creatura o un altro fenomeno visibile che non sia più grande di un cubo con spigolo di 4,5 metri.\n\nL'immagine appare in un punto situato entro gitata e permane per la durata dell'incantesimo.\n\nL'immagine è puramente visiva; non è accompagnata da suoni, odori o altri effetti sensoriali.\n\nL'incantatore può usare la sua azione per fare in modo che l'immagine si muova fino a qualsiasi altro punto entro gittata. Quando l'immagine cambia luogo, l'incantatore può alterare il suo aspetto in modo che il movimento appaia naturale per l'immagine. Per esempio, se crea l'immagine di una creatura e decide di muoverla, può alterare l'immagine in modo che sembri camminare.\n\nUn'interazione fisica con l'immagine rivela che si tratta di un'illusione, in quanto gli oggetti vi passano attraverso.\n\nUna creatura che usa la sua azione per esaminare l'immagine può determinare che si tratta di un'illusione superando una prova di Intelligenza (Indagare) contro la CD del tiro salvezza dell'incantesimo.\n\nSe una creatura discerne l'illusione per ciò che è, riesce a vedere attraverso l'immagine." },
  "Individuazione del Magico": { livello:1, scuola:"Divinazione", classi:["Bardo","Chierico","Druido","Mago","Paladino","Ranger","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso (9m)", conc:true, rituale:true, desc:"Per la durata dell'incantesimo, l'incantatore percepisce la presenza della magia entro 9 metri da lui. Se percepisce la magia in questo modo, può usare la sua azione per vedere una debole aura attorno a ogni creatura o oggetto visibile nell'area e che contenga magia, e apprende di che scuola di magia si tratta, se ne esiste una. L'incantesimo può penetrare la maggior parte delle barriere, ma è bloccato da 30 cm di pietra, 2,5 cm di metallo comune, una sottile lamina di piombo o 90cm di legno o terriccio." },
  "Infliggere Ferite": { livello:1, scuola:"Necromanzia", classi:["Chierico"], tempo:"1 Azione", gittata:"Tocco", danno:"3d10", tipoDanno:"Necrotico", desc:"Effettua un attacco incantesimo corpo a corpo contro una creatura che puoi raggiungere. In caso di successo, il bersaglio subisce un danno necrotico di 3d10.\n\n**Ai Livelli Superiori.** Quando lanci questa magia usando uno slot incantesimo di 2° livello o superiore, il danno aumenta di 1d10 per ogni livello di slot superiore al 1°." },
  "Intralciare": { livello:1, scuola:"Evocazione", classi:["Druido","Ranger"], tempo:"1 Azione", gittata:"27m", area:"Quadrato", conc:true, desc:"Erbacce e rampicanti spuntano dal terreno in un quadrato con lato di 6 metri che parte da un punto situato entro gittata. Per la durata dell'incantesimo, questi vegetali trasformano l'area in terreno difficile.\n\nUna creatura situata nell'area quando l'incantatore lancia questo incantesimo deve superare un tiro salvezza su Forza, altrimenti è trattenuta dai vegetali intralcianti finché l'incantesimo non termina. Una creatura trattenuta dai vegetali può usare la sua azione per effettuare una prova di Forza contro la CD del tiro salvezza dell'incantesimo. Se ha successo, si libera.\n\nQuando l'incantesimo termina, i vegetali evocati avvizziscono." },
  "Malocchio": { livello:1, scuola:"Ammaliamento", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"Azione Bonus", gittata:"27m", danno:"1d6", tipoDanno:"Necrotico", conc:true, desc:"Poni una maledizione su una creatura visibile entro gittata (27 metri). Fino al termine dell'incantesimo (concentrazione, fino a 1 ora), infliggi 1d6 danni necrotici extra al bersaglio ogni volta che lo colpisci con un attacco. Inoltre, scegli una caratteristica quando lanci l'incantesimo: il bersaglio ha svantaggio alle prove di caratteristica effettuate con la caratteristica scelta.\n\nSe il bersaglio scende a 0 punti ferita prima del termine dell'incantesimo, puoi usare un'azione bonus in un tuo turno successivo per maledire una nuova creatura.\n\n**Ai Livelli Superiori.** Con slot di 3° o 4° livello, la concentrazione dura fino a 8 ore. Con slot di 5° livello o superiore, dura fino a 24 ore." },
  "Mani Brucianti": { livello:1, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso (cono 4,5m)", area:"Cono", danno:"3d6", tipoDanno:"Fuoco", desc:"L'incantatore apre le mani, punta i pollici l'uno contro l'altro e dalla punta delle sue dita protese si propaga un sottile velo di fiamme.\n\nOgni creatura entro un cono di 4,5 metri deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 3d6 danni da fuoco, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nIl fuoco incendia ogni oggetto infiammabile nell'area che non sia indossato o trasportato.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 1°." },
  "Marchio del Cacciatore": { livello:1, scuola:"Divinazione", classi:["Ranger"], tempo:"Azione Bonus", gittata:"27m", danno:"1d6", tipoDanno:"Variabile", conc:true, desc:"L'incantatore sceglie una creatura entro gittata e che egli sia in grado di vedere e la marchia misticamente come sua preda.\n\nFinché l'incantesimo non termina, l'incantatore infligge 1d6 danni extra al bersaglio ogni volta che lo colpisce con un attacco con un'arma e dispone vantaggio ad ogni prova di Saggezza (Percezione) o Saggezza (Sopravvivenza) effettuata per trovarlo.\n\nSe il bersaglio scende a 0 punti ferita prima che questo incantesimo termini l'incantatore può usare un'azione bonus in un suo turno successivo per marchiare una nuova creatura.\n\n**Ai Livelli Superiori.* ***Se l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o 4° livello, può mantenere una concentrazione sull'incantesimo fino ad un massimo di 8 ore. Quando usa uno slot di 5° livello o superiore, può mantenere una concentrazione sull'incantesimo fino ad un massimo di 24 ore." },
  "Nube di Nebbia": { livello:1, scuola:"Evocazione", classi:["Druido","Mago","Ranger","Stregone"], tempo:"1 Azione", gittata:"36m", area:"Sfera", conc:true, desc:"L'incantatore crea una sfera di nebbia del raggio di 6 metri centrata su un punto entro gittata.\n\nLa sfera si diffonde oltre gli angoli e la sua area risulta pesantemente oscurata. La nebbia permane per la durata dell'incantesimo o finché un vento moderato o superiore (almeno 15 km all'ora) non la disperde.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, il raggio della sfera di nebbia aumenta di 6 metri per ogni slot di livello superiore al 1°." },
  "Onda Tonante": { livello:1, scuola:"Invocazione", classi:["Bardo","Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso (cubo 4,5m)", area:"Cubo", danno:"2d8", tipoDanno:"Tuono", desc:"Un'ondata di energia tonante si propaga dall'incantatore.\n\nOgni creatura entro un cubo con spigolo di 4,5 metri originato dall'incantatore deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 2d8 danni da tuono e viene spinta di 3 metri più lontana dall'incantatore, mentre se lo supera, subisce soltanto la metà di quei danni e non viene spinta. Inoltre, gli oggetti non fissati e completamente situati all'interno dell'area di effetto vengono automaticamente spinti 3 metri più lontani dall'incantatore a seguito dell'effetto dell'incantesimo.\n\nL'incantesimo emette un rombo tonante udibile fino a 90 metri di distanza.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello osuperiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 1°." },
  "Parlare con gli Animali": { livello:1, scuola:"Divinazione", classi:["Bardo","Druido","Ranger"], tempo:"1 Azione", gittata:"Sé stesso", rituale:true, desc:"L'incantatore ottiene la capacità di comprendere le bestie e comunicare verbalmente con loro per la durata dell'incantesimo.\n\nLe conoscenze e la consapevolezza di molte bestie sono limitate alla loro intelligenza, ma l'incantatore può apprendere da loro quanto meno alcune informazioni sui luoghi o sui mostri nelle vicinanze, o su ciò che esse sono in grado di percepire o hanno percepito nell'ultimo giorno.\n\nL'incantatore potrebbe anche persuadere una bestia a fargli un piccolo favore, a discrezione del DM." },
  "Parola di Guarigione": { livello:1, scuola:"Invocazione", classi:["Bardo","Chierico","Druido"], tempo:"Azione Bonus", gittata:"18m", danno:"2d4", tipoDanno:"Guarigione", desc:"Una creatura scelta dall'incantatore entro gittata e che egli sia in grado di vedere recupera un ammontare di punti ferita pari a 1d4 + il modificatore di caratteristica da incantatore.\n\nQuesto incantesimo non ha effetto sui costrutti o sui non morti.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, l'ammontare di guarigione aumenta di 1d4 punti ferita per ogni slot di livello superiore al 1°." },
  "Passo Lungo": { livello:1, scuola:"Trasmutazione", classi:["Bardo","Druido","Mago","Ranger"], tempo:"1 Azione", gittata:"Tocco", desc:"Trasmutazione di 1° livello\n\n- **Tempo di lancio**: 1 azione\n\n- **Gittata**: Contatto\n\n- **Componenti**: V, S, M (un pizzico di terriccio)\n\n- **Durata**: 1 ora\n\nL'incantatore tocca una creatura, la cui velocità aumenta di 3 metri finché l'incantesimo non termina.\n\n**Ai Livelli Superiori**: Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, l'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1°." },
  "Pioggia di Spine": { livello:1, scuola:"Evocazione", classi:["Ranger"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"1d10", tipoDanno:"Perforante", conc:true, desc:"La prossima volta che colpisci una creatura con un attacco con arma a distanza prima del termine dell'incantesimo (concentrazione, fino a 1 minuto), l'arma o munizione genera una pioggia di spine e rovi nel punto colpito. Oltre al normale danno dell'attacco, il bersaglio e ogni creatura entro 1,5 metri da esso devono effettuare un tiro salvezza su Destrezza. Una creatura subisce 1d10 danni perforanti se fallisce il tiro salvezza, o la metà di quei danni se lo supera.\n\n**Ai Livelli Superiori.** Se lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, il danno perforante aumenta di 1d10 per ogni slot di livello superiore al 1° (fino a un massimo di 6d10)." },
  "Protezione dal Male e dal Bene": { livello:1, scuola:"Abiurazione", classi:["Chierico","Druido","Mago","Paladino","Warlock"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"Finché l'incantesimo non termina, una creatura consenziente toccata dall'incantatore è protetta da certi tipi di creature: aberrazioni, celestiali, elementali, folletti, immondi e non morti.\n\nLa protezione conferisce vari benefici. Le creature di quei tipi subiscono svantaggio ai tiri per colpire contro il bersaglio. Inoltre il bersaglio non può essere affascinato, posseduto o spaventato da una di quelle creature. Se il bersaglio è già affascinato, posseduto o spaventato dispone vantaggio al nuovo tiro salvezza contro l'effetto rilevante." },
  "Rappresaglia Infernale": { livello:1, scuola:"Invocazione", classi:["Warlock"], tempo:"Reazione", gittata:"18m", danno:"2d10", tipoDanno:"Fuoco", desc:"L'incantatore punta l'indice contro la creatura che gli ha inferto danni e quella creatura è momentaneamente avviluppata da una cortina di fiamme infernali.\n\nLa creatura deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 2d10 danni da fuoco, mentre se lo supera, subisce soltanto la metà di quei danni.\n\n**Ai livelli superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, i danni aumentano di 1d10 per ogni slot di livello superiore al 1°." },
  "Ritirata Veloce": { livello:1, scuola:"Trasmutazione", classi:["Druido","Mago","Stregone","Warlock"], tempo:"Azione Bonus", gittata:"Sé stesso", conc:true, desc:"Questo incantesimo consente all'incantatore di muoversi a una velocità straordinaria.\n\nQuando lancia questo incantesimo, e poi come azione bonus a ogni suo turno finché l'incantesimo non termina, l'incantatore può effettuare l'azione Scatto." },
  "Rovina": { livello:1, scuola:"Ammaliamento", classi:["Bardo","Chierico"], tempo:"1 Azione", gittata:"9m", conc:true, desc:"L'incantatore sceglie fino a tre creature entro gittata e che egli sia in grado di vedere, che dovranno effettuare un tiro salvezza su Carisma. Se una creatura fallisce il suo tiro salvezza, ogni volta che effettua un tiro per colpire o un tiro salvezza prima che l'incantesimo termini deve tirare un d4 e sottrarre il numero ottenuto dal tiro per colpire o dal tiro salvezza.\n\n**Ai livelli Superiori.****.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al I°." },
  "Santuario": { livello:1, scuola:"Abiurazione", classi:["Chierico"], tempo:"Azione Bonus", gittata:"9m", desc:"L'incantatore protegge una creatura situata entro gittata dagli attacchi.\n\nFinché l'incantesimo non termina, ogni creatura che bersaglia la creatura protetta con un attacco o un incantesimo che infligge danni deve prima effettuare un tiro salvezza su Saggezza. Se lo fallisce, deve scegliere un nuovo bersaglio o perdere l'attacco.\n\nQuesto incantesimo non protegge la creatura bersaglio dagli effetti ad area come l'esplosione di una Palla di Fuoco.\n\nSe la creatura protetta effettua un attacco o lancia un incantesimo che influenza una creatura nemica, questo incantesimo termina." },
  "Scudo": { livello:1, scuola:"Abiurazione", classi:["Mago","Stregone","Warlock"], tempo:"Reazione", gittata:"Sé stesso", desc:"Una barriera di forza magica invisibile si materializza e protegge l'incantatore.\n\nFino all'inizio del proprio turno successivo, l'incantatore ottiene un bonus +5 alla CA da applicare anche all'attacco innescante e non subisce danni dall'incantesimo @Compendium[world.tutti-gli-incantesimi.iABc2VrLSFyJdy16]{Dardo Incantato}." },
  "Scudo della Fede": { livello:1, scuola:"Abiurazione", classi:["Chierico","Paladino"], tempo:"Azione Bonus", gittata:"18m", conc:true, desc:"Un campo di energia scintillante si materializza attorno a una creatura scelta dall'incantatore entro gittata, conferendole un bonus di +2 alla CA per la durata dell'incantesimo." },
  "Servitore Invisibile": { livello:1, scuola:"Evocazione", classi:["Bardo","Mago","Warlock"], tempo:"1 Azione", gittata:"18m", rituale:true, desc:"Questo incantesimo crea una forza invisibile, amorfa e priva di volontà propria che svolge i compiti più semplici su ordine dell'incantatore finché l'incantesimo non termina.\n\nIl servitore si materializza sul terreno, in uno spazio libero entro gittata. Possiede CA 10, 1 punto ferita, una Forza pari a 2 e non può attaccare. Se scende a 0 punti ferita, l'incantesimo termina.\n\nUna volta in ogni suo turno, come azione bonus, l'incantatore può ordinare mentalmente al servitore di muoversi fino a 4,5 metri e di interagire con un oggetto. Il servitore può effettuare compiti semplici come portare oggetti, pulire, riparare, ripiegare abiti, accendere fuochi, servire pietanze, versare vino e così via. Una volta impartito l'ordine, il servitore svolge il compito al meglio delle sue capacità finché non lo porta a termine, poi attende il comando successivo dell'incantatore.\n\nSe l'incantatore ordina al servitore di svolgere un compito che lo porterebbe a più di 18 metri da lui, l'incantesimo termina." },
  "Sonno": { livello:1, scuola:"Ammaliamento", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"27m", area:"Sfera", desc:"Questo incantesimo fa in modo che le creature siano vittime di un sonno magico.\n\nL'incantatore tira 5d8; il totale ottenuto è l'ammontare di creature in punti ferita che questo incantesimo può influenzare. Le creature entro 6 metri da un punto a scelta dell'incantatore situato entro gittata sono influenzate in ordine crescente dei loro punti ferita (ignorando le creature prive di sensi).\n\nA partire dalla creatura che possiede meno punti ferita attuali, ogni creatura influenzata da questo incantesimo cade priva di sensi finché l'incantesimo non termina, il dormiente non subisce danni o qualcuno non usa un'azione per scuotere o schiaffeggiare il dormiente per svegliarlo.\n\nSi sottraggono i punti ferita di ogni creatura dal totale prima di passare alla creatura con l'ammontare immediatamente superiore di punti ferita.\n\nI punti ferita di una creatura devono essere pari o inferiori al totale rimanente affinché quella creatura possa essere influenzata.\n\nLe creature non morte e quelle immuni all'essere affascinate non sono influenzate da questo incantesimo.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, tira 2d8 aggiuntivi per ogni slot di livello superiore al 1°." },
  "Sfera Cromatica": { livello:1, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"27m", danno:"3d8", tipoDanno:"Variabile", desc:"Scagli una sfera di energia elementale con diametro di 10 cm contro un bersaglio entro gittata (27 metri). Scegli un tipo di danno: acido, freddo, fuoco, fulmine, veleno o tuono. Effettui un attacco con incantesimo a distanza contro il bersaglio: se colpisci, infliggi 3d8 danni del tipo scelto.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot incantesimo di 2° livello o superiore, il danno aumenta di 1d8 per ogni slot di livello superiore al 1°." },
  "Sussurri Dissonanti": { livello:1, scuola:"Ammaliamento", classi:["Bardo","Warlock"], tempo:"1 Azione", gittata:"18m", danno:"3d6", tipoDanno:"Psichico", desc:"Una creatura a scelta dell'incantatore, situata entro gittata e che egli è in grado di vedere, sente una melodia dissonante nella sua mente. Il bersaglio effettua un tiro salvezza su Saggezza. Se lo fallisce, subisce 3d6 danni psichici e, se disponibile, deve usare immediatamente la sua reazione per muoversi fin dove la sua velocità glielo consente, percorrendo la via più sicura. In caso di successo, subisce soltanto la metà di quei danni. Utilizzo di uno slot incantesimo di livello superiore. I danni aumentano di 1d6 per ogni slot di livello superiore al 1º.\n\n**Ai Livelli Superiori.** I danni aumentano di 1d6 per ogni slot di livello superiore al 1º." },
  "Aiuto": { livello:2, scuola:"Abiurazione", classi:["Bardo","Chierico","Paladino"], tempo:"1 Azione", gittata:"9m", desc:"ore L'incantatore sceglie fino a tre creature entro gittata. I punti ferita massimi e i punti ferita attuali di ogni bersaglio aumentano di 5 per la durata dell'incantesimo. Utilizzo di uno slot incantesimo di livello superiore. I punti ferita di ciascun bersaglio aumentano di 5 per ogni slot incantesimo di livello superiore al 2º. 122 System Reference Document 5.2.1\n\n**Ai Livelli Superiori.** I punti ferita di ciascun bersaglio aumentano di 5 per ogni slot incantesimo di livello superiore al 2º. 122 System Reference Document 5.2.1" },
  "Arma Magica": { livello:2, scuola:"Trasmutazione", classi:["Mago","Paladino"], tempo:"Azione Bonus", gittata:"Tocco", conc:true, desc:"ora L'incantatore tocca un'arma non magica, e, fino al termine dell'incantesimo, quell'arma diventa un'arma magica con un bonus di +1 ai tiri per colpire e ai tiri per i danni. L'incantesimo termina in anticipo se l'incantatore lo lancia di nuovo. Utilizzo di uno slot incantesimo di livello superiore. Il bonus aumenta a +2 con uno slot incantesimo compreso tra il 3º e 5º livello. Il bonus aumenta a +3 con uno slot incantesimo di 6º livello o superiore.\n\n**Ai Livelli Superiori.** Il bonus aumenta a +2 con uno slot incantesimo compreso tra il 3º e 5º livello. Il bonus aumenta a +3 con uno slot incantesimo di 6º livello o superiore." },
  "Arma Spirituale": { livello:2, scuola:"Invocazione", classi:["Chierico"], tempo:"Azione Bonus", gittata:"18m", danno:"1d8", tipoDanno:"Forza", desc:"L'incantatore crea entro gittata un'arma fluttuante spettrale che permane per la durata dell'incantesimo o finché l'incantatore non.lancia di nuovo questo incantesimo. Quando lancia questo incantesimo, l'incantatore può effettuare un attacco in mischia con questo incantesimo contro una creatura entro 1,5 metri dall'arma. Se colpisce, il bersaglio subisce 1d8 danni da forza+ il modificatore di caratteristica da incantatore.\n\nCon un'azione bonus nel suo turno, l'incantatore può muovere l'arma di un massimo di 6 metri e ripetere l'attacco contro una creatura situata entro 1,5 metri da essa. L'arma può assumere la forma che l'incantatore preferisce. I chierici di una divinità associata a un tipo particolare di arma (come per esempio St Cuthbert, noto per la sua mazza, o Thor per il suo martello} impartiranno all'arma creata da questo incantesimo la forma di tale arma.\n\n** Ai Livelll Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o Superiore, i danni aumentano di ld8 per ogni due slot incantesimo superiori al 2•." },
  "Blocca Persone": { livello:2, scuola:"Ammaliamento", classi:["Bardo","Chierico","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"L'incantatore sceglie un umanoide entro gittata e che egli sia in grado di vedere. li bersaglio deve superare un tiro salvezza su Saggezza, altrimenti sarà paralizzato per la durata dell'incantesimo. Alla fine di ogni suo turno, il bersaglio può effettuare un altro tiro salvezza su Saggezza. Se lo supera, l'incantesimo su di esso termina.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, può bersagliare un umanoide aggiuntivo per ogni slot di livello superiore al 2°. Gli umanoidi devono trovarsi a non più di 9 metri l'uno dall'altro quando l'incantatore li bersaglia." },
  "Bussare": { livello:2, scuola:"Trasmutazione", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"18m", desc:"L'incantatore sceglie un oggetto entro gittata e che egli sia in grado di vedere. Può trattarsi di una porta, uno scrigno, un forziere, un paio di manette, un lucchetto o un altro oggetto dotato di un mezzo normale o magico per impedire l'accesso.\n\nUn bersaglio tenuto chiuso da una serratura magica, incastrato o sbarrato cessa di essere tale.\n\nSe l'oggetto è protetto da più serrature, soltanto una di esse viene sbloccata.\n\nSe l'incantatore sceglie un bersaglio tenuto chiuso da Serratura Arcana, quell'incantesimo è soppresso per 10 minuti, un periodo in cui può essere aperto e chiuso normalmente.\n\nQuando l'incantatore lancia l'incantesimo, l'oggetto emette un forte rumore simile al bussare, udibile fino a una distanza di 90 metri." },
  "Colpo Marchiante": { livello:2, scuola:"Invocazione", classi:["Paladino"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"2d6", tipoDanno:"Radiante", conc:true, desc:"La prossima volta che l'incantatore colpisce una creatura con un attacco con un'arma entro la durata di questo incantesimo, l'arma risplende di un bagliore astrale al momento di colpire.\n\nL'attacco infligge 2d6 danni radiosi extra al bersaglio, che diventa visibile se è invisibile, proietta luce fioca in un raggio di 1,5 metri attorno a sé, e non può diventare invisibile finché l'incantesimo non termina.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni extra aumentano di 1d6 per ogni slot di livello superiore al 2°." },
  "Cordone di Frecce": { livello:2, scuola:"Trasmutazione", classi:["Ranger"], tempo:"1 Azione", gittata:"Sé stesso", danno:"1d6", tipoDanno:"Perforante", desc:"Pianti quattro munizioni (frecce o dardi da balestra) non magiche nel terreno entro la tua portata e vi infondi la magia protettiva. Fino al termine dell'incantesimo (8 ore), le munizioni rimangono nascoste nel terreno. Quando una creatura diversa da te si avvicina entro 9 metri da una o più munizioni per la prima volta in un turno o vi termina il proprio turno, una munizione si lancia contro di essa.\n\nLa creatura deve superare un tiro salvezza su Destrezza o subire 1d6 danni perforanti. La munizione utilizzata viene quindi distrutta. L'incantesimo termina quando tutte e quattro le munizioni sono state scagliate.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot di 3° livello o superiore, puoi piantare due munizioni aggiuntive per ogni slot superiore al 2°." },
  "Corona della Follia": { livello:2, scuola:"Ammaliamento", classi:["Bardo","Warlock"], tempo:"1 Azione", gittata:"36m", conc:true, desc:"Un umanoide a tua scelta visibile entro gittata (36 metri) deve superare un tiro salvezza su Saggezza, altrimenti cade affascinato da te per la durata (concentrazione, fino a 1 minuto). Una corona contorta di ferro spettrale e fiamme fredde compare sulla sua testa.\n\nUna creatura affascinata in questo modo deve usare la sua azione prima di muoversi in ogni suo turno per effettuare un attacco in mischia contro un'altra creatura scelta da te a portata. Nel tuo turno devi usare la tua azione per mantenere il controllo sull'affascinato, altrimenti l'incantesimo ha termine. Il bersaglio può ripetere il tiro salvezza alla fine di ogni suo turno per liberarsi." },
  "Crescita di Spine": { livello:2, scuola:"Trasmutazione", classi:["Druido","Ranger"], tempo:"1 Azione", gittata:"45m", area:"Sfera", danno:"2d4", tipoDanno:"Perforante", conc:true, desc:"Spine e spuntoni nascono dal terreno entro un raggio di 6 metri centrato su un punto situato entro gittata.\n\nL'area diventa terreno difficile per la durata dell'incantesimo.\n\nQuando una creatura entra nell'area o si muove al suo interno, subisce 2d4 danni perforanti per ogni 1,5 metri di cui si muove.\n\nLa trasformazione del terreno è mimetizzata in modo da sembrare naturale.\n\nOgni creatura che non abbia osservato l'area al momento del lancio dell'incantesimo deve effettuare una prova di Saggezza (Percezione) contro la CD del tiro salvezza dell'incantesimo per riconoscere la pericolosità del terreno prima di entrarvi." },
  "Folata di Vento": { livello:2, scuola:"Invocazione", classi:["Druido","Mago","Ranger","Stregone"], tempo:"1 Azione", gittata:"Sé stesso (linea 18m)", area:"Linea", conc:true, desc:"Una linea di vento forte lunga 18 metri e larga 3 metri si diffonde dall'incantatore in una direzione a sua scelta per la durata dell'incantesimo.\n\nOgni creatura che inizia il suo turno su quella linea deve superare un tiro salvezza su Forza, altrimenti sarà spinta di 4,5 metri più lontana dall'incantatore, nella stessa direzione della linea. Ogni creatura sulla linea deve spendere 60 cm di movimento per ogni 30 cm di cui si muove quando cerca di avvicinarsi all'incantatore.\n\nLa folata disperde i gas e i vapori ed estingue candele, torce e simili fiamme prive di protezione nell'area. Fa tremolare le fiamme protette come quelle delle lanterne e ha una probabilità del 50% di spegnerle.\n\nCon un'azione bonus in ogni suo turno prima che l'incantesimo termini, l'incantatore può cambiare la direzione in cui la linea si diffonde da sé." },
  "Frantumare": { livello:2, scuola:"Invocazione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", area:"Sfera", danno:"3d8", tipoDanno:"Tuono", desc:"Un rumore improvviso e assordante, dolorosamente intenso, si diffonde da un punto a scelta dell'incantatore situato entro gittata.\n\nOgni creatura entro una sfera del raggio di 3 metri centrata su quel punto deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 3d8 danni da tuono, mentre se lo supera, subisce soltanto la metà di quei danni. Una creatura fatta di materiale inorganico come pietra, cristallo o metallo subisce svantaggio a questo tiro salvezza.\n\nAnche un oggetto non magico che non sia indossato o trasportato subisce i danni se si trova entro l'area dell'incantesimo.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 2°." },
  "Frusta Mentale di Tasha": { livello:2, scuola:"Ammaliamento", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"27m", danno:"3d6", tipoDanno:"Psichico", desc:"Colpisci psichicamente la mente di una creatura visibile entro gittata (27 metri). Il bersaglio deve effettuare un tiro salvezza su Intelligenza. Se fallisce, subisce 3d6 danni psichici, e fino alla fine del suo prossimo turno non può compiere reazioni, la sua velocità è dimezzata e nel suo turno può compiere solo un'azione, solo un'azione bonus o solo movimento (a sua scelta, ma una sola tra queste opzioni). Se supera il tiro salvezza, subisce metà dei danni e nessun altro effetto.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot di 3° livello o superiore, puoi bersagliare una creatura aggiuntiva entro 9 metri dalle altre per ogni slot superiore al 2°." },
  "Spada dell'Ombra": { livello:2, scuola:"Illusione", classi:["Mago","Stregone","Warlock"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"2d8", tipoDanno:"Psichico", conc:true, desc:"Intrecci fili d'ombra solida per creare una lama d'oscurità compatta nella tua mano libera. La lama dura per la durata dell'incantesimo (concentrazione, fino a 1 minuto). Conta come un'arma da mischia semplice con la quale sei competente, e possiede le proprietà Accurata, Leggera e Lancio (gittata 6/18 metri).\n\nSe colpisci con un attacco con la spada dell'ombra, infliggi 2d8 danni psichici. Quando attacchi un bersaglio situato in luce fioca o oscurità con la lama, hai vantaggio al tiro per colpire. Se lasci cadere o lanci l'arma, si dissolve alla fine del turno; puoi evocarla nuovamente nella tua mano libera come azione bonus.\n\n**Ai Livelli Superiori.** Con slot di 3° o 4° livello il danno diventa 3d8; con slot di 5° o 6° livello diventa 4d8; con slot di 7° livello o superiore diventa 5d8." },
  "Immagine Speculare": { livello:2, scuola:"Illusione", classi:["Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso", desc:"Tre duplicati illusori dell'incantatore compaiono nel suo spazio.\n\nFinché l'incantesimo non termina, i duplicati si muovono assieme a lui e imitano le sue azioni, cambiando posizione in modo che sia impossibile individuare quale immagine sia quella vera.\n\nL'incantatore può usare la sua azione per congedare i duplicati illusori.\n\nOgni volta che una creatura bersaglia l'incantatore con un attacco, l'incantatore tira un d20 per determinare se l'attacco bersaglia invece uno dei duplicati.\n\nSe l'incantatore possiede tre duplicati, deve ottenere al tiro un 6 o più per spostare il bersaglio dell'attacco su un duplicato.\n\nSe possiede due duplicati, deve ottenere al tiro un 8 o più.\n\nSe possiede un duplicato, deve ottenere al tiro un 11 o più.\n\nLa CA di un duplicato è pari a 10 + il modificatore di Destrezza dell'incantatore.\n\nSe un attacco colpisce un duplicato, esso viene distrutto.\n\nUn duplicato può essere distrutto solo da un attacco che lo colpisce. Ignora tutti gli altri danni ed effetti.\n\nL'incantesimo termina quando tutti e tre i duplicati sono distrutti.\n\nUna creatura non è influenzata da questo incantesimo se non può vedere, se si affida ai sensi diversi dalla vista, come per esempio la vista cieca, o se può percepire le illusioni come false, nel caso sia dotata di visio" },
  "Individuazione dei Pensieri": { livello:2, scuola:"Divinazione", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso (9m)", conc:true, desc:"Per la durata dell'incantesimo, l'incantatore può leggere i pensieri di certe creature.\n\nQuando lancia l'incantesimo e come sua azione in ogni turno finché l'incantesimo non termina, l'incantatore può concentrarsi su una qualsiasi creatura situata entro 9 metri da lui e che egli sia in grado di vedere.\n\nSe la creatura scelta ha un'Intelligenza pari o inferiore a 3 o non parla alcun linguaggio, non può essere influenzata dall'incantesimo.\n\nAll'inizio l'incantatore apprende i pensieri superficiali della creatura (ciò a cui la creatura sta pensando in quel momento).\n\nCon un'azione, l'incantatore può trasferire la sua attenzione sui pensieri di un'altra creatura oppure tentare di sondare più a fondo la mente della stessa creatura. Se sonda più a fondo, il bersaglio deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, all'incantatore vengono rivelati i suoi ragionamenti (se ne fa), il suo stato emotivo e una presenza dominante nei suoi pensieri (qualcosa di cui si preoccupa, che ama o che odia). Se ha successo, l'incantesimo termina.\n\nIn ogni caso, il bersaglio è consapevole che l'incantatore sta sondando la sua mente: se l'incantatore non trasferisce la sua attenzione sui pensieri di un'altra creatura, la creatura può usare la sua azione nel proprio turno per effettuare una prova di Intelligenza contrapposta alla prova di Intelligenza dell'incantatore. Se ha successo, l'incantesimo termina.\n\nLe domande rivolte verbalmente alla creatura bersaglio plasmano naturalmente il corso dei suoi pensieri, quindi questo incantesimo è particolarmente efficace nel corso di un interrogatorio.\n\nL'incantatore può anche usare questo incantesimo per individuare la presenza di creature pensanti che non è in grado di vedere.\n\nQuando lancia l'incantesimo, o come sua azione nell'arco della durata, l'incantatore può cercare pensieri entro un raggio di 9 metri da sé. L'incantesimo può penetrare la maggior parte delle barriere, ma è bloccato da 60 cm di pietra, 5 cm di metallo diverso dal piombo o una sottile lamina di piombo. L'incantatore non può individuare una creatura con un'Intelligenza pari o inferiore a 3, o che non parli alcun linguaggio. Una volta individuata la presenza di una creatura in questo modo, l'incantatore può leggere i suoi pensieri per il resto della durata nel modo sopra descritto, anche se non è in grado di vederla; la creatura, tuttavia, deve comunque trovarsi entro gittata." },
  "Ingrandire/Ridurre": { livello:2, scuola:"Trasmutazione", classi:["Bardo","Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"9m", danno:"1d4", tipoDanno:"Forza", conc:true, desc:"L'incantatore ingrandisce o riduce una creatura o un oggetto situato entro gittata e che egli sia in grado di vedere per la durata dell'incantesimo.\n\nL'incantatore deve scegliere una creatura o un oggetto che non sia indossato o trasportato.\n\nSe il bersaglio non è consenziente, può effettuare un tiro salvezza su Costituzione. Se lo supera, l'incantesimo non ha effetto.\n\nSe il bersaglio è una creatura, tutto ciò che essa indossa e trasporta cambia taglia assieme a lei. Ogni oggetto lasciato cadere da una creatura influenzata torna immediatamente alla sua taglia normale.\n\n**Ingrandire.** La taglia del bersaglio raddoppia in tutte le sue dimensioni e i suo peso aumenta di otto volte. Questa crescita aumenta la taglia della creatura di una categoria (da Media a Grande, per esempio). Se non c'è abbastanza spazio per consentire al bersaglio di raddoppiare la sua taglia, la creatura o l'oggetto in questione sviluppa la massima taglia possibile nello spazio disponibile. Finché l'incantesimo non termina, il bersaglio dispone anche di vantaggio alle prove di Forza e ai tiri salvezza su Forza. Anche le armi del bersaglio crescono fino ad adattarsi alla nuova taglia. Finché queste armi sono ingrandite, gli attacchi effettuati dal bersaglio con queste armi infliggono 1d4 danni extra.\n\n**Ridurre.** La taglia del bersaglio si dimezza in tutte le dimensioni e il suo peso diventa un ottavo del peso normale. Questa riduzione diminuisce la taglia della creatura di una categoria (da Media a Piccola, per esempio). Finché l'incantesimo non termina, il bersaglio subisce svantaggio alle prove di Forza e ai tiri salvezza su Forza. Anche le armi del bersaglio si riducono fino ad adattarsi alla nuova taglia. Finché queste armi sono ridotte, gli attacchi effettuati dal bersaglio con queste armi infliggono 1d4 danni in meno (i danni non possono scendere a meno di 1)." },
  "Invisibilità": { livello:2, scuola:"Illusione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"Una creatura toccata dall'incantatore diventa invisibile finché l'incantesimo non termina.\n\nAnche tutto ciò che il bersaglio indossa o trasporta diventa invisibile finché rimane sulla sua persona.\n\nL'incantesimo termina per un bersaglio quando quel bersaglio attacca o lancia un incantesimo.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 2°." },
  "Legame di Protezione": { livello:2, scuola:"Abiurazione", classi:["Chierico","Paladino"], tempo:"1 Azione", gittata:"Tocco", desc:"Questo incantesimo protegge una creatura consenziente toccata dall’incantatore e crea tra i due un legame mistico che permane finché l’incantesimo non termina. Finché il bersaglio si trova entro 18 metri dall’incantatore, ottiene un bonus di +1 alla CA e ai tiri salvezza e resistenza a tutti i danni. Inoltre, ogni volta che subisce danni, l’incantatore subisce lo stesso ammontare di danni.\n\nL’incantesimo termina se l’incantatore scende a 0 punti ferita, se l’incantatore e il bersaglio si separano per più di 18 metri di distanza o se l’incantesimo viene lanciato di nuovo su una delle creature collegate. Inoltre, l’incantatore può interrompere l’incantesimo con un’azione." },
  "Levitazione": { livello:2, scuola:"Trasmutazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"Una creatura o un oggetto a scelta dell'incantatore, situato entro gittata e che egli sia in grado di vedere, si solleva verticalmente fino a 6 metri e rimane sospeso lassù per la durata dell'incantesimo.\n\nL'incantesimo può far levitare un bersaglio che pesa fino a 250 kg.\n\nUna creatura non consenziente che supera un tiro salvezza su Costituzione non subisce l'effetto dell'incantesimo\n\nIl bersaglio può muoversi soltanto spingendosi o aggrappandosi a un oggetto fisso o a una superficie entro portata (come per esempio una parete o un soffitto), che gli permette di muoversi come se stesse scalando quella superficie.\n\nL'incantatore può variare l'altitudine del bersaglio di un massimo di 6 metri in ogni direzione nel proprio turno.\n\nSe il bersaglio è l'incantatore stesso, egli può muoversi su o giù come parte del suo movimento. Altrimenti può usare la sua azione per muovere il bersaglio, che deve rimanere entro gittata.\n\nQuando l'incantesimo termina, il bersaglio scende dolcemente fluttuando fino a terra, se era ancora sospeso." },
  "Localizzare Oggetto": { livello:2, scuola:"Divinazione", classi:["Bardo","Chierico","Druido","Mago","Paladino","Ranger"], tempo:"1 Azione", gittata:"Sé stesso (300m)", conc:true, desc:"L'incantatore descrive o nomina un oggetto a lui familiare.\n\nPercepisce la direzione dell'ubicazione di quell'oggetto purché esso si trovi entro 300 metri da lui.\n\nSe l'oggetto è in movimento, l'incantatore sa in che direzione di muove.\n\nL'incantesimo può localizzare un oggetto specifico noto all'incantatore, purché l'incantatore abbia visto tale oggetto da vicino (entro 9 metri) almeno una volta.\n\nIn alternativa, l'incantesimo può localizzare l'oggetto più vicino di un tipo particolare, come un certo tipo di veste, gioiello, mobile, strumento o arma.\n\nQuesto incantesimo non può localizzare un oggetto se una cortina di piombo di qualsiasi spessore, anche una sottile lamina, blocca il percorso diretto tra l'incantatore e l'oggetto." },
  "Metallo Rovente": { livello:2, scuola:"Trasmutazione", classi:["Bardo","Druido"], tempo:"1 Azione", gittata:"18m", danno:"2d8", tipoDanno:"Fuoco", conc:true, desc:"L'incantatore sceglie un oggetto artificiale di metallo, come un'arma di metallo o un'armatura di metallo media o pesante, situato entro gittata e che egli sia in grado di vedere, e fa in modo che quell'oggetto diventi incandescente.\n\nOgni creatura a contatto fisico con l'oggetto subisce 2d8 danni da fuoco quando l'incantesimo viene lanciato.\n\nFinché l'incantesimo non termina, l'incantatore può usare un'azione bonus a ogni suo turno successivo per infliggere di nuovo quei danni.\n\nSe una creatura indossa o impugna l'oggetto e ne subisce i danni, quella creatura deve superare un tiro salvezza su Costituzione o lasciare cadere l'oggetto, se può farlo.\n\nSe non lascia cadere l'oggetto, subisce svantaggio ai tiri per colpire e alle prove di caratteristica fino all'inizio del turno successivo dell'incantatore.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 2°." },
  "Offuscamento": { livello:2, scuola:"Illusione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso", conc:true, desc:"Il corpo dell'incantatore diventa sfocato, instabile e ondeggiante agli occhi di tutti coloro che sono in grado di vederlo.\n\nPer la durata dell'incantesimo, tutte le creature subiscono svantaggio ai tiri per colpire contro di lui.\n\nUn attaccante è immune a questo effetto se non si affida alla vista, per esempio se è dotato di vista cieca o se è in grado di vedere attraverso le illusioni, per esempio tramite visione del vero." },
  "Oscurità": { livello:2, scuola:"Invocazione", classi:["Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", area:"Sfera", conc:true, desc:"L'incantatore sceglie un punto situato entro gittata da cui si diffonde un'oscurità magica che riempie una sfera del raggio di 4,5 metri per la durata dell'incantesimo.\n\nL'oscurità si diffonde oltre gli angoli.\n\nUna creatura dotata di scurovisione non è in grado di vedere attraverso questa oscurità e le luci non magiche non possono illuminarla.\n\nSe il punto scelto dall'incantatore si trova su un oggetto che egli sta impugnando o che non è indossato o trasportato da nessuno, l'oscurità si diffonde dall'oggetto e si muove assieme a esso.\n\nCoprire completamente la fonte dell'oscurità con un oggetto opaco, come una scodella o un elmo, blocca l'oscurità.\n\nSe una parte dell'area di questo incantesimo si sovrappone a un'area di luce creata da un incantesimo di 2° livello o inferiore, l'incantesimo che ha creato la luce è dissolto." },
  "Passare Senza Tracce": { livello:2, scuola:"Abiurazione", classi:["Druido","Ranger"], tempo:"1 Azione", gittata:"Sé stesso (aura 9m)", conc:true, desc:"L'incantatore è avvolto da un velo d'ombra e di silenzio che impedisce a lui e ai suoi compagni di essere individuati.\n\nPer la durata dell'incantesimo, ogni creatura da lui scelta e situata entro 9 metri da lui (incluso sé stesso) ottiene un bonus di +10 alle prove di Destrezza (Furtività) e le sue tracce sono impossibili da seguire se non tramite mezzi magici.\n\nUna creatura che riceve questo bonus non lascia impronte o altre tracce del suo passaggio" },
  "Passo Velato": { livello:2, scuola:"Evocazione", classi:["Mago","Stregone","Warlock"], tempo:"Azione Bonus", gittata:"Sé stesso (9m)", desc:"L'incantatore è avvolto per un istante da una foschia argentata e si teletrasporta di un massimo di 9 metri fino a uno spazio libero che egli sia in grado di vedere." },
  "Pelle Coriacea": { livello:2, scuola:"Trasmutazione", classi:["Druido","Mago","Ranger"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"ora 174 System Reference Document 5.2.1 L'incantatore tocca una creatura consenziente. Fino al termine dell'incantesimo, la pelle del bersaglio assume l'aspetto della corteccia. Inoltre, il bersaglio ha una Classe Armatura di 17 se la sua CA è inferiore a tale valore." },
  "Potenziare Caratteristica": { livello:2, scuola:"Trasmutazione", classi:["Bardo","Chierico","Druido","Mago"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"Conferisci un potenziamento magico ad una creatura con cui sei in contatto. Scegli uno degli effetti seguenti; il bersaglio ottiene quell’effetto fino al termine dell’incantesimo.\n\n**Astuzia della Volpe.** Il bersaglio ha vantaggio alle prove di Intelligenza.\n\n**Forza del Toro.** Il bersaglio ha vantaggio alle prove di Forza, e la sua capacità di carico raddoppia.\n\n**Grazia del Gatto.** Il bersaglio ha vantaggio alle prove di Destrezza. Inoltre, qualora non sia inabile, non subisce danni dalle cadute di 6 metri o meno.\n\n**Resistenza dell’Orso.** Il bersaglio ha vantaggio alle prove di Costituzione. Ottiene anche 2d6 punti ferita temporanei, che vengono persi alla fine dell’incantesimo.\n\n**Saggezza del Gufo.** Il bersaglio ha vantaggio alle prove di Saggezza.\n\n**Splendore dell’Aquila.** Il bersaglio ha vantaggio alle prove di Carisma.\n\n**Ai Livelli Più Alti.** Quando esegui questo incantesimo usando uno slot incantesimo di 3° livello o più alto, puoi prendere a bersaglio un’ulteriore creatura per ogni livello dello slot sopra il 2°." },
  "Preghiera di Guarigione": { livello:2, scuola:"Invocazione", classi:["Chierico"], tempo:"10 min", gittata:"9m", danno:"2d8", tipoDanno:"Guarigione", desc:"Fino a sei creature scelte dall'incantatore, situate entro gittata e che egli sia in grado di vedere, recuperano un ammontare di punti ferita a testa pari a 2d8 + il modificatore di caratteristica da incantatore.\n\nQuesto incantesimo non ha effetto su costrutti o sui non morti.\n\n**Ai Livelli Successivi. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, la guarigione aumenta di 1d8 per ogni slot di livello superiore al 2°." },
  "Presagio": { livello:2, scuola:"Divinazione", classi:["Chierico","Druido"], tempo:"1 min", gittata:"Sé stesso", rituale:true, desc:"Lanciando bastoncini incastonati di gemme o ossa di drago, rivelando carte illustrate o usando altri strumenti di divinazione, l'incantatore riceve un segno da un'entità ultraterrena riguardo al risultato di un corso d'azione specifico che intende intraprendere entro i prossimi 30 minuti.\n\nIl DM sceglie tra i seguenti presagi possibili:\n\n- Ventura, se l'azione fornisce risultati positivi\n\n- Sventura, se l'azione fornisce risultati negativi\n\n- Ventura e sventura, se l'azione fornisce sia risultati positivi che negativi\n\n- Nulla, se l'azione non fornisce risultati positivi o negativi in modo rilevante\n\nL'incantesimo non prende in considerazione quelle potenziali circostanze che potrebbero alterare l'esito, come per esempio il lancio di incantesimi aggiuntivi o la perdita o l'acquisizione di un compagno.\n\nSe l'incantatore lancia l'incantesimo due o più volte prima di completare il suo riposo lungo successivo, esiste una probabilità cumulativa del 25 per cento per ogni lancio dopo il primo di ottenere un responso casuale.\n\nIl DM effettua questo tiro in segreto." },
  "Protezione dai Veleni": { livello:2, scuola:"Abiurazione", classi:["Chierico","Druido","Paladino","Ranger"], tempo:"1 Azione", gittata:"Tocco", desc:"L'incantatore tocca una creatura, se quella creatura è avvelenata il veleno è neutralizzato. Se il bersaglio è afflitto da più veleni, l'incantatore neutralizza un veleno di cui conosce la presenza, oppure ne neutralizza uno a caso.\n\nPer la durata dell'incantesimo, il bersaglio dispone di vantaggio ai tiri salvezza per non essere avvelenato e di resistenza ai danni da veleno." },
  "Raggio di Indebolimento": { livello:2, scuola:"Necromanzia", classi:["Mago","Warlock"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"Un fascio nero di energia debilitante parte dal tuo dito diretto contro una creatura a gittata. Effettua un attacco a distanza con incantesimo contro il bersaglio. Se colpisci, il bersaglio infliggerà la metà dei danni con gli attacchi con arma che usano la Forza fino al termine dell’incantesimo.\n\nAl termine di ciascun turno del bersaglio, questi può effettuare un tiro salvezza su Costituzione contro l’incantesimo. Se lo supera, l’incantesimo ha termine." },
  "Raggio di Luna": { livello:2, scuola:"Invocazione", classi:["Druido"], tempo:"1 Azione", gittata:"36m", area:"Cilindro", danno:"2d10", tipoDanno:"Radiante", conc:true, desc:"Un bagliore argentato di luce pallida forma un cilindro del raggio di 1,5 metri e alto 12 metri, centrato su un punto entro gittata. Finché l'incantesimo non termina, il cilindro è pervaso di luce fioca. Quando una creatura entra nell'area dell'incantesimo per la prima volta in un turno o vi inizia il proprio turno, viene avvolta da una cortina di fiamme spettrali che le provocano un dolore lancinante e la obbligano a effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 2d10 danni radiosi, mentre se lo supera, subisce soltanto la metà di quei danni. Un mutaforma subisce svantaggio a questo tiro salvezza. Inoltre, se lo fallisce, riassume istantaneamente la sua forma originale e non può assumere una forma diversa finché non esce dalla luce dell'incantesimo. Nei suoi turni successivi, dopo avere lanciato questo incantesimo, l'incantatore può usare un'azione per muovere il bagliore di un massimo di 18 metri in qualsiasi direzione.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d10 per ogni slot di livello superiore al 2°." },
  "Raggio Rovente": { livello:2, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"36m", danno:"2d6", tipoDanno:"Fuoco", desc:"L'incantatore crea tre raggi di fuoco e li scaglia contro uno o più bersagli entro gittata.\n\nL'incantatore effettua un attacco a distanza con questo incantesimo per ogni raggio. Se colpisce, il bersaglio subisce 2d6 danni da fuoco.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, crea un raggio aggiuntivo per ogni slot di livello superiore al 2°." },
  "Ragnatela": { livello:2, scuola:"Evocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"18m", area:"Cubo", conc:true, desc:"L'incantatore evoca una massa di spessi e viscosi filamenti di ragnatela in un punto a sua scelta situato entro gittata.\n\nLe ragnatele riempiono un cubo con spigolo di 6 metri generato da quel punto per la durata dell'incantesimo.\n\nLe ragnatele sono terreno difficile e la loro area è considerata leggermente oscurata.\n\nSe le ragnatele non sono ancorate tra due masse solide (per esempio pareti o alberi) o stese su un pavimento, un muro o un soffitto, collassano su sé stesse e l'incantesimo termina all'inizio del turno successivo dell'incantatore.\n\nLe ragnatele stese su una superficie piatta hanno una profondità di 1,5 metri.\n\nOgni creatura che inizia il suo turno nelle ragnatele o che vi entra durante il proprio turno deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, la creatura è trattenuta fintanto che rimante tra le ragnatele o finché non si libera spezzandole.\n\nUna creatura trattenuta dalle ragnatele può usare la sua azione per effettuare una prova di Forza contro la CD del tiro salvezza dell'incantesimo. Se ha successo, non è più trattenuta.\n\nLe ragnatele sono infiammabili.\n\nUn cubo di ragnatele con spigolo di 1,5 metri brucia in 1 round, infliggendo 2d4 danni da fuoco a ogni creatura che inizi il suo turno tra le fiamme." },
  "Ristorare Inferiore": { livello:2, scuola:"Abiurazione", classi:["Bardo","Chierico","Druido","Paladino","Ranger"], tempo:"1 Azione", gittata:"Tocco", desc:"L'incantatore tocca una creatura e può porre termine a una malattia o una condizione che lo affligge tra accecato, assordato, avvelenato o paralizzato." },
  "Scurovisione": { livello:2, scuola:"Trasmutazione", classi:["Druido","Mago","Ranger","Stregone"], tempo:"1 Azione", gittata:"Tocco", desc:"L'incantatore tocca una creatura consenziente per conferirle la capacità di vedere nell'oscurità.\n\nPer la durata dell'incantesimo, quella creatura è dotata di scurovisione fino a 18 metri." },
  "Sfera Infuocata": { livello:2, scuola:"Evocazione", classi:["Druido","Mago"], tempo:"1 Azione", gittata:"18m", danno:"2d6", tipoDanno:"Fuoco", conc:true, desc:"Una sfera di fuoco del diametro di 1,5 metri appare in uno spazio libero a scelta dell'incantatore, situato entro gittata, dove permane per la durata dell'incantesimo.\n\nOgni creatura che termina il suo turno entro 1,5 metri dalla sfera deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 2d6 danni da fuoco, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nCon un'azione bonus, l'incantatore può muovere la sfera di un massimo di 9 metri.\n\nSe urta una creatura con la sfera, quella creatura deve effettuare il tiro salvezza contro i danni della sfera e la sfera non può muoversi ulteriormente per quel turno.\n\nQuando l'incantatore muove la sfera, può dirigerla oltre le barriere alte fino a 1,5 metri e farla saltare oltre le fosse larghe fino a 3 metri.\n\nLa sfera incendia gli oggetti infiammabili che non sono indossati e trasportati e proietta luce intensa entro un raggio di 6 metri e luce fioca per altri 6 metri.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 2°." },
  "Silenzio": { livello:2, scuola:"Illusione", classi:["Bardo","Chierico","Ranger"], tempo:"1 Azione", gittata:"36m", area:"Sfera", conc:true, rituale:true, desc:"L'incantatore genera una sfera del raggio di 6 metri centrata su un punto a sua scelta situato entro gittata.\n\nPer la durata dell'incantesimo, nessun suono può essere creato all'interno di quella sfera o attraversarla.\n\nOgni creatura o oggetto interamente all'interno della sfera è immune ai danni da tuono e ogni creatura interamente all'interno della sfera è assordata.\n\nAll'interno dell'area è impossibile lanciare un incantesimo che includa una componente verbale." },
  "Suggestione": { livello:2, scuola:"Ammaliamento", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"9m", conc:true, desc:"L'incantatore suggerisce un corso d'azione da intraprendere (limitandosi a una o due frasi) e influenza magicamente una creatura entro gittata e che egli sia in grado di vedere.\n\nLa creatura deve essere in grado di sentire l'incantatore e di capirlo.\n\nLe creature che non possono essere affascinate sono immuni a questo effetto.\n\nLa suggestione deve essere formulata in modo che il corso d'azione appaia ragionevole. Chiedere a una creatura di pugnalarsi, gettarsi su una lancia, immolarsi o compiere altri atti palesemente autolesionistici pone termine all'incantesimo.\n\nIl bersaglio deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, deve perseguire il corso d'azione descritto dall'incantatore al meglio delle sue capacità. Tale corso d'azione può proseguire per l'intera durata dell'incantesimo. Se l'attività suggerita può essere completata in un periodo di tempo più breve, l'incantesimo termina quando il soggetto completa ciò che gli è stato chiesto di fare. L'incantatore può anche specificare quali condizioni innescheranno un'attività speciale nel corso della durata. Per esempio, potrebbe suggerire che un cavaliere ceda il suo cavallo da guerra al primo mendicante che incontra. Se questa condizione non viene soddisfatta prima che l'incantesimo termini, quell'attività non viene effettuata.\n\nSe l'incantatore o uno dei suoi compagni infliggono danni al bersaglio, l'incantesimo termina." },
  "Trovare Destriero": { livello:2, scuola:"Evocazione", classi:["Paladino"], tempo:"10 min", gittata:"9m", desc:"L'incantatore evoca uno spirito che assume la forma di una cavalcatura insolitamente forte, intelligente e fedele, stringendo con lei un legame duraturo. La cavalcatura appare in uno spazio libero entro gittata e assume una forma a scelta dell'incantatore tra un cavallo da guerra, un pony, un cammello, un alce o un mastino. (Il DM potrebbe consentire di evocare altri animali come cavalcature.) La cavalcatura usa le statistiche della forma scelta, anche se si tratta di un celestiale, un folletto o un immondo (a scelta dell'incantatore) anziché di un tipo normale. Inoltre, se la cavalcatura ha un'Intelligenza pari o inferiore a 5, la sua Intelligenza diventa 6 e ottiene la capacità di capire un linguaggio a scelta dell'incantatore e che l'incantatore sia in grado di parlare. La cavalcatura serve l'incantatore sia in combattimento che in altri momenti, e grazie al legame istintivo che li unisce, i due combattono come un'unità perfettamente coesa. Quando l'incantatore è in sella alla cavalcatura, può fare in modo che ogni incantesimo che bersaglia solo se stesso bersagli anche la sua cavalcatura. Quando la cavalcatura scende a 0 punti ferita, scompare, non lasciandosi dietro alcuna forma fisica. L'incantatore può anche congedare la sua cavalcatura in qualsiasi momento con un'azione, facendola scomparire. In ogni caso, un nuovo lancio di questo incantesimo evocherà la stessa cavalcatura, riportata al massimo dei suoi punti ferita. Finché la cavalcatura si trova entro 1,5 km dall'incantatore, questi può comunicare con lei telepaticamente. L'incantatore non può legarsi a più di una cavalcatura alla volta tramite questo incantesimo. Con un'azione, può liberare la cavalcatura dal suo legame in qualsiasi momento, facendola scomparire." },
  "Vedere Invisibilità": { livello:2, scuola:"Divinazione", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso", desc:"Per la durata dell'incantesimo, l'incantatore vede le creature e gli oggetti invisibili come se fossero visibili e può vedere sul Piano Etereo.\n\nLe creature e gli oggetti eterei appaiono spettrali e trasparenti." },
  "Vincolo della Terra": { livello:2, scuola:"Trasmutazione", classi:["Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"90m", conc:true, desc:"Scegli una creatura visibile entro gittata (90 metri). Strisce spettrali di energia giallastra avvolgono la creatura. Il bersaglio deve superare un tiro salvezza su Forza, altrimenti per la durata (concentrazione, fino a 1 minuto) la sua velocità di volare (se presente) è ridotta a 0 metri. Se la creatura è in volo al momento del lancio, scende dolcemente verso terra a una velocità di 18 metri al round finché non atterra in piedi in sicurezza." },
  "Zona di Verità": { livello:2, scuola:"Ammaliamento", classi:["Bardo","Chierico","Paladino"], tempo:"1 Azione", gittata:"18m", area:"Sfera", desc:"- **Tempo di lancio: **1 azione\n\n- **Gittata: **18 metri\n\n- **Componenti**: V, S\n\n- **Durata**: 10 minuti\n\nL'incantatore crea una zona magica protetta dagli inganni entro una sfera di raggio di 4,5 metri centrata su un punto a sua scelta situato entro gittata. Finché l'incantesimo non termina, una creatura che entra nell'area dell'incantesimo per la prima volta in un turno o vi inizia il proprio turno deve effettuare un tiro di salvezza su Carisma. Se lo fallisce la creatura non può mentire deliberatamente finché si trova entro l'area. L'incantatore sa se ogni creatura ha superato o fallito il suo tiro salvezza.\n\nUna creatura influenzata è consapevole dell'incantesimo e può quindi evitare di rispondere alle domande a cui normalmente risponderebbe mentendo. Una tale creatura può fornire risposte sfuggenti, purché rimanga entro i confini della verità." },
  "Animare Morti": { livello:3, scuola:"Necromanzia", classi:["Chierico","Mago","Warlock"], tempo:"1 min", gittata:"3m", desc:"L'incantatore sceglie una pila di ossa o un cadavere umanoide di taglia Media o Piccola entro gittata, animandolo come creatura non morta. Il bersaglio si trasforma in uno scheletro se l'incantatore sceglie la pila di ossa, o in uno zombi se l'incantatore sceglie un cadavere (vedi \"Mostri\" per le schede delle statistiche). A ogni suo turno, l'incantatore può effettuare un'azione bonus per comandare mentalmente qualsiasi creatura creata con questo incantesimo, a patto che si trovi entro 18 metri da lui (se controlla varie creature, l'incantatore può comandarne più di una allo stesso momento, impartendo lo stesso comando a ciascuna di loro). L'incantatore decide quale azione effettuerà la creatura e dove si muoverà nel suo turno successivo, oppure può impartirle un comando generale, come restare a guardia di una stanza o un di corridoio. Se invece non impartisce alcun comando, la creatura effettua l'azione Schivata e si sposta solo per evitare di subire danni. Una volta ricevuto un ordine, la creatura continua a seguirlo finché non ha portato a termine il compito. La creatura rimane sotto il controllo dell'incantatore per 24 ore, passate le quali smette di obbedire a qualsiasi comando ulteriore. Per mantenere il controllo sulla creatura per altre 24 ore, l'incantatore deve lanciare di nuovo questo incantesimo su di essa prima che l'attuale periodo di 24 ore termini. Questo uso dell'incantesimo gli permette di ristabilire il controllo su un massimo di quattro creature da lui animate tramite questo incantesimo, anziché animarne una nuova. Utilizzo di uno slot incantesimo di livello superiore. L'incantatore anima due creature non morte aggiuntive o ristabilisce il controllo su di esse per ogni slot incantesimo di livello superiore al 3º. Ognuna delle creature deve provenire da un diverso cadavere o mucchio d'ossa.\n\n**Ai Livelli Superiori.** L'incantatore anima due creature non morte aggiuntive o ristabilisce il controllo su di esse per ogni slot incantesimo di livello superiore al 3º. Ognuna delle creature deve provenire da un diverso cadavere o mucchio d'ossa." },
  "Arma Elementale": { livello:3, scuola:"Trasmutazione", classi:["Druido","Mago","Paladino","Ranger"], tempo:"1 Azione", gittata:"Tocco", danno:"1d4", tipoDanno:"Variabile", conc:true, desc:"Tocchi un'arma non magica. Fino al termine dell'incantesimo (concentrazione, fino a 1 ora), l'arma diventa un'arma magica con un bonus di +1 ai tiri per colpire e conferisce 1d4 danni extra di un tipo a scelta tra acido, freddo, fuoco, fulmine o tuono a ogni colpo andato a segno.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot incantesimo di 5° o 6° livello, il bonus ai tiri per colpire aumenta a +2 e il danno extra diventa 2d4. Quando usi uno slot di 7° livello o superiore, il bonus diventa +3 e il danno extra diventa 3d4." },
  "Aura di Vitalità": { livello:3, scuola:"Invocazione", classi:["Paladino"], tempo:"1 Azione", gittata:"Sé stesso (aura 9m)", conc:true, desc:"Un'aura curativa con raggio di 9 metri emana da te fino al termine dell'incantesimo (concentrazione, fino a 1 minuto). Fino alla conclusione dell'incantesimo, puoi usare un'azione bonus in ogni tuo turno per far recuperare 2d6 punti ferita a una creatura a tua scelta (incluso te stesso) situata all'interno dell'aura. Questo incantesimo non ha effetto su costrutti o non morti." },
  "Camminare sull'Acqua": { livello:3, scuola:"Trasmutazione", classi:["Artefice","Chierico","Druido","Ranger","Stregone"], tempo:"1 Azione", gittata:"9m", rituale:true, desc:"ora Questo incantesimo conferisce la capacità di muoversi su una qualsiasi superficie liquida, come l'acqua, l'acido, il fango, la neve, le sabbie mobili o la lava, come se si trattasse di un innocuo terreno solido (ma le creature che attraversano un tratto di lava fusa possono comunque subire danni dal calore). Fino a dieci creature consenzienti entro gittata a scelta dell'incantatore ottengono questa capacità per la durata dell'incantesimo. Un bersaglio colpito deve usare un'azione bonus per passare dalla superficie del liquido all'interno del liquido stesso e viceversa, ma se il bersaglio cade dentro di esso passa attraverso la superficie nel liquido sottostante." },
  "Chiamare il Fulmine": { livello:3, scuola:"Invocazione", classi:["Druido"], tempo:"1 Azione", gittata:"36m", area:"Cilindro", danno:"3d10", tipoDanno:"Fulmine", conc:true, desc:"Una nube tempestosa a forma di un cilindro del raggio di 18 metri e alto 3 metri compare in un punto che l'incantatore sia in grado di vedere e situato a 30 metri direttamente sopra di lui.\n\nL'incantesimo fallisce se l'incantatore non è in grado di vedere il punto in cui la nube tempestosa potrebbe comparire (per esempio, se si trova all'interno di una stanza che non è in grado di contenere la nube).\n\nQuando l'incantatore lancia l'incantesimo, sceglie un punto entro gittata e che egli sia in grado di vedere.\n\nUna scarica di fulmini si propaga dalla nube fino a quel punto.\n\nOgni creatura entro 1,5 metri da quel punto deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 3d10 danni da fulmine, mentre se lo supera, subisce soltanto la metà di quei danni. A ogni suo turno finché l'incantesimo non termina, l'incantatore può usare la sua azione per invocare di nuovo il fulmine in questo modo, bersagliando lo stesso punto o un punto diverso.\n\nSe l'incantatore si trova all'esterno durante una tempesta quando lancia questo incantesimo, ottiene il controllo della tempesta esistente anziché crearne una nuova. In queste condizioni i danni dell'incantesimo aumentano di 1d10.\n\n**Ai Livelli Superiori**. Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d10 per ogni slot di livello superiore al 3°." },
  "Colpo Accecante": { livello:3, scuola:"Invocazione", classi:["Paladino"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"3d8", tipoDanno:"Radiante", conc:true, desc:"La tua arma risplende di un bagliore solare accecante. La prossima volta che colpisci una creatura con un attacco con arma prima del termine dell'incantesimo (concentrazione, fino a 1 minuto), l'attacco infligge 3d8 danni radianti extra al bersaglio. Inoltre, il bersaglio deve superare un tiro salvezza su Costituzione, altrimenti è accecato fino al termine dell'incantesimo.\n\nUna creatura accecata da questo incantesimo ripete il tiro salvezza alla fine di ogni suo turno; se lo supera, l'effetto di cecità ha termine." },
  "Controincantesimo": { livello:3, scuola:"Abiurazione", classi:["Mago","Stregone","Warlock"], tempo:"Reazione", gittata:"18m", desc:"L'incantatore tenta di interrompere una creatura nell'atto di lanciare un incantesimo.\n\nSe la creatura sta lanciando un incantesimo di 3° livello o inferiore, l'incantesimo della creatura fallisce e non ha effetto.\n\nSe la creatura sta lanciando un incantesimo di 4° livello o superiore, l'incantatore effettua una prova di caratteristica usando la sua caratteristica da incantatore. La CD è pari a 10 + il livello dell'incantesimo della creatura. In caso di successo, l'incantesimo della creatura fallisce e non ha effetto.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, l'incantesimo interrotto non ha effetto se il suo livello è pari o inferiore al livello dello slot incantesimo usato dall'incantatore." },
  "Crescita Vegetale": { livello:3, scuola:"Trasmutazione", classi:["Bardo","Druido","Ranger"], tempo:"1 Azione / 8 ore", gittata:"45m", desc:"Questo incantesimo incanala vitalità nei vegetali di un'area specifica.\n\nEsistono due possibili usi dell'incantesimo, mirati a fornire benefici immediati o a lungo termine.\n\nSe l'incantatore lancia questo incantesimo usando 1 azione, sceglie un punto situato entro gittata. Tutti i vegetali normali entro un raggio di 30 metri centrato su quel punto crescono rigogliosamente fino a formare un groviglio. Una creatura che si muove attraverso quell'area deve spendere 120 cm di movimento per ogni 30 cm di cui si muove.\n\nL'incantatore può escludere una o più aree di qualsiasi dimensione all'interno dell'area dell'incantesimo per fare in modo che non ne siano influenzate.\n\nSe l'incantatore lancia questo incantesimo nell'arco di 8 ore, rende la terra fertile. Tutti i vegetali entro un raggio di 750 metri centrato in un punto situato entro gittata cresceranno rigogliosamente per 1 anno.\n\nAl momento del raccolto produrranno il doppio del cibo normale." },
  "Dissolvi Magie": { livello:3, scuola:"Abiurazione", classi:["Bardo","Chierico","Druido","Mago","Paladino","Stregone","Warlock"], tempo:"1 Azione", gittata:"36m", desc:"L'incantatore sceglie una creatura, oggetto o effetto magico situato entro gittata.\n\nOgni Incantesimo di 3° livello o inferiore termina. Per ogni incantesimo di 4° livello o superiore presente sul bersaglio, l'incantatore effettua una prova di caratteristica usando la propria caratteristica da incantatore.\n\nLa CD è pari a 10 + il livello dell'incantesimo. Se supera la prova, l'incantesimo termina.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, termina automaticamente gli effetti di un incantesimo sul bersaglio se il livello di quell'incantesimo è pari o inferiore al livello dello slot incantesimo usato dall'incantatore.\n\nErrata & Chiarificazioni\nDissolvi magie termina solo gli effetti delle magie, non ha effetto su: creature già evocate, proprietà magiche di oggetti, abilità (anche simili ad un incantesimo).\n\nPer sapere se un Incantesimo è suscettibile ad essere dissolto dall'Incantesimo Dissolvi Magie basta guardare al suo tempo di lancio, se l'incantesimo è Istantaneo non può essere dissolto. Ad esempio una creatura affetta dall'incantesimo Cura Ferite se colpito da un Dissolvi Magie o da un Cono Antimagia viene comunque guarita poiché l'effetto dell'incantesimo Cura Ferite è Istantaneo.\n\nLanciare Dissolvi magie su Non morti, costrutti, Immondi, famigli, etc... termina gli effetti dell'incantesimo, non è detto che li dissolva anche se evocati dalla magia poiché essi sono il prodotto della magia non la magia in sé; per chiarificare seguire sempre la regola base: se ha come tempo di lancio Istantanea non funziona utilizzare Dissolvi Magie. Se lanciato su delle creature evocate tramite l'incantesimo Evoca Animali, dissolve una creatura, non tutte, poiché l'incantesimo ne ha evocate diverse e quelle sono l'effetto dell'incantesimo.\n\nDissolvi Magie termina qualunque effetto magico sul bersaglio, che sia positivo o nocivo, l'incantatore non può scegliere quali effetti terminare, tutti gli effetti vengono dissolti.\n\nDissolvi magie non dissolve Abilità o Privilegi di classe, lanciare Dissolvi Magie su un Paladino con un'aura attiva non termina l'effetto dell'aura; allo stesso modo lanciarlo su un Druido trasformato in Forma Selvatica non termina il suo privilegio, il Druido rimane nella sua Forma Selvatica e nulla accade." },
  "Evoca Fata": { livello:3, scuola:"Evocazione", classi:["Druido","Mago","Ranger","Warlock"], tempo:"1 Azione", gittata:"27m", conc:true, desc:"Evochi uno spirito fatato che assume una forma corporea in uno spazio libero visibile entro gittata (27 metri). La creatura dura per 1 ora (concentrazione) e scompare se scende a 0 punti ferita. È amichevole verso te e i tuoi compagni e agisce nel tuo turno subito dopo di te.\n\nScegli l'umore della fata al momento del lancio: Furente, Ingannevole o Gioiosa. In combattimento possiede CA pari a 12 + il livello dello slot, punti ferita pari a 30 + 10 per ogni livello dello slot superiore al 3°, e compie un numero di attacchi pari alla metà del livello dello slot. Infligge 1d6 + 3 + il livello dello slot danni da forza e possiede un teletrasporto con effetto bonus in base all'umore.\n\n**Ai Livelli Superiori.** Le statistiche e i punti ferita aumentano con il livello dello slot utilizzato." },
  "Evoca Ombra": { livello:3, scuola:"Evocazione", classi:["Mago","Warlock"], tempo:"1 Azione", gittata:"27m", conc:true, desc:"Evochi uno spirito delle ombre che assume una forma fisica in uno spazio libero entro gittata (27 metri). Dura per 1 ora (concentrazione). Scegli una forma: Furia, Disperazione o Paura.\n\nHa CA pari a 11 + il livello dello slot, PF pari a 35 + 15 per ogni livello dello slot superiore al 3°, resistenza ai danni necrotici e compie un numero di attacchi pari alla metà del livello dello slot. Infligge 1d12 + 3 + il livello dello slot danni da freddo o necrotici e può spaventare o rallentare i nemici adiacenti.\n\n**Ai Livelli Superiori.** Statistiche e punti ferita aumentano con il livello dello slot." },
  "Evoca Spirito Non Morto": { livello:3, scuola:"Necromanzia", classi:["Mago","Warlock"], tempo:"1 Azione", gittata:"27m", conc:true, desc:"Evochi uno spirito non morto corporeo in uno spazio libero entro gittata (27 metri). Dura per 1 ora (concentrazione). Scegli la forma: Spettrale, Scheletrica o Putrefatta.\n\nHa CA pari a 11 + il livello dello slot, PF pari a 30 + 10 per ogni livello superiore al 3°, immunità ai danni necrotici e da veleno e compie un numero di attacchi pari alla metà del livello dello slot. Gli attacchi infliggono 1d8 + 3 + il livello dello slot danni necrotici e possono paralizzare (Putrefatto) o spaventare (Spettrale) i bersagli.\n\n**Ai Livelli Superiori.** Statistiche e PF aumentano proporzionalmente allo slot." },
  "Evocare Animali": { livello:3, scuola:"Evocazione", classi:["Druido","Ranger"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"L'incantatore evoca spiriti fatati che prendono la forma di animali ed appaiono in uno spazio non occupato che egli possa vedere entro gittata. Sceglie una delle seguenti opzioni per decidere cosa appare:\n\n- Una creatura con grado sfida 2 o inferiore\n\n- Due creature con grado sfida 1 o inferiore\n\n- Quattro creature con grado sfida 1/2 o inferiore\n\n- Otto creature con grado sfida 1/4 o inferiore\n\nOgni bestia è considerata anche come Essere Fatato e scompare quando finisce a 0 punti ferita o quando finisce l'incantesimo. Le creature evocate sono amichevoli nei confronti dell'incantatore e dei suoi alleati. L'incantatore tira per l'iniziativa delle creature evocate come gruppo, che ha i propri turni. Le creature evocate obbediscono ai comandi verbali impartiti dall'incantatore (nessuna azione richiesta). Se l'incantatore non impartisce un comando, le creature evocate si difendono da eventuali altre creature ostili, ma altrimenti non intraprendono alcuna azione.\n\nIl DM possiede le statistiche delle creature.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo utilizzando determinati slot incantesimo di livello superiore, sceglie una delle opzioni di evocazione precedenti ed appare un numero maggiore di creature: il doppio utilizzando uno slot di 5° livello, il triplo utilizzando uno slot di 7° livello e il quadruplo utilizzando uno slot di 9° livello." },
  "Fame di Hadar": { livello:3, scuola:"Evocazione", classi:["Warlock"], tempo:"1 Azione", gittata:"45m", area:"Sfera", danno:"2d6", tipoDanno:"Freddo", conc:true, desc:"Apri una fenditura verso il vuoto oscuro dello spazio profondo, creando una sfera di oscurità nera impenetrabile con raggio di 6 metri entro gittata (45 metri). L'area è pesantemente oscurata, è considerata terreno difficile e nessuna luce, magica o no, può illuminarla.\n\nUna creatura che inizia il proprio turno nell'area subisce 2d6 danni da freddo. Una creatura che termina il proprio turno nell'area deve superare un tiro salvezza su Destrezza o subire 2d6 danni da acido da tentacoli lattiginosi che scaturiscono dal vuoto. Concentrazione, fino a 1 minuto." },
  "Faro di Speranza": { livello:3, scuola:"Abiurazione", classi:["Chierico"], tempo:"1 Azione", gittata:"9m", conc:true, desc:"Questo incantesimo infonde speranza e vitalità.\n\nL'incantatore sceglie un qualsiasi numero di creature entro gittata.\n\nPer la durata dell'incantesimo, ogni bersaglio dispone di vantaggio ai tiri salvezza su Saggezza e ai tiri salvezza contro morte e recupera il numero massimo di punti ferita possibile da qualsiasi guarigione." },
  "Freccia Fulminante": { livello:3, scuola:"Trasmutazione", classi:["Ranger"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"4d8", tipoDanno:"Fulmine", conc:true, desc:"Il tuo prossimo tiro per colpire con un'arma a distanza trasforma il proiettile in una saetta di fulmini scoppiettante. Che colpisca o manchi, l'attacco infligge 4d8 danni da fulmine al bersaglio (se colpisce) o la metà (se manca). Inoltre, ogni creatura entro 3 metri dal bersaglio deve superare un tiro salvezza su Destrezza o subire 2d8 danni da fulmine (la metà su successo).\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot di 4° livello o superiore, il danno contro il bersaglio principale aumenta di 1d8 per ogni slot superiore al 3°, e il danno alle creature vicine aumenta di 1d8 per ogni slot superiore al 3°." },
  "Fulmine": { livello:3, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso (linea 30m)", area:"Linea", danno:"8d6", tipoDanno:"Fulmine", desc:"Un fulmine parte dall'incantatore in una direzione a sua scelta, formando una linea lunga 30 metri e larga 1,5 metri.\n\nOgni creatura entro la linea deve effettuare un tiro salvezza su Destrezza. Se lo fallisce subisce 8d6 danni da fulmine, mentre se lo supera, subisce soltanto al metà di quei danni.\n\nIl fulmine incendia oggetti infiammabili nell'area che non sono indossati o trasportati.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 3°." },
  "Guardiani Spirituali": { livello:3, scuola:"Invocazione", classi:["Chierico"], tempo:"1 Azione", gittata:"Sé stesso (aura 4,5m)", danno:"3d8", tipoDanno:"Radiante", conc:true, desc:"L'incantatore chiama a sé degli spiriti che lo proteggano.\n\nGli spiriti fluttuano attorno a lui a una distanza di 4,5 metri per la durata dell'incantesimo.\n\nSe l'incantatore è buono o neutrale, la loro forma spettrale appare angelica o fatata (a scelta dell'incantatore).\n\nSe è malvagio, appaiono come immondi.\n\nQuando l'incantatore lancia questo incantesimo, può designare un qualsiasi numero di creature che egli sia in grado di vedere, che non ne saranno influenzate. La velocità di una creatura influenzata viene dimezzata nell'area, e quando la creatura entra nell'area per la prima volta o vi inizia il proprio turno, deve effettuare un tiro salvezza su Saggezza. Se lo fallisce subisce 3d8 danni radiosi (se l'incantatore è buono o neutrale) o 3d8 danni necrotici (se è malvagio), mentre se lo supera, subisce soltanto la metà di quei danni.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 3°." },
  "Immagine Maggiore": { livello:3, scuola:"Illusione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"36m", conc:true, desc:"- **Tempo di Lancio:** 1 azione\n\n- **Gittata:** 36 metri\n\n- **Componenti:** V, S, M (un pezzo di vello)\n\n- **Durata**: Concentrazione, fino a 10 minuti\n\nCrei l&rsquo;immagine di un oggetto, una creatura o qualche altro fenomeno visibile non più grande di un cubo di 6 metri di spigolo. L&rsquo;immagine appare in un punto a gittata che puoi vedere e vi rimane per la durata dell&rsquo;incantesimo. L&rsquo;immagine sembra completamente reale, e comprende suoni, odori e la temperatura appropriata alla cosa raffigurata. Non puoi generare calore o freddo sufficiente a provocare danni, né un suono abbastanza forte da infliggere danno da tuono o assordare una creatura, o un odore che possa far star male una creatura (come il fetore di un troglodita).\n\nFinché resti a gittata dell&rsquo;illusione, puoi usare un&rsquo;azione per far muovere l&rsquo;immagine in qualsiasi altro punto a gittata. Quando l&rsquo;immagine cambia posizione, puoi alterarne l&rsquo;aspetto così che i suoi movimenti appaiano naturali. Per esempio, se crei l&rsquo;immagine di una creatura e la muovi, puoi alterare l&rsquo;immagine in modo che sembri camminare. Allo stesso modo, puoi impiegare l&rsquo;illusione per produrre suoni diversi in momenti diversi, fino a farle portare avanti una conversazione.\n\nL&rsquo;interazione fisica con l&rsquo;immagine la rivela come illusione, dato che le cose vi passano attraverso. Una creatura che usa la sua azione per esaminare l&rsquo;immagine può determinare che si tratta di un&rsquo;illusione con una prova riuscita di Intelligenza (Indagare) contro la CD del tiro salvezza del tuo incantesimo. Se una creatura riconosce l&rsquo;illusione per quello che è, la creatura può vedervi attraverso, e per quella creatura tutte le altre qualità sensoriali svaniscono.\n\n**Ai Livelli Superiori**. Quando lanci questo incantesimo usando uno slot incantesimo di 6° livello o più alto, l&rsquo;incantesimo dura finché non viene dissolto, senza richiedere la tua concentrazione." },
  "Infliggere Maledizione": { livello:3, scuola:"Necromanzia", classi:["Bardo","Chierico","Mago"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"L'incantatore tocca una creatura che deve superare un tiro salvezza su Saggezza per non essere maledetta per la durata dell'incantesimo.\n\nQuando l'incantatore lancia questo incantesimo, sceglie la natura della maledizione tra le opzioni seguenti:\n\n- L'incantatore sceglie un punteggio di caratteristica. Finché è maledetto, il bersaglio subisce svantaggio alle prove di caratteristica e ai tiri salvezza effettuati con quel punteggio di caratteristica.\n\n- Finché è maledetto, il bersaglio subisce svantaggio ai tiri per colpire contro l'incantatore.\n\n- Finché è maledetto, il bersaglio deve effettuare un tiro salvezza su Saggezza all'inizio di ogni suo turno. Se lo fallisce, spreca la sua azione di quel turno e non fa niente.\n\n- Finché il bersaglio è maledetto, gli attacchi e gli incantesimi dell'incantatore infliggono 1d8 danni necrotici extra al bersaglio.\n\nUn incantesimo Rimuovi Maledizione pone fine a questo effetto.\n\nA discrezione del DM, l'incantatore può scegliere un effetto alternativo per la maledizione, che però non dovrebbe risultare più potente di quelli descritti sopra.\n\nIl DM ha l'ultima parola su tali effetti della maledizione.\n\n**Ai Livelli Superiori**. Se l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, la durata diventa concentrazione, fino a 10 minuti.\n\nSe usa uno slot incantesimo di 5° livello o superiore, la durata diventa 8 ore.\n\nSe usa uno slot incantesimo di 7° livello o superiore, la durata è 24 ore.\n\nSe usa uno slot incantesimo di 9° livello o superiore, l'incantesimo dura finché non viene dissolto.\n\nL'uso di uno slot incantesimo di 5° livello o superiore conferisce una durata che non richiede concentrazione." },
  "Lentezza": { livello:3, scuola:"Trasmutazione", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"36m", area:"Cubo", conc:true, desc:"L'incantatore altera il tempo attorno a un massimo di sei creature a sua scelta all'interno di un cubo con spigolo di 12 metri situato entro gittata. Ogni bersaglio deve superare un tiro salvezza su Saggezza, altrimenti è influenzato da questo incantesimo per la sua durata. Un bersaglio influenzato subisce una penalità di -2 alla CA e ai tiri salvezza su Destrezza, non può usare reazioni e la sua velocità è dimezzata. Nel proprio turno, il bersaglio deve scegliere se usare un'azione o un'azione bonus, ma non entrambe. A prescindere dalle sue capacità e oggetti magici, non può effettuare più di un attacco in mischia o a distanza durante il suo turno. Se la creatura tenta di lanciare un incantesimo con un tempo di lancio di 1 azione, deve tirare un d20. Con un risultato pari o superiore a 11, l'incantesimo non ha effetto prima del turno successivo della creatura e quest'ultima deve usare la propria azione di quel turno per completare l'incantesimo. Se non può farlo, l'incantesimo va sprecato. Una creatura influenzata da questo incantesimo effettua un altro tiro salvezza alla fine del suo turno. Se lo supera, l'effetto per lei termina." },
  "Linguaggi": { livello:3, scuola:"Divinazione", classi:["Bardo","Chierico","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Tocco", desc:"Questo incantesimo garantisce ad una creatura toccata dall'incantatore l'abilità di comprendere e parlare un linguaggio che sente. Inoltre, quando il bersaglio parla, ogni creatura che conosca almeno un linguaggio e che possa sentire il bersaglio è in grado di comprendere ciò che esso pronuncia." },
  "Luce del Giorno": { livello:3, scuola:"Invocazione", classi:["Chierico","Druido","Paladino","Ranger","Stregone"], tempo:"1 Azione", gittata:"18m", area:"Sfera", desc:"Una sfera di luce del raggio di 18 metri si diffonde da un punto situato entro gittata scelto dall'incantatore.\n\nLa sfera è pervasa da luce intensa e proietta luce fioca per altri 18 metri.\n\nSe il punto scelto dall'incantatore si trova su un oggetto che egli sta impugnando o che non è indossato o trasportato da nessuno, la luce si diffonde dall'oggetto e si muove assieme a esso.\n\nCoprire completamente la fonte di luce con un oggetto opaco, come una scodella o un elmo, blocca la luce.\n\nSe una parte dell'area di questo incantesimo si sovrappone a un'area di oscurità creata da un incantesimo di 3° livello o inferiore, l'incantesimo che ha creato l'oscurità è dissolto." },
  "Manto del Crociato": { livello:3, scuola:"Invocazione", classi:["Paladino"], tempo:"1 Azione", gittata:"Sé stesso (aura 9m)", danno:"1d4", tipoDanno:"Radiante", conc:true, desc:"Un potere divino emana da te in un'aura con raggio di 9 metri per la durata (concentrazione, fino a 1 minuto). Fino alla fine dell'incantesimo, l'aura si muove con te. Ogni creatura non ostile nell'aura (incluso te) infligge 1d4 danni radianti extra quando colpisce con un attacco con arma." },
  "Messaggio a Distanza": { livello:3, scuola:"Invocazione", classi:["Bardo","Mago"], tempo:"1 Azione", gittata:"Illimitata", rituale:true, desc:"L'incantatore invia un breve messaggio di massimo venticinque parole a una creatura che gli sia familiare.\n\nLa creatura sente il messaggio nella sua mente, riconosce l'incantatore come colui che l'ha inviato e può rispondere immediatamente allo stesso modo.\n\nL'incantesimo consente alle creature con un punteggio di Intelligenza pari o superiore a 1 di capire il significato del messaggio.\n\nL'incantatore può inviare il messaggio a qualsiasi distanza e perfino sugli altri piani di esistenza, ma se il bersaglio si trova su un piano di esistenza diverso dal suo, c'è una probabilità del 5 per cento che il messaggio non arrivi." },
  "Muro di Vento": { livello:3, scuola:"Invocazione", classi:["Druido","Ranger"], tempo:"1 Azione", gittata:"36m", area:"Linea", danno:"3d8", tipoDanno:"Tuono", conc:true, desc:"Un muro di vento forte si solleva dal terreno in un punto a scelta dell'incantatore situato entro gittata.\n\nIl muro può essere lungo fino a 15 metri, alto 4,5 metri e spesso 30 cm.\n\nL'incantatore può modellare il muro nel modo che preferisce, purché formi un percorso continuo lungo il terreno.\n\nIl muro permane per la durata dell'incantesimo.\n\nQuando il muro appare, ogni creatura entro la sua area deve effettuare un tiro salvezza su Forza. Se lo fallisce, subisce 3d8 danni contundenti, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nIl vento forte tiene lontana la nebbia, il fumo e gli altri gas.\n\nLe creature o gli oggetti volanti di taglia Piccola o inferiore non possono passare attraverso il muro.\n\nI materiali leggeri e non fissati in qualche modo volano verso l'alto una volta portati all'interno del muro.\n\nLe frecce, i quadrelli e gli altri proiettili ordinari lanciati ai bersagli dietro il muro vengono deviati verso l'alto e mancano automaticamente (i macigni scagliati dai giganti o dalle macchine d'assedio e altri proiettili simili non sono influenzati dal muro).\n\nLe creature in forma gassosa non possono attraversare il muro." },
  "Nube Mefitica": { livello:3, scuola:"Evocazione", classi:["Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"27m", area:"Sfera", danno:"5d8", tipoDanno:"Veleno", conc:true, desc:"L'incantatore crea una sfera del raggio di 6 metri composta di gas nauseante giallastro, centrata su un punto situato entro gittata.\n\nLa nube si diffonde oltre gli angoli e la sua area è pesantemente oscurata.\n\nLa nube permane nell'area per la durata dell'incantesimo.\n\nOgni creatura situata completamente all'interno della nube all'inizio del suo turno deve effettuare un tiro salvezza su Costituzione contro veleno. Se lo fallisce, spende la sua azione di quel turno a vomitare in preda al dolore.\n\nLe creature che non hanno bisogno di respirare o sono immuni al veleno superano automaticamente questo tiro salvezza.\n\nUn vento moderato (almeno 15 km all'ora) disperde la nube dopo 4 round. Un vento forte (almeno 30 km all'ora) la disperde dopo un round." },
  "Palla di Fuoco": { livello:3, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"45m", area:"Sfera", danno:"8d6", tipoDanno:"Fuoco", desc:"Una scia di luce parte dall'indice dell'incantatore e sfreccia fino a un punto a sua scelta entro gittata, dove detona con un profondo boato generando un'esplosione di fiamme.\n\nOgni creatura situata entro una sfera del raggio di 6 metri centrata su quel punto deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 8d6 danni da fuoco, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nIl fuoco si diffonde oltre gli angoli e incendia ogni oggetto infiammabile nell'area che non sia indossato o trasportato.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 3°." },
  "Chiaroveggenza": { livello:3, scuola:"Divinazione", classi:["Bardo","Chierico","Mago","Stregone","Warlock"], tempo:"10 min", gittata:"1,5 km", conc:true, desc:"L'incantatore crea un sensore invisibile entro gittata in un luogo a lui familiare (vale a dire un luogo che abbia visitato o visto in precedenza), oppure in un luogo ovvio che non gli sia familiare (per esempio dietro una porta, oltre un angolo o in mezzo a un boschetto). Il sensore rimane al suo posto per la durata dell'incantesimo e non è possibile attaccarlo o interagire con esso in altri modi. Quando l'incantatore lancia l'incantesimo sceglie tra vista e udito. Può usare il senso scelto tramite il sensore, come se si trovasse nel suo spazio. Usando la sua azione, l'incantatore può passare da vista a udito o viceversa. Una creatura in grado di vedere il sensore (per esempio una creatura che beneficia di vedere invisibilità o vista pura) vede un globo luminoso e intangibile grande all'incirca quanto il pugno dell'incantatore." },
  "Occhio Arcano": { livello:4, scuola:"Divinazione", classi:["Mago"], tempo:"1 Azione", gittata:"9m", conc:true, desc:"L'incantatore crea un occhio magico invisibile entro gittata che fluttua nell'aria per la durata dell'incantesimo.\n\nL'incantatore riceve mentalmente una serie di informazioni visive dall'occhio, che è dotato di visione normale e scurovisione fino a 9 metri.\n\nL'occhio può guardare in ogni direzione.\n\nCon un'azione, l'incantatore può muovere l'occhio di 9 metri in qualsiasi direzione. Non c'è limite alla distanza di cui l'occhio può allontanarsi dall'incantatore, ma esso non può entrare su un altro piano di esistenza.\n\nUna barriera solida blocca il movimento dell'occhio, che però può passare attraverso un'apertura del diametro minimo di 2,5 cm." },
  "Localizza Creatura": { livello:4, scuola:"Divinazione", classi:["Bardo","Chierico","Druido","Mago","Paladino","Ranger"], tempo:"1 Azione", gittata:"Sé stesso", conc:true, desc:"L'incantatore descrive o nomina una creatura a lui familiare.\n\nPercepisce la direzione dell'ubicazione di quella creatura, purché essa si trovi entro 300 metri da lui.\n\nSe la creatura è in movimento, l'incantatore sa in che direzione si muove.\n\nL'incantesimo può localizzare una creatura specifica nota all'incantatore, o la creatura più vicina di un tipo specifico (come per esempio un umano o un unicorno), purché l'incantatore abbia visto tale creatura da vicino (entro 9 metri) almeno una volta.\n\nSe la creatura descritta o nominata dall'incantatore ha una forma diversa, per esempio se si trova sotto l'effetto di un incantesimo Metamorfosi, questo incantesimo non localizza la creatura.\n\nQuesto incantesimo non può localizzare una creatura se un corso d'acqua largo almeno 3 metri blocca il percorso diretto tra l'incantatore e la creatura." },
  "Storia Leggendaria": { livello:5, scuola:"Divinazione", classi:["Bardo","Chierico","Mago"], tempo:"10 min", gittata:"Sé stesso", desc:"Una cupola di forza immobile del raggio di 3 metri si forma intorno e sopra di te, restando stazionaria per la durata. L&rsquo;incantesimo termina se lasci l&rsquo;area.\n\nNove creature di taglia Media o inferiore possono entrare nella cupola insieme a te. L&rsquo;incantesimo fallisce se l&rsquo;area include una creatura più grande o più di dieci creature. Le creature e gli oggetti all&rsquo;interno della cupola, quando lanci questo incantesimo, la possono attraversare liberamente. Tutte le altre creature e oggetti sono proibiti dall&rsquo;attraversarla. Incantesimi e altri effetti magici non possono estendersi oltre la cupola o attraversarla. L&rsquo;atmosfera all&rsquo;interno dello spazio è confortevole e asciutta, quale che sia il clima all&rsquo;esterno.\n\nFino al termine dell&rsquo;incantesimo, puoi comandare che l&rsquo;interno diventi illuminato fioco o buio. La cupola è opaca dall&rsquo;esterno, di qualsiasi colore tu scelga, ma è trasparente dall&rsquo;interno." },
  "Parlare con i Morti": { livello:3, scuola:"Necromanzia", classi:["Bardo","Chierico"], tempo:"1 Azione", gittata:"3m", desc:"L'incantatore conferisce una parvenza di vita e di intelligenza a un cadavere a sua scelta situato entro gittata, permettendogli di rispondere alle domande che egli gli pone.\n\nIl cadavere deve avere ancora una bocca e non deve essere un non morto.\n\nL'incantesimo fallisce se il cadavere è già stato il bersaglio di questo incantesimo negli ultimi 10 giorni.\n\nFinché l'incantesimo non termina, l'incantatore può porre al cadavere un massimo di cinque domande.\n\nIl cadavere sa solo quello che sapeva in vita, inclusi i linguaggi che conosceva.\n\nLe risposte sono generalmente brevi, criptiche o ripetitive e il cadavere non è obbligato in alcun modo a fornire risposte sincere se l'incantatore gli è ostile o se lo riconosce come nemico.\n\nL'incantesimo non riporta l'anima della creatura nel suo corpo, ma soltanto lo spirito animante.\n\nQuindi il cadavere non può apprendere nuove informazioni, non conosce nulla di ciò che è accaduto dopo la sua morte e non può speculare sugli eventi futuri." },
  "Parola di Guarigione di Massa": { livello:3, scuola:"Invocazione", classi:["Bardo","Chierico"], tempo:"Azione Bonus", gittata:"18m", danno:"2d4", tipoDanno:"Guarigione", desc:"Finché pronunci parole di cura, fino a sei creature di tua scelta che puoi vedere entro gittata riacquistano punti ferita pari a 1d4 + il modificatore da Incantatore. Questo incantesimo non ha effetto su non morti o costrutti.\n\n**Ai Livelli Superiori.** Quando lanci questa magia usando uno slot incantesimo di 4° livello o superiore, la guarigione aumenta di 1d4 per ogni livello di slot superiore al 3°." },
  "Paura": { livello:3, scuola:"Illusione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso (cono 9m)", area:"Cono", conc:true, desc:"L'incantatore proietta un'immagine illusoria delle peggiori paure della creatura. Ogni creatura entro un cono di 9 metri deve superare un tiro salvezza su Saggezza, altrimenti lascia cadere ciò che tiene in mano e diventa spaventata per la durata dell'incantesimo.\n\nFinché è spaventata da questo incantesimo, una creatura deve effettuare l'azione di Scatto e muoversi per allontanarsi dall'incantatore lungo il percorso più sicuro possibile ad ogni suo turno, a meno che non ci sia alcun posto dove andare.\n\nSe la creatura termina il so turno in un luogo dove non possiede la linea di vista fino all'incantatore, può effettuare un tiro salvezza su Saggezza. Se lo supera, l'incantesimo termina per lei." },
  "Respirare sott'Acqua": { livello:3, scuola:"Trasmutazione", classi:["Artefice","Druido","Mago","Ranger","Stregone"], tempo:"1 Azione", gittata:"9m", rituale:true, desc:"Questo incantesimo conferisce ad un massimo di dieci creature consenzienti entro gittata e che l'incantatore sia in grado di vedere la capacità di respirare sott'acqua finché l'incantesimo non termina. Le creature influenzate conservano anche la loro normale modalità di respirazione." },
  "Rimuovi Maledizione": { livello:3, scuola:"Abiurazione", classi:["Chierico","Mago","Paladino","Warlock"], tempo:"1 Azione", gittata:"Tocco", desc:"Al tocco dell'incantatore, tutte le maledizioni che affliggono una creatura o un oggetto terminano.\n\nSe l'oggetto è un oggetto magico maledetto, la sua maledizione rimane, ma l'incantesimo spezza la sintonia del suo proprietario con quell'oggetto, consentendogli di rimuoverlo o di scartarlo." },
  "Rivitalizzare": { livello:3, scuola:"Necromanzia", classi:["Bardo","Chierico","Druido","Paladino"], tempo:"1 Azione", gittata:"Tocco", desc:"L'incantatore tocca una creatura morta entro l'ultimo minuto.\n\nQuella creatura torna in vita con 1 punto ferita.\n\nQuesto incantesimo non può riportare in vita una creatura morta di vecchiaia e non può ripristinare le eventuali parti del corpo mancanti." },
  "Schema Ipnotico": { livello:3, scuola:"Illusione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"36m", area:"Cubo", conc:true, desc:"L'incantatore crea un complicato intreccio di colori che si snoda nell'aria all'interno di un cubo con spigolo di 9 metri entro gittata.\n\nLa trama appare soltanto per un istante, poi svanisce. Ogni creatura entro l'area che la veda deve effettuare un tiro salvezza su Saggezza. Se lo fallisce, diventa affascinata da questo incantesimo. Finché è affascinata, la creatura è incapacitata e la sua velocità è pari a 0.\n\nL'incantesimo su una creatura influenzata termina se la creatura subisce danni o se qualcun altro usa un'azione per scuotere la creatura, destandola dal suo stato confusionale." },
  "Tempesta di Nevischio": { livello:3, scuola:"Invocazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"45m", area:"Cilindro", conc:true, desc:"Finché l'incantesimo non termina, una gelida pioggia di nevischio cade in un cilindro del raggio di 12 metri e alto 6 metri, centrato su un punto a scelta dell'incantatore e situato entro gittata.\n\nL'area è pesantemente oscurata e le fiamme scoperte vengono estinte.\n\nIl terreno entro l'area è coperto di ghiaccio scivoloso e diventa terreno difficile.\n\nQuando una creatura entra nell'area dell'incantesimo per la prima volta in un turno o vi inizia il proprio turno, deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, cade a terra prona.\n\nSe una creatura cerca di concentrarsi nell'area dell'incantesimo, deve superare un tiro salvezza su Costituzione contro la CD del tiro salvezza dell'incantesimo lanciato dall'incantatore, altrimenti perderà la concentrazione." },
  "Tocco Vampirico": { livello:3, scuola:"Necromanzia", classi:["Mago","Warlock"], tempo:"1 Azione", gittata:"Sé stesso / Tocco", danno:"3d6", tipoDanno:"Necrotico", conc:true, desc:"Il tocco della mano dell'incantatore, avviluppata in una cortina d'ombra, può risucchiare l'energia vitale delle altre creature per curare le proprie ferite. L'incantatore effettua un attacco in mischia con questo incantesimo contro una creatura entro portata. Se colpisce, il bersaglio subisce 3d6 danni necrotici e l'incantatore recupera un ammontare di punti ferita pari alla metà dei danni necrotici inflitti. Finché l'incantesimo non termina, l'incantatore può effettuare l'attacco di nuovo ogni suo turno con azione\n\n**A livelli più alti**. Quando si lancia l'incantesimo usando uno slot incantesimo di 4°livello o superiore, i danni aumentano di 1d6 per ogni slot di livello superiore al 3°" },
  "Velocità": { livello:3, scuola:"Trasmutazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"9m", conc:true, desc:"L'incantatore sceglie una creatura consenziente entro gittata e che egli sia in grado di vedere.\n\nFinché l'incantesimo non termina, il bersaglio ottiene un bonus di +2 alla CA, dispone di vantaggio ai tiri salvezza su Destrezza, la sua velocità raddoppia, e ottiene un'azione aggiuntiva a ogni suo turno. L'azione aggiuntiva può essere usata soltanto per effettuare un'azione di Attacco (solo attacchi con le armi), Disimpegno, Nascondersi, Scatto o Usare un Oggetto.\n\nQuando l'incantesimo termina, il bersaglio non può muoversi o effettuare azioni fino alla fine del suo turno successivo, in quanto è sopraffatto da un'ondata di spossatezza." },
  "Volare": { livello:3, scuola:"Trasmutazione", classi:["Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"fino a 10 minuti L'incantatore tocca una creatura consenziente. Per la durata dell'incantesimo, il bersaglio ottiene una velocità di volo di 18 metri e può fluttuare. Al termine dell'incantesimo, il bersaglio ancora sospeso in aria cade, sempre che non abbia modo di impedire la caduta. Utilizzo di uno slot incantesimo di livello superiore. L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 3º.\n\n**Ai Livelli Superiori.** L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 3º." },
  "Aura di Vita": { livello:4, scuola:"Abiurazione", classi:["Paladino"], tempo:"1 Azione", gittata:"Sé stesso (aura 9m)", conc:true, desc:"fino a 10 minuti L'incantatore irradia un'aura in un'emanazione di 9 metri da sé che permane per la durata dell'incantesimo. Mentre sono nell'aura, l'incantatore e i suoi alleati ottengono resistenza ai danni necrotici e i loro punti ferita massimi non possono essere ridotti. Se un alleato con 0 punti ferita inizia il suo turno nell'aura, ne recupera 1." },
  "Barriera contro la Morte": { livello:4, scuola:"Abiurazione", classi:["Chierico","Mago","Paladino"], tempo:"1 Azione", gittata:"Tocco", desc:"L'incantatore tocca una creatura e le conferisce una certa misura di protezione dalla morte.\n\nLa prima volta in cui il bersaglio dovrebbe scendere a 0 punti ferita a seguito dei danni subiti, il bersaglio scende invece a 1 punto ferita e l'incantesimo termina.\n\nSe l'incantesimo ha ancora effetto quando il bersaglio è soggetto a un effetto che lo ucciderebbe istantaneamente senza infliggere danni, quell'effetto è invece negato contro il bersaglio e l'incantesimo termina." },
  "Colpo Sconvolgente": { livello:4, scuola:"Invocazione", classi:["Paladino"], tempo:"Azione Bonus", gittata:"Sé stesso", danno:"4d6", tipoDanno:"Psichico", conc:true, desc:"La tua arma vibra di energia che distrugge il corpo e la mente. La prossima volta che colpisci con un attacco con arma prima del termine dell'incantesimo (concentrazione, fino a 1 minuto), l'attacco infligge 4d6 danni psichici extra al bersaglio. Inoltre, il bersaglio deve superare un tiro salvezza su Saggezza, altrimenti ha svantaggio a tutti i tiri per colpire e alle prove di caratteristica e non può compiere reazioni fino alla fine del suo turno successivo." },
  "Confusione": { livello:4, scuola:"Ammaliamento", classi:["Bardo","Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"27m", area:"Sfera", conc:true, desc:"Questo incantesimo assale e sconvolge le menti delle creature, inducendole al delirio e provocando azioni incontrollate. Ogni creatura entro una sfora del raggio di 3 metri centrata su un punto a scelta dell'incantatore entro gittata deve superare un tiro salvezza su Saggezza nel momento in cui l'incantesimo viene lanciato, altrimenti ne sarà influenzata. Un bersaglio influenzato non può effettuare reazioni e deve tirare un d10 all'inizio di ogni suo turno per determinare il suo comportamento per quel turno.\n\nd10\nComportamento\n\n1\nLa creatura usa tutto il suo movimento per muoversi in una direzione casuale. Per determinare la direzione si tira un d8 e si assegna una direzione a ogni faccia del dado. La creatura non effettua un'azione in questo turno\n\n2-6\nLa creatura non si muove e non effettua azioni in questo turno.\n\n7-8\nLa creatura usa la sua azione per effettuare un attacco in mischia contro una creatura determinata casualmente e situata entro la sua portata. Se non c'è alcuna creatura entro portata, la creatura non fa nulla.\n\n9-10\nLa creatura può agire e muoversi normalmente\n\n**Al Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, il raggio della sfera aumenta di 1,5 metri per ogni slot di livello superiore al 4°." },
  "Esilio": { livello:4, scuola:"Abiurazione", classi:["Chierico","Mago","Paladino","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"fino a 1 minuto Una creatura entro gittata che l'incantatore è in grado di vedere deve superare un tiro salvezza su Carisma o essere trasportata in un semipiano sicuro per la durata dell'incantesimo. Mentre si trova lì, il bersaglio è incapacitato. Al termine dell'incantesimo, il bersaglio riappare nello spazio in cui si trovava prima del lancio o, se è occupato, nello spazio libero più vicino. Se l'incantesimo sul bersaglio dura 1 minuto, il bersaglio non fa ritorno se è un'aberrazione, un celestiale, un elementale, un folletto o un immondo. In questo caso, viene trasportato in un luogo casuale di un piano (a scelta del GM) associato al tipo di creatura di cui fa parte. Utilizzo di uno slot incantesimo di livello superiore. L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 4º. 145 System Reference Document 5.2.1 spostare anche il branco fino a 9 metri in uno spazio libero che è in grado di vedere. Ogni volta che il branco si muove entro 3 metri da una creatura che l'incantatore è in grado di vedere e ogni volta che una creatura che l'incantatore è in grado di vedere entra in uno spazio entro 3 metri dal branco o vi termina il suo turno, l'incantatore può costringerla a effettuare un tiro salvezza su Destrezza. In caso di fallimento, subisce 3d10 danni taglienti. Una creatura effettua questo tiro salvezza solo una volta per turno. Utilizzo di uno slot incantesimo di livello superiore. I danni aumentano di 1d10 per ogni slot di livello superiore al 3º.\n\n**Ai Livelli Superiori.** L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 4º. 145 System Reference Document 5.2.1 spostare anche il branco fino a 9 metri in uno spazio libero che è in grado di vedere. Ogni volta che il branco si muove entro 3 metri da una creatura che l'incantatore è in grado di vedere e ogni volta che una creatura che l'incantatore è in grado di vedere entra in uno spazio entro 3 metri dal branco o vi termina il suo turno, l'incantatore può costringerla a effettuare un tiro salvezza su Destrezza. In caso di fallimento, subisce 3d10 danni taglienti. Una creatura effettua questo tiro salvezza solo una volta per turno. Utilizzo di uno slot incantesimo di livello superiore. I danni aumentano di 1d10 per ogni slot di livello superiore al 3º." },
  "Evoca Aberrazione": { livello:4, scuola:"Evocazione", classi:["Mago","Warlock"], tempo:"1 Azione", gittata:"27m", conc:true, desc:"Evochi uno spirito aberrante visibile entro gittata (27 metri) per 1 ora (concentrazione). Scegli la forma: Beholderkin, Slaad o Mind Flayer (Fattucchiere Stellare).\n\nHa CA pari a 11 + livello dello slot, PF pari a 40 + 10 per ogni livello sopra il 4°, vola (Beholderkin) o rigenera PF (Slaad), compie attacchi a distanza o in mischia infliggendo danni da forza o psichici pari a 1d8 + 3 + livello di slot, con effetti aggiuntivi in base alla forma.\n\n**Ai Livelli Superiori.** Statistiche e PF aumentano in base allo slot." },
  "Evoca Costrutto": { livello:4, scuola:"Evocazione", classi:["Artefice","Mago"], tempo:"1 Azione", gittata:"27m", conc:true, desc:"Evochi uno spirito animato di un costrutto entro gittata (27 metri) per 1 ora (concentrazione). Scegli il materiale: Argilla, Metallo o Pietra.\n\nHa CA pari a 13 + livello dello slot, PF pari a 40 + 15 per ogni livello sopra il 4°, resistenza a danni da veleno e non magici, compie attacchi che infliggono 1d8 + 4 + livello dello slot danni da forza e possiede reazioni speciali (es. riscaldare il metallo, fango d'argilla o tempra di pietra).\n\n**Ai Livelli Superiori.** Statistiche e PF aumentano proporzionalmente allo slot." },
  "Evoca Elementale": { livello:4, scuola:"Evocazione", classi:["Druido","Mago","Ranger"], tempo:"1 Azione", gittata:"27m", conc:true, desc:"L'incantatore chiama a sé un servitore elementale, scegliendo un'area di acqua, aria, fuoco o terra delle dimensioni di un cubo con spigolo di 3 metri situato entro gittata.\n\nUn elementale con grado di sfida pari o inferiore a 5 e appropriato all'area scelta appare in uno spazio libero entro 3 metri da quell'area.\n\nPer esempio, un elementale del fuoco scaturisce da un falò, mentre un elementale della terra emerge dal terreno.\n\nL'elementale scompare quando scende a 0 punti ferita o quando l'incantesimo termina.\n\nL'elementale è amichevole nei confronti dell'incantatore e dei suoi compagni per la durata dell'incantesimo.\n\nSi tira per l'iniziativa dell'elementale, che svolge i propri turni.\n\nL'elementale obbedisce ai comandi verbali impartiti dall'incantatore (nessuna azione richiesta). Se l'incantatore non impartisce un comando, l'elementale si difende da eventuali altre creature ostili, ma altrimenti non intraprende alcuna azione.\n\nSe la concentrazione dell'incantatore è interrotta, l'elementale non scompare. L'incantatore perde invece il controllo dell'elementale, che diventa ostile nei suoi confronti e nei confronti dei suoi compagni e li potrebbe attaccare. Un elementale privo di controllo non può essere congedato dall'incantatore e scompare 1 ora dopo essere stato evocato.\n\nIl DM possiede le statistiche dell'elementale.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, il grado sfida aumenta di 1 per ogni slot di livello superiore al 5°." },
  "Evocare Elementali Minori": { livello:4, scuola:"Evocazione", classi:["Druido","Mago"], tempo:"1 Azione", gittata:"27m", conc:true, desc:"L'incantatore evoca elementali che appaiono in uno spazio non occupato che egli possa vedere entro gittata. Sceglie una delle seguenti opzioni per decidere cosa appare:\n\n- Un elementale con grado sfida 2 o inferiore\n\n- Due elementali con grado sfida 1 o inferiore\n\n- Quattro elementali con grado sfida 1/2 o inferiore\n\n- Otto elementali con grado sfida 1/4 o inferiore\n\nUn elementale evocato da questo incantesimo scompare se ridotto a 0 punti ferita o alla fine dell'incantesimo.\n\nLe creature evocate sono amichevoli nei confronti dell'incantatore e dei suoi alleati. L'incantatore tira per l'iniziativa delle creature evocate come gruppo, che ha i propri turni. Le creature evocate obbediscono ai comandi verbali impartiti dall'incantatore (nessuna azione richiesta). Se l'incantatore non impartisce un comando, le creature evocate si difendono da eventuali altre creature ostili, ma altrimenti non intraprendono alcuna azione.\n\nIl DM possiede le statistiche delle creature.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo utilizzando determinati slot incantesimo di livello superiore, sceglie una delle opzioni di evocazione precedenti ed appare un numero maggiore di creature: il doppio utilizzando uno slot incantesimo di 6° livello e il triplo utilizzando uno slot incantesimo di 8° livello." },
  "Guardiano della Fede": { livello:4, scuola:"Invocazione", classi:["Chierico"], tempo:"1 Azione", gittata:"9m", danno:"20", tipoDanno:"Radiante", desc:"Un guardiano spettrale Grande compare e fluttua per la durata dell'incantesimo in uno spazio libero a scelta dell'incantatore situato entro gittata e che egli sia in grado di vedere.\n\nIl guardiano occupa quello spazio ed è sfocato, ad eccezione di una spada scintillante e uno scudo decorati con il simbolo della divinità dell'incantatore.\n\nOgni creatura ostile all'incantatore che si muova fino a uno spazio entro 3 metri dal guardiano per la prima volta in un turno deve superare un tiro salvezza su Destrezza. Se lo fallisce, subisce 20 danni radiosi, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nIl guardiano svanisce quando ha inferto un totale di 60 danni." },
  "Inaridire": { livello:4, scuola:"Necromanzia", classi:["Chierico","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"9m", danno:"8d8", tipoDanno:"Necrotico", desc:"Una creatura entro gittata e che l'incantatore sia in grado di vedere è investita da un'ondata di energia necromantica che ne prosciuga i fluidi corporei e la vitalità.\n\nIl bersaglio deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 8d8 danni necrotici, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nQuesto incantesimo non ha alcun effetto sui costrutti o sui non morti.\n\nSe l'incantatore bersaglia una creatura vegetale o un vegetale magico, tale bersaglio subisce svantaggio al tiro salvezza e l'incantesimo infligge il massimo dei danni.\n\nSe l'incantatore bersaglia un vegetale non magico che non è una creatura, come un albero o un arbusto, esso non effettua alcun tiro salvezza: avvizzisce e muore automaticamente.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 4°." },
  "Invisibilità Superiore": { livello:4, scuola:"Illusione", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"L'incantatore o la creatura da lui toccata diventa invisibile finché l'incantesimo non termina. Anche tutto ciò che il bersaglio indossa o trasporta diventa invisibile finché rimane sulla sua persona." },
  "Libertà di Movimento": { livello:4, scuola:"Abiurazione", classi:["Bardo","Chierico","Druido","Ranger"], tempo:"1 Azione", gittata:"Tocco", desc:"ora L'incantatore tocca una creatura consenziente. Per la durata dell'incantesimo, il movimento del bersaglio non è influenzato dal terreno difficile, inoltre incantesimi e altri effetti magici non possono né ridurne la velocità né trattenerlo o renderlo paralizzato. Il bersaglio dispone anche di una velocità di nuoto pari alla sua velocità. Inoltre, il bersaglio può usare 1,5 metri di movimento per sfuggire automaticamente alle restrizioni non magiche, come un paio di manette o la presa di una creatura che lo afferra. Utilizzo di uno slot incantesimo di livello superiore. L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 4º.\n\n**Ai Livelli Superiori.** L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 4º." },
  "Malanno": { livello:4, scuola:"Necromanzia", classi:["Chierico","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"9m", danno:"8d8", tipoDanno:"Necrotico", desc:"Una creatura entro gittata e che l'incantatore sia in grado di vedere è investita da un'ondata di energia necromantica che ne prosciuga i fluidi corporei e la vitalità.\n\nIl bersaglio deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 8d8 danni necrotici, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nQuesto incantesimo non ha alcun effetto sui costrutti o sui non morti.\n\nSe l'incantatore bersaglia una creatura vegetale o un vegetale magico, tale bersaglio subisce svantaggio al tiro salvezza e l'incantesimo infligge il massimo dei danni.\n\nSe l'incantatore bersaglia un vegetale non magico che non è una creatura, come un albero o un arbusto, esso non effettua alcun tiro salvezza: avvizzisce e muore automaticamente.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 4°." },
  "Muro di Fuoco": { livello:4, scuola:"Invocazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"36m", area:"Linea", danno:"5d8", tipoDanno:"Fuoco", conc:true, desc:"L'incantatore crea un muro di fuoco su una superficie solida situata entro gittata.\n\nIl muro può essere lungo fino a 18 metri, alto 6 metri e spesso 30 cm, oppure può essere un muro circolare del diametro massimo di 6 metri, alto 6 metri e spesso 30 cm.\n\nIl muro è opaco e permane per la durata dell'incantesimo.\n\nQuando il muro appare, ogni creatura entro la sua area deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 5d8 danni da fuoco, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nUn lato del muro, scelto dall'incantatore al momento del lancio di questo incantesimo, infligge 5d8 danni da fuoco a ogni creatura che termina il suo turno entro 3 metri da quel lato o all'interno del muro. Una creatura subisce gli stessi danni quando entra nel muro per la prima volta in un turno o vi termina il proprio turno. L'altro lato del muro non infligge danni.\n\n**Ai Livelli Superiori.** Quando L'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 4°." },
  "Pelle di Pietra": { livello:4, scuola:"Abiurazione", classi:["Druido","Mago","Ranger"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"Questo incantesimo rende la carne di una creatura consenziente toccata dall'incantatore dura come la pietra.\n\nFinché l'incantesimo non termina, il bersaglio ottiene resistenza ai danni non magici contundenti, perforanti e taglienti." },
  "Metamorfosi": { livello:4, scuola:"Trasmutazione", classi:["Bardo","Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"Questo incantesimo impartisce una nuova forma a una creatura entro gittata e che l'incantatore sia in grado di vedere.\n\nUna creatura non consenziente deve effettuare un tiro salvezza su Saggezza per evitare l'effetto.\n\nL'incantesimo non ha effetto su un mutaforma o su una creatura con 0 punti ferita.\n\nLa trasformazione permane per la durata dell'incantesimo o finché il bersaglio non scenda a 0 punti ferita o non muoia.\n\nLa nuova forma può essere quella di qualsiasi bestia il cui grado di sfida sia pari o inferiore a quello del bersaglio (o al livello del bersaglio, se esso non possiede un grado di sfida).\n\nLe statistiche di gioco del bersaglio, inclusi i punteggi di caratteristica mentali, vengono sostituite dalle statistiche della bestia scelta.\n\nIl bersaglio mantiene il suo allineamento e la sua personalità.\n\nIl bersaglio assume i punti ferita della sua nuova forma.\n\nQuando torna alla sua forma normale, torna al numero di punti ferita che possedeva prima della trasformazione.\n\nSe riassume la sua forma normale per essere sceso a 0 punti ferita, ogni eventuale danno in ecceso si trasferisce alla sua forma normale. Fintanto che i danni in eccesso non portano la forma normale della creatura a 0 punti ferita, essa non cade priva di sensi.\n\nLe azioni della creatura sono limitate a quelle che la natura della sua nuova forma le consente di effettuare: non può parlare, lanciare incantesimi o effettuare qualsiasi altra azione che richieda l'uso delle mani o della parola.\n\nL'equipaggiamento del bersaglio si fonde nella nuova forma.\n\nLa creatura non può attivare, usare o impugnare gli oggetti del suo equipaggiamento, né trarne benefici in altri modi." },
  "Porta Dimensionale": { livello:4, scuola:"Evocazione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"150m", desc:"L'incantatore si teletrasporta dal suo luogo attuale a un qualsiasi altro punto entro gittata.\n\nArriva esattamente nel punto desiderato, che può trattarsi di un luogo che è in grado di vedere o uno che è in grado di descrivere dichiarandone la distanza e la direzione, come per esempio \"60 metri in linea retta verso il basso\" o \"verso nordovest, a un'angolazione ascendente di 45 gradi per 90 metri\".\n\nL'incantatore può portare con sé degli oggetti, purché il loro peso non superi quello che egli è in grado di trasportare. Può inoltre portare con sé una creatura consenziente di taglia pari o inferiore alla sua, che trasporti equipaggiamento che non superi la sua capacità di trasporto.\n\nLa creatura deve trovarsi entro 1,5 metri dall'incantatore quando questi lancia l'incantesimo.\n\nSe l'incantatore dovesse arrivare in un luogo già occupato da un oggetto o da una creatura, sia l'incantatore che ogni creatura che viaggia assieme a lui subiscono 4d6 danni da forza ciascuno e l'incantesimo di teletrasporto fallisce." },
  "Scudo di Fuoco": { livello:4, scuola:"Invocazione", classi:["Mago"], tempo:"1 Azione", gittata:"Sé stesso", danno:"2d8", tipoDanno:"Fuoco", desc:"Per la durata dell'incantesimo il corpo dell'incantatore è avvolto da un sottile alone di fiamme spettrali che proiettano luce intensa entro un raggio di 3 metri e luce fioca per altri 3 metri.\n\nL'incantatore può terminare l'incantesimo prematuramente usando un'azione.\n\nLe fiamme conferiscono all'incantatore uno scudo ardente o uno scudo gelido, a sua scelta. Lo scudo ardente gli conferisce resistenza ai danni da freddo mentre lo scudo gelido gli conferisce resistenza ai danni da fuoco. Inoltre, ogni volta che una creatura entro 1,5 metri dall'incantatore lo colpisce con un attacco in mischia, dallo scudo si sprigiona una fiammata. L'attaccante subisce 2d8 danni da fuoco nel caso di uno scudo ardente o 2d8 danni da freddo nel caso di uno scudo gelido." },
  "Tempesta di Ghiaccio": { livello:4, scuola:"Invocazione", classi:["Druido","Mago","Ranger","Stregone"], tempo:"1 Azione", gittata:"90m", area:"Cilindro", danno:"2d8+4d6", tipoDanno:"Contundente/Freddo", desc:"Chicchi di grandine duri quanto pietre piovono sul terreno all'interno di un cilindro del raggio di 6 metri e alto 12 metri centrato su un punto entro gittata.\n\nOgni creatura entro il cilindro deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 2d8 danni contundenti e 4d6 danni da freddo, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nLa grandine trasforma l'area di effetto della tempesta in terreno difficile fino alla fine del turno successivo dell'incantatore.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 5° livello o superiore, i danni contundenti aumentano di 1d8 per ogni slot di livello superiore al 4°." },
  "Terreno Allucinatorio": { livello:4, scuola:"Illusione", classi:["Bardo","Druido","Mago","Warlock"], tempo:"1 Azione", gittata:"90m", area:"Cubo", desc:"L'incantatore fa in modo che un terreno naturale contenuto in un cubo con spigolo di 45 metri appaia, suoni e odori come un altro tipo di terreno naturale.\n\nUn campo aperto o una strada potrebbe quindi sembrare una palude, una collina, un creapaccio o un qualche altro tipo di terreno difficile o invalicabile.\n\nUno stagno potrebbe apparire come un prato erboso, un precipizio come un dolce pendio e un fosso erto di rocce come una strada ampia e accogliente.\n\nLe strutture artificiali, l'equipaggiamento e le creature entro l'area non cambiano aspetto.\n\nLe caratteristiche tattili del terreno non cambiano, quindi le creature che entrano nell'area hanno buone probabilità di capire che si tratta di un'illusione." },
  "Vite Afferrante": { livello:4, scuola:"Evocazione", classi:["Druido","Ranger"], tempo:"1 Azione", gittata:"9m", conc:true, desc:"Fai germogliare istantaneamente una spessa vite rampicante da una superficie piana entro gittata (9 metri). La vite dura per la durata dell'incantesimo (concentrazione, fino a 1 minuto). Quando lanci questo incantesimo e poi come azione bonus in ogni tuo turno, puoi comandare alla vite di scattare verso una creatura entro 9 metri da essa. La creatura deve superare un tiro salvezza su Destrezza, altrimenti viene trascinata fino a 6 metri in linea retta verso la vite." },
  "Blocca Mostri": { livello:5, scuola:"Ammaliamento", classi:["Bardo","Chierico","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"27m", conc:true, desc:"L'incantatore sceglie una creatura entro gittata e che egli sia in grado di vedere. li bersaglio deve superare un tiro salvezza su Saggezza, altrimenti sarà paralizzato per la durata dell'incantesimo. Questo incantesimo non ha effetto sui non morti. Alla fine di ogni suo turno, il bersaglio può effettuare un altro tiro salvezza su Saggezza. Se lo supera, l'incantesimo su di esso termina.\n\n**Ai Livelli Superiori**. Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 5°. Le creature devono trovarsi a non più di 9 metri l'una dall'altra quando l'incantatore le bersaglia." },
  "Cerchio di Potere": { livello:5, scuola:"Abiurazione", classi:["Paladino"], tempo:"1 Azione", gittata:"Sé stesso (aura 9m)", conc:true, desc:"Un'energia divina radiante erompe da te creando un'aura protettiva con raggio di 9 metri per la durata (concentrazione, fino a 10 minuti). Fino al termine dell'incantesimo, l'aura si sposta con te.\n\nTu e qualsiasi alleato nell'aura avete vantaggio a tutti i tiri salvezza contro incantesimi e altri effetti magici. Inoltre, quando una creatura nell'aura supera un tiro salvezza contro un incantesimo o effetto magico che infliggerebbe la metà dei danni su un successo, non subisce invece alcun danno." },
  "Colonna di Fuoco": { livello:5, scuola:"Invocazione", classi:["Chierico"], tempo:"1 Azione", gittata:"18m", area:"Cilindro", danno:"4d6+4d6", tipoDanno:"Fuoco/Radiante", desc:"Una colonna verticale di fuoco divino scende dal cielo con un boato in un luogo indicato dall'incantatore. Ogni creatura entro un cilindro del raggio di 3 metri e alto 12 metri centrato su un punto entro gittata deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 4d6 danni da fuoco e 4d6 danni radiosi, mentre se lo supera, subisce soltanto la metà di quei danni.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, i danni da fuoco o i danni radiosi (a scelta dell'incantatore) aumentano di 1d6 per ogni slot di livello superiore al 5°." },
  "Comunione con la Natura": { livello:5, scuola:"Divinazione", classi:["Druido","Ranger"], tempo:"1 min", gittata:"Sé stesso", rituale:true, desc:"L’incantatore entra in comunione con gli spiriti della natura e acquisisce conoscenza dell’area circostante. All’aperto, l’incantesimo fornisce all’incantatore la conoscenza dell’area entro un raggio di 4,5 chilometri. Nelle caverne e in altri ambienti naturali sotterranei, il raggio è limitato a 90 metri. L’incantesimo non funziona nei luoghi in cui la natura è stata sostituita da costruzioni, come castelli e insediamenti.\n\nScegli tre dei seguenti fatti; l’incantatore apprende i fatti che riguardano l’area dell’incantesimo:\n\n- Luoghi di insediamento\n- Ubicazione dei portali che conducono verso altri piani di esistenza\n- Ubicazione di una creatura con grado di sfida pari o superiore a 10 (a scelta del GM) che sia un celestiale, un elementale, un folletto, un immondo o un non morto\n- Il tipo di pianta, minerale o bestia più diffuso (l’incantatore sceglie quale apprendere)\n- Ubicazione di distese d’acquaAd esempio, l’incantatore può determinare l’ubicazione di un potente mostro situato in quell’area, l’ubicazione delle distese d’acqua e l’ubicazione di eventuali cittadine." },
  "Cono di Freddo": { livello:5, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso (cono 18m)", area:"Cono", danno:"8d8", tipoDanno:"Freddo", desc:"Un getto d'aria gelida si propaga dall'incantatore. Ogni creatura entro un cono di 18 metri che ha origine dall'incantatore effettua un tiro salvezza su Costituzione, subendo 8d8 danni da freddo in caso di fallimento, o la metà dei danni in caso di successo. Una creatura uccisa da questo incantesimo si tramuta in una statua di ghiaccio finché non si scioglie. Utilizzo di uno slot incantesimo di livello superiore. I danni aumentano di 1d8 per ogni slot di livello superiore al 5º.\n\n**Ai Livelli Superiori.** I danni aumentano di 1d8 per ogni slot di livello superiore al 5º." },
  "Cura Ferite di Massa": { livello:5, scuola:"Invocazione", classi:["Bardo","Chierico","Druido"], tempo:"1 Azione", gittata:"18m", area:"Sfera", danno:"5d8", tipoDanno:"Guarigione", desc:"Un'ondata di energia curativa si sprigiona da un punto a scelta dell'incantatore situato entro gittata.\n\nL'incantatore indica fino a sei creature entro una sfera del raggio di 9 metri centrata su quel punto.\n\nOgni creatura bersaglio recupera un ammontare di punti ferita pari a 3d8 + il modificatore di caratteristica da incantatore.\n\nQuesto incantesimo non ha effetto sui costrutti o sui non morti.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, la guarigione aumenta di 1d8 per ogni slot di livello superiore al 5°." },
  "Dominare Persone": { livello:5, scuola:"Ammaliamento", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"L'incantatore tenta di soggiogare un umanoide entro gittata e che egli sia in grado di vedere.\n\nQuell'umanoide deve superare un tiro salvezza su Saggezza, altrimenti sarà affascinato dall'incantatore per la durata dell'incantesimo.\n\nSe l'incantatore o le creature a lui amichevoli stanno combattendo contro l'umanoide, quest'ultimo dispone di vantaggio al tiro salvezza.\n\nMentre il bersaglio è affascinato, l'incantatore dispone di un legame telepatico con lui finché entrambi si trovano sullo stesso piano di esistenza. L'incantatore può usare questo legame telepatico per impartire comandi alla creatura finché è cosciente (nessuna azione richiesta), ed essa farà del suo meglio per obbedire. L'incantatore può specificare un corso d'azione semplice e generico come \"attacca quella creatura\", \"corri fin laggiù\" o \"portami quell'oggetto\". Se la creatura porta a termine l'ordine e non riceve ulteriori indicazioni da parte dell'incantatore, essa si difende e si protegge al meglio delle sue capacità.\n\nL'incantatore può usare la sua azione per assumere il controllo totale e preciso del bersaglio. Fino alla fine del turno successivo dell'incantatore, la creatura effettua soltanto le azioni scelte dall'incantatore e non fa niente che l'incantatore non le consenta di fare. Durante questo periodo, l'incantatore può anche fare in modo che la creatura usi una reazione, ma per farlo dovrà usare la sua stessa reazione.\n\nOgni volta che il bersaglio subisce danni, effettua un nuovo tiro salvezza su Saggezza contro l'incantesimo. Se lo suepra, l'incantesimo termina.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo con uno slot incantesimo di 6° livello, la durata diventa concentrazione, fino a 10 minuti.\n\nQuando usa uno slot incantesimo di 7° livello, la durata diventa concentrazione, fino a 1 ora.\n\nQuando usa uno slot incantesimo di 8° livello o superiore, la durata diventa concentrazione, fino a 8 ore." },
  "Evoca Celestiale": { livello:5, scuola:"Evocazione", classi:["Chierico","Paladino"], tempo:"1 Azione", gittata:"27m", conc:true, desc:"fino a 10 minuti L'incantatore evoca uno spirito dai Piani Superiori, che si manifesta come un pilastro di luce in un cilindro del raggio di 3 metri e dell'altezza di 12 metri centrato in un punto entro gittata. Per ogni creatura che l'incantatore è in grado di vedere nel cilindro, sceglie quale di queste luci brilla su di essa: Luce curatrice. Il bersaglio recupera una quantità di punti ferita pari a 4d12 più il modificatore di caratteristica da incantatore dell'incantatore. Luce ustionante. Il bersaglio effettua un tiro salvezza su Destrezza, subendo 6d12 danni radiosi in caso di fallimento, o la metà dei danni in caso di successo. Fino al termine dell'incantesimo, una luce intensa riempie il cilindro e, quando l'incantatore si muove nel suo turno, può spostare anche il cilindro fino a 9 metri. Ogni volta che il cilindro si muove nello spazio di una creatura che l'incantatore è in grado di vedere e ogni volta che una creatura che l'incantatore è in grado di vedere entra nel cilindro o vi termina il suo turno, l'incantatore può immergerla in una di queste luci. Una creatura può essere influenzata da questo incantesimo solo una volta per turno. Utilizzo di uno slot incantesimo di livello superiore. I danni e la guarigione aumentano di 1d12 per ogni slot di livello superiore al 7º.\n\n**Ai Livelli Superiori.** I danni e la guarigione aumentano di 1d12 per ogni slot di livello superiore al 7º." },
  "Evoca Drago": { livello:5, scuola:"Evocazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"Evochi uno spirito draconico grande in uno spazio libero visibile entro gittata (18 metri) per la durata di 1 ora (concentrazione). Scegli la famiglia: Cromatico, Metallico o Gemma.\n\nHa CA pari a 14 + livello dello slot, PF pari a 50 + 10 per ogni livello sopra il 5°, velocità di volo 18 metri, vista cieca 9 metri, resistenza al danno elementale prescelto e compie un numero di attacchi (morsi e soffio) pari alla metà del livello dello slot, infliggendo 1d6 + 4 + livello dello slot danni perforanti più 2d6 danni elementali.\n\n**Ai Livelli Superiori.** Statistiche e punti ferita aumentano con il livello dello slot." },
  "Evocare Elementale": { livello:5, scuola:"Evocazione", classi:["Druido","Mago"], tempo:"1 min", gittata:"27m", conc:true, desc:"L'incantatore chiama a sé un servitore elementale, scegliendo un'area di acqua, aria, fuoco o terra delle dimensioni di un cubo con spigolo di 3 metri situato entro gittata.\n\nUn elementale con grado di sfida pari o inferiore a 5 e appropriato all'area scelta appare in uno spazio libero entro 3 metri da quell'area.\n\nPer esempio, un elementale del fuoco scaturisce da un falò, mentre un elementale della terra emerge dal terreno.\n\nL'elementale scompare quando scende a 0 punti ferita o quando l'incantesimo termina.\n\nL'elementale è amichevole nei confronti dell'incantatore e dei suoi compagni per la durata dell'incantesimo.\n\nSi tira per l'iniziativa dell'elementale, che svolge i propri turni.\n\nL'elementale obbedisce ai comandi verbali impartiti dall'incantatore (nessuna azione richiesta). Se l'incantatore non impartisce un comando, l'elementale si difende da eventuali altre creature ostili, ma altrimenti non intraprende alcuna azione.\n\nSe la concentrazione dell'incantatore è interrotta, l'elementale non scompare. L'incantatore perde invece il controllo dell'elementale, che diventa ostile nei suoi confronti e nei confronti dei suoi compagni e li potrebbe attaccare. Un elementale privo di controllo non può essere congedato dall'incantatore e scompare 1 ora dopo essere stato evocato.\n\nIl DM possiede le statistiche dell'elementale.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, il grado sfida aumenta di 1 per ogni slot di livello superiore al 5°." },
  "Faretra Veloce": { livello:5, scuola:"Trasmutazione", classi:["Ranger"], tempo:"Azione Bonus", gittata:"Tocco", conc:true, desc:"Trasmetti una rapidità soprannaturale alla tua faretra o borsa di proiettili per la durata (concentrazione, fino a 1 minuto). Fino al termine dell'incantesimo, puoi usare un'azione bonus in ogni tuo turno per effettuare due attacchi con un'arma a distanza, a condizione che tu prenda le munizioni dalla faretra bersagliata. La faretra produce magicamente quante munizioni non magiche siano necessarie." },
  "Muro di Forza": { livello:5, scuola:"Invocazione", classi:["Mago"], tempo:"1 Azione", gittata:"36m", conc:true, desc:"Un muro invisibile di forza si materializza in un punto a scelta dell'incantatore situato entro gittata.\n\nIl muro appare nell'orientamento che l'incantatore desidera, come barriera orizzontale, verticale o inclinata.\n\nPuò fluttuare nell'aria o poggiare su una superficie solida.\n\nL'incantatore può modellarlo in una semisfera o in una sfera del raggio massimo di 3 metri, o come una superficie piatta composta di dieci pannelli quadrati con lato di 3 metri l'uno.\n\nOgni pannello deve essere contiguo a un altro pannello.\n\nIn qualsiasi forma, il muro ha uno spessore di 0,5 cm e permane per la durata dell'incantesimo.\n\nSe il muro passa attraverso lo spazio di una creatura quando appare, la creatura viene spinta da un lato del muro a scelta dell'incantatore.\n\nNulla può attraversare fisicamente il muro, che è immune a tutti i danni e non può essere dissolto tramite Dissolvi Magie.\n\nUn incantesimo Disintegrazione, tuttavia, distrugge il muro istantaneamente.\n\nIl muro si estende anche sul Piano Etereo, bloccando i viaggi eterei che lo attraversano." },
  "Muro di Pietra": { livello:5, scuola:"Invocazione", classi:["Druido","Mago"], tempo:"1 Azione", gittata:"36m", conc:true, desc:"Un muro non magico di solida pietra si materializza partendo da un punto a scelta dell'incantatore situato entro gittata.\n\nIl muro è spesso 15 cm e composto da dieci pannelli quadrati con lato di 3 metri l'uno. Ogni pannello deve essere contiguo ad almeno un altro pannello.\n\nIn alternativa, l'incantatore può creare dei pannelli di 3 metri per 6 metri dello spessore di soli 7,5 cm.\n\nSe il muro attraversa lo spazio di una creatura nel momento in cui compare, quella creatura viene spinta da un lato del muro (a scelta dell'incantatore).\n\nSe una creatura sarebbe circondata su tutti i lati dal muro (o dal muro e da un'altra superficie solida), può effettuare un tiro salvezza su Destrezza. Se lo supera, può usare la sua reazione per muoversi fino alla sua velocità nel tentativo di non rimanere intrappolata dal muro.\n\nIl muro può avere la forma desiderata dall'incantatore, ma non può occupare lo stesso spazio di una creatura o di un oggetto. Non è necessario che il muro sia verticale o poggi su fondamenta solide. Deve però fondersi ed essere solidamente sorretto da una massa di pietra già esistente.\n\nQuindi è possibile usare questo incantesimo per creare una rampa o un ponte che attraversi un baratro\n\nSe l'incantatore crea un'arcata di lunghezza superiore a 6 metri, deve dimezzare le dimensioni di ogni pannello per creare dei sostegni. Può rozzamente modellare il muro per creare feritoie, spalti e così via.\n\nIl muro è un oggetto fatto di pietra che può essere danneggiato e quindi sfondato.\n\nOgni pannello ha CA 15 e 30 punti ferita per ogni 2,5 cm di spessore. Quando un pannello scende a 0 punti ferita è distrutto e potrebbe provocare anche il crollo di altri pannelli, a discrezione del DM.\n\nSe l'incantatore mantiene la concentrazione su questo incantesimo per l'intera durata, il muro diventa permanente e non può essere dissolto. Altrimenti, il muro scompare quando l'incantesimo termina." },
  "Onda Distruttrice": { livello:5, scuola:"Invocazione", classi:["Paladino"], tempo:"1 Azione", gittata:"Sé stesso (aura 9m)", area:"Sfera", danno:"5d6+5d6", tipoDanno:"Tuono/Radiante", desc:"Colpisci il suolo scatenando un'onda d'urto di energia fragorosa e divina che erompe da te in un raggio di 9 metri. Ogni creatura a tua scelta entro l'area deve effettuare un tiro salvezza su Costituzione.\n\nSe fallisce, subisce 5d6 danni da tuono e 5d6 danni radianti o necrotici (a tua scelta) e cade prona. Se supera il tiro salvezza, subisce solo la metà di quei danni e non cade prona." },
  "Passo Arboreo": { livello:5, scuola:"Evocazione", classi:["Druido","Ranger"], tempo:"1 Azione", gittata:"Sé stesso", conc:true, desc:"L'incantatore ottiene la capacità di entrare in un albero e di muoversi dall'interno di quell'albero a un altro albero dello stesso tipo situato entro 150 metri.\n\nEntrambi gli alberi devono essere vivi e di taglia pari o superiore a quella dell'incantatore.\n\nL'incantatore deve usare 1,5 metri di movimento per entrare in un albero.\n\nApprende istantaneamente l'ubicazione di tutti gli altri alberi dello stesso tipo entro 150 metri e, come parte del movimento usato per entrare al suo interno, può scegliere se passare in uno di quegli alberi o emergere dall'albero in cui si trova.\n\nL'incantatore ricompare in un punto a sua scelta entro 1,5 metri dall'albero di destinazione usando ulteriori 1,5 metri di movimento. Se non gli rimane più alcun movimento, ricompare entro 1,5 metri dall'albero in cui è entrato.\n\nL'incantatore può usare questa capacità di trasporto una volta per round per la durata dell'incantesimo.\n\nDeve concludere ogni suo turno fuori da un albero." },
  "Passo Lontano": { livello:5, scuola:"Evocazione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"Azione Bonus", gittata:"Sé stesso (18m)", conc:true, desc:"Ti teletrasporti istantaneamente fino a 18 metri in uno spazio libero visibile. Fino al termine dell'incantesimo (concentrazione, fino a 1 minuto), puoi teletrasportarti nuovamente fino a 18 metri come azione bonus in ogni tuo turno successivo." },
  "Piaga di Insetti": { livello:5, scuola:"Evocazione", classi:["Chierico","Druido","Stregone"], tempo:"1 Azione", gittata:"90m", area:"Sfera", danno:"4d10", tipoDanno:"Perforante", conc:true, desc:"Uno sciame di locuste fameliche riempie una sfera del raggio di 6 metri centrata su un punto a scelta dell'incantatore entro gittata. La sfera si diffonde oltre gli angoli, permane per la durata dell'incantesimo e la sua area è leggermente oscurata. L'area della sfera è considerata terreno difficile.\n\nQuando la sfera compare, ogni creatura al suo interno deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 4d10 danni perforanti, mentre se lo supera subisce soltanto la metà di quei danni. Una creatura deve effettuare questo tiro salvezza anche quando entra nell'area dell'incantesimo per la prima volta in un turno o vi termina il proprio turno.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, i danni aumentano di 1d10 per ogni slot di livello superiore al 5°." },
  "Rianimare Morti": { livello:5, scuola:"Necromanzia", classi:["Bardo","Chierico","Paladino"], tempo:"1 ora", gittata:"Tocco", desc:"L'incantatore riporta in vita una creatura morta da lui toccata, purché non sia morta da più di 10 giorni. Se l'anima della creatura è consenziente ed è libera di riunirsi al corpo, la creatura torna in vita con 1 punto ferita.\n\nQuesto incantesimo neutralizza inoltre qualsiasi veleno e cura le malattie non magiche che influenzavano la creatura al momento della morte. Tuttavia, questo incantesimo non rimuove le malattie magiche, le maledizioni e le altre afflizioni analoghe; se non vengono rimossi prima del lancio dell'incantesimo, il bersaglio ne sarà afflitto quando tornerà in vita.\n\nQuesto incantesimo non può riportare in vita una creatura non morta.\n\nQuesto incantesimo richiude tutte le ferite mortali, ma non ripristina le parti del corpo mancanti. Se una creatura è priva di parti del corpo o di organi essenziali per la sua sopravvivenza (come per esempio la testa), l'incantesimo fallisce automaticamente.\n\nIl ritorno dalla morte è una vera e propria ordalia. Il bersaglio subisce una penalità di -4 a tutti i tiri per colpire, ai tiri salvezza e alle prove di caratteristica. Ogni volta che il bersaglio completa un riposo lungo, la penalità viene ridotta di 1 finché non sparisce del tutto." },
  "Ridestare": { livello:5, scuola:"Trasmutazione", classi:["Druido"], tempo:"8 ore", gittata:"Tocco", desc:"L'incantatore tocca un umanoide morto o una parte di un umanoide morto. Purché la creatura non sia morta da più di 10 giorni, l'incantesimo forma un nuovo corpo adulto per quell'umanoide e poi richiama la sua anima all'interno di quel corpo. Se l'anima del bersaglio non è consenziente o libera di tornare, l'incantesimo fallisce.\n\nL'incantesimo produce un nuovo corpo in cui la creatura possa vivere, cosa che probabilmente costringe la creatura a cambiare razza. Il DM tira un d100 e consulta la tabella seguente per determinare quale forma assume la creatura quando torna in vita; in alternativa, il DM può scegliere la forma.\n\nd100\nRazza\n\n01-04\nDragonide\n\n05-13\nNano delle colline\n\n14-21\nNano delle montagne\n\n22-25\nElfo oscuro\n\n26-34\nElfo alto\n\n35-42\nElfo dei boschi\n\n43-46\nGnomo delle foreste\n\n47-52\nGnomo delle rocce\n\n53-56\nMezzelfo\n\n57-60\nMezzorco\n\n61-68\nHalfling piedelesto\n\n69-76\nHalfling tozzo\n\n77-96\nUmano\n\n97-00\nTiefling\n\nLa creatura reincarnata ricorda la sua vita e le sue esperienze passate. Conserva le capacità che possedeva nella sua forma originale, ma sostituisce la razza originale con quella nuova e cambia i tratti razziali di conseguenza." },
  "Ristorare Superiore": { livello:5, scuola:"Abiurazione", classi:["Bardo","Chierico","Druido"], tempo:"1 Azione", gittata:"Tocco", desc:"L'incantatore infonde energia positiva in una creatura toccata per disfare un effetto debilitante. L'incantatore può ridurre di uno il livello di indebolimento del bersaglio o terminare uno degli effetti seguenti su di esso:\n\n- Un effetto che ha affascinato o pietrificato il bersaglio;\n\n- Una maledizione, inclusa la sintonia del bersaglio con un oggetto magico maledetto;\n\n- Una qualsiasi riduzione di un punteggio di caratteristica del bersaglio;\n\n- Un effetto che riduce il massimo dei punti ferita del bersaglio." },
  "Scrutare": { livello:5, scuola:"Divinazione", classi:["Bardo","Chierico","Druido","Mago","Warlock"], tempo:"10 min", gittata:"Sé stesso", conc:true, desc:"L'incantatore può vedere e udire una particolare creatura a sua scelta situata sul suo stesso piano di esistenza. Il bersaglio deve effettuare un tiro salvezza su Saggezza, modificato dalla conoscenza e dal tipo di legame che l'incantatore ha nei confronti del bersaglio. Se il bersaglio sa che l'incantatore sta lanciando questo incantesimo, può fallire il tiro salvezza volontariamente se desidera essere osservato.\n\nConoscenza\nModificatore del\ntiro salvezza\n\nInformazioni indirette (solo sentito parlare del bersaglio)\n+5\n\nInformazioni dirette (si è incontrato il bersaglio)\n0\n\nFamiliarità (si conosce bene il bersaglio)\n-5\n\nLegame\nModificatore del\ntiro salvezza\n\nDescrizione o immagine\n-2\n\nOggetto personale o abito\n-4\n\nParte del corpo, ciocca di capelli, unghia tagliata ecc.\n-10\n\nIn caso di tiro salvezza superato, il bersaglio non è influenzato e l'incantatore non può più usare questo incantesimo contro di lui per 24 ore.\n\nIn caso di tiro salvezza fallito, l'incantesimo crea un sensore invisibile entro 3 metri dal bersaglio. L'incantatore può vedere e sentire attraverso il sensore come se si trovasse sul posto. Il sensore si muove assieme al bersaglio, rimanendo entro 3 metri da esso per la durata dell'incantesimo. Una creatura in grado di vedere gli oggetti invisibili vede il sensore come un globo luminoso delle dimensioni approssimative di un pugno umano.\n\nAnziché bersagliare una creatura, l'incantatore può scegliere un luogo che abbia già visto in precedenza come bersaglio di questo incantesimo. Quando lo fa, il sensore appare in quel luogo e non si muove." },
  "Sviare": { livello:5, scuola:"Illusione", classi:["Bardo","Mago"], tempo:"1 Azione", gittata:"Sé stesso", conc:true, desc:"L'incantatore diventa invisibile nello stesso momento in cui una sua replica illusoria appare nel punto in cui si trova. Il doppione permane per la durata dell'incantesimo, ma l'invisibilità termina se l'incantatore attacca o lancia un incantesimo.\n\nL'incantatore può utilizzare la sua azione per spostare il doppione fino al doppio della propria velocità e farlo gesticolare, parlare e comportare in qualsiasi maniera egli scelga.\n\nL'incantatore può vedere attraverso gli occhi della replica ed udire attraverso le sue orecchie come se si trovasse nello stesso punto. In ciascuno dei propri turni, come azione bonus, l'incantatore può passare dall'utilizzare i propri sensi a quelli della replica o viceversa. Mentre l'incantatore utilizza i sensi del doppione, si trova cieco e sordo in rapporto all'ambiente che lo circonda." },
  "Telecinesi": { livello:5, scuola:"Trasmutazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"L'incantatore ottiene la capacità di spostare o manipolare le creature o gli oggetti con la forza del pensiero.\n\nQuando lancia l'incantesimo e come sua azione ogni round per la durata dell'incantesimo, può proiettare la sua volontà su una creatura o un oggetto situato entro gittata e che egli sia in grado di vedere, causando l'effetto appropriato sottostante.\n\nL'incantatore può influenzare lo stesso bersaglio round dopo round, oppure sceglierne uno nuovo in qualsiasi momento.\n\nSe cambia bersaglio, il bersaglio precedente non è più influenzato dall'incantesimo\n\n**Creatura. **L'incantatore può tentare di muovere una creatura di taglia Enorme o inferiore, effettuando una prova di caratteristica con la propria caratteristica da incantatore contrapposta alla prova di Forza della creatura. Se vince la contesa, muove la creatura di un massimo di 9 metri in qualsiasi direzione, anche verticalmente, ma non oltre la gittata dell'incantesimo. Fino alla fine del turno successivo dell'incantatore, la creatura è trattenuta dalla morsa telecinetica. Una creatura sollevata verticalmente rimane sospesa a mezz'aria. Nei round successivi, l'incantatore può usare la sua azione per tentare di mantenere la sua morsa telecinetica sulla creatura ripetendo la contesa.\n\n**Oggetto. **L'incantatore può tentare di muovere un oggetto dal peso massimo di 500 kg. Se l'oggetto non è indossato o trasportato, l'incantatore può muoverlo automaticamente di un masimo di 9 metri in qualsiasi direzione, ma non oltre la gittata di questo incantesimo. Se l'oggetto è indossato o trasportato da una creatura, l'incantatore deve effettuare una prova di caratteristica con la sua caratteristica da incantatore contrapposta a una prova di Forza di quella creatura. Se vince la contesa, strappa l'oggetto a quella creatura e può muoverlo di un massimo di 9 metri in qualsiasi direzione, ma non oltre la gittata di questo incantesimo. L'incantatore può esercitare un controllo più preciso, come manipolare un semplice strumento, aprire una porta o un contenitore, riporre o prelevare un oggetto da un contenitore aperto o versare i contenuti di una fiala." },
  "Crea Morti Viventi": { livello:6, scuola:"Necromanzia", classi:["Chierico","Mago","Warlock"], tempo:"1 min", gittata:"3m", desc:"L'incantatore può lanciare questo incantesimo solo di notte.\n\nSceglie fino a tre cadaveri umanoidi di taglia Media o Piccola situati entro gittata.\n\nOgni cadavere diventa un ghoul sotto il suo controllo. (Il DM possiede le statistiche di gioco di queste creature).\n\nA ogni suo turno l'incantatore può usare un'azione bonus per comandare mentalmente qualsiasi creatura da lui creata tramite questo incantesimo e situata entro 36 metri da lui (se controlla più creature, può comandarle tutte o nessuna allo stesso tempo, impartendo lo stesso comando a ogni creatura).\n\nL'incantatore decide quale azione effettuerà la creatura e dove si muoverà durante il suo turno successivo, oppure può impartire un comando generale, come per esempio vigilare su una camera o un corridoio in particolare.\n\nSe l'incantatore non impartisce alcun comando, la creatura si limita a difendersi dalle creature ostili.\n\nUna volta ricevuto un ordine, la creatura continua a seguirlo finché non ha portato a termine il compito.\n\nLa creatura rimane sotto il controllo dell'incantatore per 24 ore, dopodiché smette di obbedire ai comandi che l'incantatore le ha impartito.\n\nPer mantenere il controllo della creatura per altre 24 ore, l'incantatore deve lanciare di nuovo questo incantesimo su di essa prima che l'attuale periodo di 24 ore termini. Questo uso dell'incantesimo gli permette di ristabilire il controllo su un massimo di tre creature da lui animate tramite questo incantesimo, anziché animarne di nuove.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello, anima o ristabilisce il controllo su quattro ghoul. Quando lancia questo incantesimo usando uno slot incantesimo di 8° livello, anima o ristabilisce il controllo su cinque ghoul, o due ghast o wight. Quando lancia questo incantesimo usando uno slot incantesimo di 9° livello, anima o ristabilisce il controllo su sei ghoul, tre ghast o wight, o due mummie." },
  "Evoca Demone": { livello:6, scuola:"Evocazione", classi:["Mago","Warlock"], tempo:"1 Azione", gittata:"27m", conc:true, desc:"Evochi uno spirito immondo che assume una forma visibile entro gittata (27 metri) per 1 ora (concentrazione). Scegli la forma: Demone, Diavolo o Yugoloth.\n\nHa CA pari a 12 + livello dello slot, PF pari a 50 + 15 per ogni livello sopra il 6°, vola (Diavolo) o si teletrasporta (Yugoloth), resistenza al fuoco e compie un numero di attacchi pari alla metà del livello dello slot, infliggendo 1d6 (o 2d6) + 3 + livello di slot danni taglienti/fuoco/necrotici e proiettando aure di danno o fiamme venefiche.\n\n**Ai Livelli Superiori.** Statistiche e PF aumentano in base allo slot." },
  "Fulmine a Catena": { livello:6, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"45m", danno:"10d8", tipoDanno:"Fulmine", desc:"L'incantatore crea un fulmine che sfreccia verso un bersaglio a sua scelta entro gittata e che egli sia in grado di vedere. Tre fulmini sfrecciano poi dal bersaglio verso un massimo di altri tre bersagli, ognuno dei quali deve trovarsi entro 9 metri dal primo bersaglio. L'incantesimo può bersagliare una creatura o un oggetto, che può essere bersagliato soltanto da uno dei fulmini. Un bersaglio deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 10d8 danni da fulmine mentre se lo supera, subisce soltanto la metà di quei danni.\n\n**Ai livelli superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, un fulmine aggiuntivo sfreccia dal primo bersaglio a un altro bersaglio per ogni slot di livello superiore al 6°." },
  "Guarigione": { livello:6, scuola:"Invocazione", classi:["Chierico","Druido"], tempo:"1 Azione", gittata:"18m", danno:"70", tipoDanno:"Cura", desc:"L'incantatore sceglie una creatura entro gittata che egli è in grado di vedere. Un flusso di energia positiva investe il bersaglio, facendogli recuperare 70 punti ferita. Inoltre, questo incantesimo termina le condizioni accecato, assordato e avvelenato che affliggono il bersaglio. Utilizzo di uno slot incantesimo di livello superiore. La guarigione aumenta di 10 per ogni slot di livello superiore al 6º.\n\n**Ai Livelli Superiori.** La guarigione aumenta di 10 per ogni slot di livello superiore al 6º." },
  "Raggio Solare": { livello:6, scuola:"Invocazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso (linea 18m)", area:"Linea", danno:"6d8", tipoDanno:"Radiante", conc:true, desc:"Un bagliore di luce brillante scaturisce dalla mano dell'incantatore e genera una linea lunga 18 metri e targa 1,5 metri. Ogni creatura sulla linea deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 6d8 danni radiosi ed è accecata fino al turno successivo dell'incantatore, mentre se lo supera, subisce soltanto la metà di quei danni e non è accecata da questo incantesirao. Le melme e i non morti subiscono svantaggio a questo tiro salvezza.\n\nL'incantatore può creare una nuova linea di energia radiosa con la sua azione in qualsiasi turno finché l'incantesimo non termina. Per la durata dell'incantesimo, una scintilla di energia radiosa risplende nella mano dell'incantatore e proietta luce intensa entro un raggio di 9 metri e luce fioca per altri 9 metri. Questa luce è considerata luce solare." },
  "Trasportare Via": { livello:6, scuola:"Evocazione", classi:["Bardo","Chierico","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Tocco", desc:"Questo incantesimo crea un legame magico tra un vegetale inanimato di taglia Grande o superiore situato entro gittata e un altro vegetale, situato a qualsiasi distanza sullo stesso piano di esistenza.\n\nL'incantatore deve avere visto o toccato il vegetale di destinazione almeno una volta in precedenza.\n\nPer la durata dell'incantesimo, qualsiasi creatura può entrare nel vegetale bersaglio e uscire da quello di destinazione usando 1,5 metri di movimento." },
  "Vedere Verità": { livello:6, scuola:"Divinazione", classi:["Bardo","Chierico","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Tocco", desc:"Questo incantesimo conferisce alla creatura toccata dall'incantatore la capacità di vedere le cose per ciò che effettivamente sono.\n\nPer la durata dell'incantesimo, la creatura è dotata di vista pura, nota le porte segrete nascoste dalla magia ed è in grado di vedere sul Piano Etereo, entro un raggio di 36 metri." },
  "Dardo Incantato Superiore": { livello:7, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"36m", danno:"11d4+11", tipoDanno:"Forza", desc:"L'incantatore crea tre dardi lucenti di forza magica.\n\nOgni dardo colpisce una creatura scelta dall'incantatore, situata entro gittata e che egli sia in grado di vedere.\n\nUn dardo infligge 1d4+1 danni da forza al suo bersaglio.\n\nTutti i dardi colpiscono simultaneamente e l'incantatore può dirigerli per colpire una sola creatura o più creature.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, l'incantesimo crea un dardo aggiuntivo per ogni slot di livello superiore al 1°." },
  "Meteore": { livello:7, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"1600m", area:"Sfera", danno:"20d6", tipoDanno:"Fuoco", desc:"Crei fino a quattro meteore incandescenti che fluttuano attorno alla tua testa per la durata (concentrazione, fino a 10 minuti). Con un'azione bonus nel tuo turno o quando lanci l'incantesimo, puoi scagliare fino a due meteore contro bersagli entro 36 metri.\n\nEffettui un attacco magico a distanza per ciascuna meteora: se colpisci, infliggi 4d12 danni da fuoco o radianti. Inoltre, le meteore emanano luce intensa per 9 metri e luce fioca per altri 9 metri." },
  "Regressione": { livello:7, scuola:"Ammaliamento", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"9m", desc:"Attacchi la mente di una creatura visibile entro gittata (45 metri), frantumandone l'intelletto e la personalità. Il bersaglio subisce 4d6 danni psichici e deve effettuare un tiro salvezza su Intelligenza.\n\nSe fallisce, i suoi punteggi di Intelligenza e Carisma scendono entrambi a 1. La creatura non può lanciare incantesimi, attivare oggetti magici, comprendere linguaggi o comunicare in modo intelligibile. Può comunque riconoscere i suoi amici e proteggerli. Alla fine di ogni periodo di 30 giorni, la creatura può ripetere il tiro salvezza per riprendersi." },
  "Resurrezione": { livello:7, scuola:"Necromanzia", classi:["Bardo","Chierico"], tempo:"1 ora", gittata:"Tocco", desc:"Toccando una creatura morta da non più di un secolo, che non sia morte di vecchiaia, e che non sia un non-morto. Qualora la sua anima fosse consenziente, il bersaglio torna in vita con tutti i suoi punti ferita.\n\nL'incantesimo neutralizza ogni veleno e cura ogni malattia comune. Ma non può curare malattie di origine magica e maledizioni. L'incantesimo inoltre, rimargina ogni ferita mortale e ripristina ogni parte mancate del corpo.\n\nTornare dai morti è un esperienza estenuante. Il bersaglio riceve un -4 a tutti i tiri per colpire, tiri salvezza e tiri di abilità. Ogni volta che si finisce un riposo lungo , la penalità si riduce di 1 fino a svanire\n\nSe il bersaglio è rimasto morto per più di un anno, non può lanciare incantesimi, e riceve svantaggio a tutti i tiri per colpire, tiri abilità e tiri salvezza fino alla fine di un riposo lungo." },
  "Antimagia": { livello:8, scuola:"Abiurazione", classi:["Chierico","Mago"], tempo:"1 Azione", gittata:"Sé stesso (sfera 3m)", area:"Sfera", conc:true, desc:"Una sfera invisibile di antimagia con raggio di 3 metri ti circonda per la durata dell'incantesimo (concentrazione, fino a 1 ora). L'area all'interno della sfera è separata dall'energia magica che pervade il multiverso.\n\nAll'interno della sfera nessun incantesimo può essere lanciato, gli oggetti magici diventano mondani e le evocazioni o creature create magicamente svaniscono temporaneamente finché si trovano nella sfera. Gli incantesimi e gli altri effetti magici non possono oltrepassare la sfera o bersagliare alcunché al suo interno." },
  "Dominare Mostri": { livello:8, scuola:"Ammaliamento", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"L'incantatore tenta di soggiogare una creatura entro gittata e che egli sia in grado di vedere.\n\nQuella creatura deve superare un tiro salvezza su Saggezza, altrimenti sarà affascinata dall'incantatore per la durata dell'incantesimo.\n\nSe l'incantatore o le creature a lui amichevoli stanno combattendo contro la creatura, quest'ultima dispone di vantaggio al tiro salvezza.\n\nMentre la creatura è affascinata, l'incantatore dispone di un legame telepatico con essa finché entrambi si trovano sullo stesso piano di esistenza. L'incantatore può usare questo legame telepatico per impartire comandi alla creatura finché è cosciente (nessuna azione richiesta), ed essa farà del suo meglio per obbedire.\n\nL'incantatore può specificare un corso d'azione semplice e generico come \"attaca quella creatura\", \"corri fin laggiù\" o \"portami quell'oggetto\". Se la creatura porta a termine l'ordine e non riceve ulteriori indicazioni da parte dell'incantatore, essa si difende e si protegge al meglio delle sue capacità.\n\nL'incantatore può usare la sua azione per assumere il controllo totale e preciso del bersaglio. Fino alla fine del turno successivo dell'incantatore, la creatura effettua soltanto le azioni scelte dall'incantatore e non fa niente che l'incantatore non le consenta di fare. Durante questo periodo, l'incantatore può anche fare in modo che la creatura usi una reazione, ma per farlo dovrà usare la sua stessa reazione.\n\nOgni volta che il bersaglio subisce danni, effettua un nuovo tiro salvezza su Saggezza contro l'incantesimo. Se lo supera, l'incantesimo termina.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo con uno slot incantesimo di 9° livello, la durata diventa concentrazione, fino a 8 ore." },
  "Incendio": { livello:8, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"750m", area:"Sfera", danno:"12d6", tipoDanno:"Fuoco", desc:"Una nube tempestosa turbinante di fumo denso e braci incandescenti compare in una sfera con raggio di 6 metri centrata su un punto entro gittata (45 metri). L'area è pesantemente oscurata per la durata (concentrazione, fino a 1 minuto).\n\nOgni creatura nell'area quando la nube compare, o che vi entra per la prima volta in un turno o vi termina il proprio turno, deve superare un tiro salvezza su Destrezza, altrimenti subisce 10d8 danni da fuoco (la metà su successo). La nube si allontana da te di 3 metri in linea retta all'inizio di ogni tuo turno." },
  "Potere delle Parole": { livello:8, scuola:"Ammaliamento", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", desc:"Pronunci una singola parola di potere arcano che risuona nella mente di una creatura visibile entro gittata (18 metri). Se la creatura bersaglio possiede 150 punti ferita o meno, viene sopraffatta dal potere:\n\n- Se la parola è Stordire (Power Word Stun): la creatura è stordita. Può effettuare un tiro salvezza su Costituzione alla fine di ogni suo turno per riprendersi.\n- Se ha più punti ferita della soglia, l'incantesimo non ha alcun effetto su di essa." },
  "Tornado": { livello:8, scuola:"Evocazione", classi:["Druido"], tempo:"1 Azione", gittata:"90m", area:"Cilindro", danno:"4d10", tipoDanno:"Contundente", conc:true, desc:"Prendi il controllo dell'aria in un cubo di 30 metri visibile entro gittata (90 metri) per la durata (concentrazione, fino a 1 ora). Puoi scegliere di creare venti di burrasca o tornado:\n\n- **Venti Ascendenti:** Il vento solleva le creature facendole levitare dolcemente o scagliandole in aria.\n- **Venti Discendenti:** Il vento schiaccia le creature volanti verso il suolo, imponendo tiro salvezza su Forza per non cadere prone.\n- **Venti Orizzontali:** Soffi potenti spingono le creature lontane e disperdono gas, nebbie e fiamme non protette nell'area." },
  "Desiderio": { livello:9, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso", desc:"Desiderio è il più potente incantesimo che una creatura mortale sia in grado di lanciare.\n\nPronunciando semplicemente il proprio desiderio ad alta voce, l'incantatore altera le fondamenta stesse della realtà in base a ciò che desidera.\n\nL'uso base di questo incantesimo è riprodurre un qualsiasi altro incantesimo di livello pari o inferiore all'8°.\n\nL'incantatore non deve soddisfare alcun requisito di quell'incantesimo, nemmeno gli eventuali requisiti in componenti costose. L'incantesimo ha semplicemente effetto.\n\nIn alternativa, l'incantatore può creare uno degli effetti seguenti a sua scelta:\n\n- L'incantatore crea un oggetto dal valore massimo di 25.000 mo che non sia un oggetto magico. L'oggetto non può essere più lungo di 90 metri in ogni dimensione e compare a terra, in uno spazio libero che l'incantatore sia in grado di vedere.\n\n- L'incantatore consente a un massimo di venti creature che egli sia in grado di vedere di recuperare tutti i punti ferita e terminare tutti gli effetti su di esse come descritto nell'incantesimo Ristorare Superiore.\n\n- L'incantatore conferisce a un massimo di dieci creature che egli sia in grado di vedere resistenza a un tipo di danni a sua scelta.\n\n- L'incantatore conferisce a un massimo di dieci creature che egli sia in grado di vedere immunità a un singolo incantesimo o a un altro effetto magico per 8 ore. Per esempio, potrebbe rendere sé stesso e tutti i suoi compagni immuni all'attacco da risucchio di un lich.\n\n- L'incantatore annulla un singolo evento recente imponendo la ripetizione di un qualsiasi tiro effettuato entro l'ultimo round (incluso il suo ultimo round). La realtà viene rimodellata e si adatta al nuovo risultato. Per esempio, un incantesimo desiderio potrebbe annullare il tiro salvezza superato di un avversario, il colpo critico di un nemico o il tiro salvezza fallito di un amico. L'incantatore può imporre che il tiro ripetuto sia effettuato con vantaggio o svantaggio e può scegliere se usare il tiro ripetuto o il tiro originale.\n\nL'incantatore potrebbe essere in grado di realizzare qualcosa che vada oltre gli esempi soprastanti, dichiarando il suo desiderio al DM nel modo più preciso possibile. Il DM ha la massima libertà di decidere cosa accade in questi casi: più potente è il desiderio, maggiori sono le probabilità che qualcosa vada storto.\n\nL'incantesimo potrebbe semplicemente fallire, e l'effetto desiderato dall'incantatore potrebbe avverarsi solo in parte, oppure l'incantatore potrebbe subire delle conseguenze inaspettate a seguito della formulazione del desiderio. Per esempio, se desidera che un suo nemico sia morto, potrebbe essere portato avanti nel tempo in un periodo in cui quel nemico non è più in vita, finendo per essere rimosso dal gioco a tutti gli effetti. Analogamente, se desidera un oggetto magico leggendario o un artefatto, potrebbe essere trasportato istantaneamente in presenza del legittimo proprietario dell'oggetto.\n\nLa tensione provocata dal lancio di questo incantesimo per produrre un qualsiasi effetto diverso dalla duplicazione di un altro incantesimo debilita l'incantatore. Dopo avere subito quella tensione, ogni volta che l'incantatore lancia un incantesimo prima di avere completato un riposo lungo subisce 1d10 danni necrotici per livello di quell'incantesimo. Questi danni non possono essere ridotti o prevenuti in alcun modo. Inoltre, la Forza dell'incantatore scende a 3 per 2d4 giorni (se non è già pari o inferiore a 3). Per ognuno di quei giorni trascorso a riposare e a non fare nulla al di fuori di attività poco impegnative, il tempo di recupero rimanente diminuisce di 2 giorni.\n\nEsiste infine una probabilità del 33 per cento che l'incantatore non sia in grado di lanciare desiderio mai più, se non riesce a reggere questa tensione." },
  "Fermare il Tempo": { livello:9, scuola:"Trasmutazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso", desc:"L'incantatore ferma brevemente lo scorrere del tempo per chiunque eccetto se stesso. Il tempo non scorre per le altre creature, mentre l'incantatore guadagna 1d4+1 turni di seguito, durante i quali può effettuare azioni e muoversi come di consueto.\n\nQuesto incantesimo termina se una delle azioni che l'incantatore effettua durante questo periodo, o qualsiasi effetto che egli possa creare durante questo periodo, interessa una creatura diversa dall'incantatore od un oggetto indossato o portato da qualcuno diverso dall'incantatore.\n\nInoltre, l'incantesimo termina se l'incantatore si sposta in un luogo a più di 300 metri dalla zona in cui è stato lanciato." },
  "Lama della Catastrofe": { livello:9, scuola:"Invocazione", classi:["Mago","Stregone","Warlock"], tempo:"Azione Bonus", gittata:"18m", danno:"4d12", tipoDanno:"Forza", conc:true, desc:"Crei una fessura planare a forma di lama scintillante di pura distruzione spaziale entro gittata (18 metri) per 1 minuto (concentrazione). Quando lanci l'incantesimo e come azione bonus in ogni tuo turno successivo, puoi muovere la lama fino a 9 metri ed effettuare due attacchi con essa.\n\nCiascun attacco è un attacco magico in mischia contro un bersaglio entro 1,5 metri dalla lama. Se colpisci, infliggi 4d12 danni da forza. Questo attacco mette a segno un colpo critico con un risultato di 18-20 al d20; su un colpo critico, infligge 12d12 danni da forza invece del normale raddoppio. La lama può oltrepassare qualsiasi barriera magica, incluso un Muro di Forza." },
  "Meteore di Massa": { livello:9, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"1600m", area:"Sfera", danno:"20d6+20d6", tipoDanno:"Fuoco/Contundente", desc:"Fino a quattro sfere infuocate di roccia cosmica precipitano al suolo in punti a tua scelta visibili entro gittata (1,6 km). Ciascuna meteora esplode all'impatto in una sfera con raggio di 12 metri.\n\nOgni creatura nell'area di ciascuna esplosione deve effettuare un tiro salvezza su Destrezza. Subisce 20d6 danni da fuoco e 20d6 danni contundenti se fallisce il tiro salvezza, o la metà di quei danni se lo supera. Una creatura situata nell'area di più esplosioni è colpita da una sola di esse. L'incantesimo danneggia gli oggetti e incendia quelli infiammabili nell'area." },
  "Porta del Portale": { livello:9, scuola:"Evocazione", classi:["Chierico","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"Crei un portale circolare bidirezionale fino a 6 metri di diametro che collega uno spazio libero visibile entro gittata (18 metri) a una precisa destinazione situata su un altro piano di esistenza. Il portale dura per la durata dell'incantesimo (concentrazione, fino a 1 minuto).\n\nQualsiasi creatura o oggetto che attraversa il portale viene istantaneamente trasportato sull'altro piano, comparendo nello spazio libero più vicino al portale di destinazione. Quando lanci l'incantesimo, puoi pronunciare il vero nome di una specifica creatura: il portale si apre nelle sue vicinanze e la creatura viene risucchiata attraverso il portale, comparendo nel tuo spazio." },
  "Profezia": { livello:9, scuola:"Divinazione", classi:["Chierico"], tempo:"1 min", gittata:"Sé stesso", desc:"Tocchi una creatura consenziente conferendole la capacità di scrutare nel futuro immediato per la durata di 8 ore. Per tutta la durata, il bersaglio non può essere sorpreso e ha vantaggio a tutti i tiri per colpire, alle prove di caratteristica e ai tiri salvezza.\n\nInoltre, tutte le altre creature hanno svantaggio ai tiri per colpire effettuati contro il bersaglio per tutta la durata dell'incantesimo. Questo incantesimo termina immediatamente se lo lanci di nuovo prima che siano trascorse le 8 ore." },
  "Resurrezione Pura": { livello:9, scuola:"Necromanzia", classi:["Chierico","Druido"], tempo:"1 ora", gittata:"Tocco", desc:"L'incantatore tocca una creatura che è morta da non più di 200 anni e che è morta per qualsiasi motivo tranne la vecchiaia. Se l'anima della creatura è libera e disponibile, viene ripristinata con tutti i suoi punti ferita. Questo incantesimo chiude tutte le ferite, neutralizza ogni veleno, cura tutte le malattie e toglie qualsiasi maledizione. L'incantesimo sostituisce gli organi e gli arti danneggiati o mancanti. Se la creatura era non morta, viene ripristinata nella sua forma non-non-morta. L'incantesimo può fornire un nuovo corpo se l'originale non esiste più, nel qual caso l'incantatore deve pronunciare il nome della creatura. La creatura appare in uno spazio non occupato che l'incantatore sceglie entro 3 metri da esso." },
  "Tempo Inverso": { livello:9, scuola:"Trasmutazione", classi:["Mago"], tempo:"1 Azione", gittata:"Sé stesso", desc:"Manipoli la tessitura stessa del tempo e della causalità per un breve istante. Riavvolgi il flusso temporale locale tornando indietro di esattamente un round (6 secondi):\n\nTutti i danni subiti, le risorse spese, i tiri effettuati, gli spostamenti e le azioni intraprese durante l'ultimo round da qualsiasi creatura entro 36 metri vengono completamente annullati, e lo stato del mondo ritorna esattamente com'era all'inizio del round precedente, mantenendo solo la tua consapevolezza di ciò che è accaduto. Non puoi lanciare questo incantesimo più di una volta per riposo lungo." },
  "Controllo delle Fiamme": { livello:0, scuola:"Trasmutazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"18m", desc:"Scegli una fiamma non magica visibile entro gittata (18 metri) che possa essere contenuta in un cubo con spigolo di 1,5 metri. Ne controlli la forma in uno dei seguenti modi:\n\n- Espandi la fiamma di 1,5 metri in una direzione in cui sia presente combustibile (come legno o olio).\n- Estingui istantaneamente le fiamme nel cubo.\n- Raddoppi o dimezzi l'area di luce intensa e fioca emessa dalla fiamma, ne cambi il colore, o entrambe le cose, per 1 ora.\n- Fai apparire forme semplici (come sagome animate di creature o simboli) all'interno delle fiamme per 1 ora." },
  "Creare Falò": { livello:0, scuola:"Evocazione", classi:["Artefice","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", danno:"1d8", tipoDanno:"Fuoco", conc:true, desc:"Crei un falò magico a terra in un punto visibile entro gittata (18 metri). Fino al termine dell'incantesimo (concentrazione, fino a 1 minuto), il falò occupa un cubo di 1,5 metri. Ogni creatura nell'area del falò quando lo lanci deve superare un tiro salvezza su Destrezza, altrimenti subisce 1d8 danni da fuoco. Una creatura deve effettuare il tiro salvezza anche quando entra nell'area del falò per la prima volta in un turno o quando vi termina il proprio turno. Il falò incendia gli oggetti infiammabili non indossati o trasportati.\n\n**Potenziamento per i Trucchetti.** I danni aumentano di 1d8 al 5° livello (2d8), all'11° livello (3d8) e al 17° livello (4d8)." },
  "Modellare la Terra": { livello:0, scuola:"Trasmutazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"9m", desc:"Scegli una porzione di terra o pietra visibile entro gittata (9 metri) che possa essere contenuta in un cubo con spigolo di 1,5 metri. La manipoli in uno dei seguenti modi:\n\n- Se prendi di mira un'area di terra sciolta, puoi scavarne istantaneamente fino a un cubo di 1,5 metri e depositarla a una distanza massima di 1,5 metri.\n- Fai comparire forme, parole o disegni sulla terra o pietra prescelta per 1 ora.\n- Trasformi la terra o pietra in terreno difficile, oppure trasformi terreno difficile in terreno normale, per 1 ora." },
  "Plasmare l'Acqua": { livello:0, scuola:"Trasmutazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"9m", desc:"Scegli un'area d'acqua visibile entro gittata (9 metri) che possa essere contenuta in un cubo con spigolo di 1,5 metri. La manipoli in uno dei seguenti modi:\n\n- Sposti o alteri istantaneamente il flusso d'acqua fino a 1,5 metri in qualsiasi direzione.\n- Fai assumere all'acqua forme semplici o cambi colore e opacità per 1 ora.\n- Congeli l'acqua, purché non vi siano creature al suo interno. L'acqua si scongela dopo 1 ora." },
  "Infusione Magica": { livello:0, scuola:"Trasmutazione", classi:["Artefice","Druido","Warlock"], tempo:"1 Azione Bonus", gittata:"Tocco", danno:"1d6", tipoDanno:"Contundente", desc:"Tocchi da uno a tre ciottoli o sassi non magici infondendoli di magia per la durata di 1 minuto. Tu o un'altra creatura potete effettuare un attacco con incantesimo a distanza con uno dei sassi scagliandolo con la mano o con una fionda (gittata 18 metri per il lancio a mano, gittata normale della fionda).\n\nChi effettua l'attacco usa il tuo modificatore di caratteristica da incantatore per il tiro per colpire. Se colpisce, il bersaglio subisce danni contundenti pari a 1d6 + il tuo modificatore di caratteristica da incantatore. Che colpisca o manchi, l'incantesimo su quel sasso ha termine." },
  "Tuono": { livello:0, scuola:"Invocazione", classi:["Artefice","Bardo","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso (1,5m)", danno:"1d6", tipoDanno:"Tuono", desc:"Provochi uno scoppio di tuono fragoroso che risuona fino a 30 metri di distanza. Ogni creatura diversa da te entro 1,5 metri deve superare un tiro salvezza su Costituzione, altrimenti subisce 1d6 danni da tuono.\n\n**Potenziamento per i Trucchetti.** I danni aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6)." },
  "Ferocia Primordiale": { livello:0, scuola:"Trasmutazione", classi:["Druido"], tempo:"1 Azione", gittata:"Sé stesso (1,5m)", danno:"1d10", tipoDanno:"Acido", desc:"I tuoi denti o le tue unghie si allungano e si affilano, gocciolando di acido corrosivo. Effettui un attacco in mischia con questo incantesimo contro una creatura entro 1,5 metri. Se colpisci, il bersaglio subisce 1d10 danni da acido. Dopo l'attacco, la tua fisionomia torna normale.\n\n**Potenziamento per i Trucchetti.** I danni aumentano di 1d10 quando raggiungi il 5° livello (2d10), l'11° livello (3d10) e il 17° livello (4d10)." },
  "Amicizia con gli Animali": { livello:1, scuola:"Ammaliamento", classi:["Bardo","Druido","Ranger"], tempo:"1 Azione", gittata:"9m", desc:"Grazie a questo incantesimo l'incantatore convince una bestia che non ha alcuna intenzione di nuocerle. L'incantatore sceglie una bestia entro gittata e che egli sia in grado di vedere. La bestia deve vedere e sentire l'incantatore. Se l'Intelligenza della bestia è pari o superiore a 4, l'incantesimo fallisce. Altrimenti, la bestia deve superare un tiro salvezza su Saggezza o essere affascinata dall'incantatore per la durata dell'incantesimo. Se l'incantatore o uno dei suoi compagni infligge danni al bersaglio, l'incantesimo termina.\n\n**Al Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 2° livello o superiore, può influenzare una bestia aggiuntiva per ogni slot di livello superiore al 1°." },
  "Bocciolo di Ghiaccio": { livello:1, scuola:"Evocazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"18m", danno:"1d10+2d6", tipoDanno:"Perforante/Freddo", desc:"Scagli una scheggia di ghiaccio solido contro una creatura entro gittata (18 metri). Effettui un attacco con incantesimo a distanza contro il bersaglio: se colpisci, infliggi 1d10 danni perforanti. Che tu colpisca o manchi, la scheggia esplode immediatamente in frammenti taglienti: il bersaglio e ogni creatura entro 1,5 metri da esso devono superare un tiro salvezza su Destrezza, altrimenti subiscono 2d6 danni da freddo.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot di 2° livello o superiore, il danno da freddo aumenta di 1d6 per ogni slot superiore al 1°." },
  "Creare o Distruggere Acqua": { livello:1, scuola:"Trasmutazione", classi:["Chierico","Druido"], tempo:"1 Azione", gittata:"9m", desc:"L'incantatore esegue una delle seguenti azioni: Creare acqua. L'incantatore crea fino a 40 litri d'acqua pulita in un contenitore aperto entro gittata. In alternativa, l'acqua cade sotto forma di pioggia in un cubo con spigolo di 9 metri entro gittata, estinguendo le fiamme presenti nell'area. Distruggere acqua. L'incantatore distrugge fino a 40 litri d'acqua in un contenitore aperto entro gittata. In alternativa, distrugge la nebbia presente in un cubo con spigolo di 9 metri entro gittata. Utilizzo di uno slot incantesimo di livello superiore. L'incantatore crea o distrugge 40 litri aggiuntivi d'acqua, oppure la grandezza del cubo aumenta di 1,5 metri per spigolo, per ogni slot di livello superiore al 1º.\n\n**Ai Livelli Superiori.** L'incantatore crea o distrugge 40 litri aggiuntivi d'acqua, oppure la grandezza del cubo aumenta di 1,5 metri per spigolo, per ogni slot di livello superiore al 1º." },
  "Individuazione del Veleno e delle Malattie": { livello:1, scuola:"Divinazione", classi:["Chierico","Druido","Paladino","Ranger"], tempo:"1 Azione", gittata:"Sé stesso", conc:true, rituale:true, desc:"Se esistono o appaiono entro 9 metri, percepisci la presenza di veleni, creature velenose e malattie. Anche la loro posizione e il loro tipo diventano noti.\n\nQuesto incantesimo è bloccato da 30 cm di pietra, 1 pollice di metallo comune, un sottile foglio di piombo o 1 metro di legno o terra." },
  "Purificare Cibo e Bevande": { livello:1, scuola:"Trasmutazione", classi:["Chierico","Druido","Paladino"], tempo:"1 Azione", gittata:"3m", rituale:true, desc:"L'incantatore rimuove veleno e marciume da cibi e bevande non magici situati in una sfera del raggio di 1,5 metri centrata su un punto entro gittata." },
  "Salto": { livello:1, scuola:"Trasmutazione", classi:["Artefice","Druido","Mago","Ranger","Stregone"], tempo:"1 Azione", gittata:"Tocco", desc:"minuto L'incantatore tocca una creatura consenziente. La creatura, in ogni suo turno fino al termine dell'incantesimo, può saltare fino a 9 metri, usando 3 metri di movimento. Utilizzo di uno slot incantesimo di livello superiore. L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º.\n\n**Ai Livelli Superiori.** L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 1º." },
  "Calmare Emozioni": { livello:2, scuola:"Ammaliamento", classi:["Bardo","Chierico","Druido"], tempo:"1 Azione", gittata:"18m", area:"Sfera", conc:true, desc:"L'incantatore tenta di sopprimere le emozioni più intense in un gruppo di persone. Ogni umanoide entro una sfera del raggio di 6 metri centrata su un punto scelto dall'incantatore entro gittata deve effettuare un tiro salvezza su Carisma; una creatura può scegliere di fallire questo tiro salvezza, se lo desidera. Se una creatura fallisce il suo tiro salvezza, l'incantatore sceglie uno dei due effetti seguenti. L'incantatore può sopprimere qualsiasi effetto che rende un bersaglio affascinato o spaventato. Quando questo incantesimo termina, ogni effetto soppresso torna a essere applicato, purché la sua durata non si sia esaurita nel frattempo. In alternativa, l'incantatore può rendere un bersaglio indifferente ad alcune creature da lui scelte nei cui confronti il bersaglio risulterebbe ostile. Questa indifferenza termina se il bersaglio viene attaccato o danneggiato da un incantesimo, o se vede uno dei suoi amici subire danni. Quando l'incantesimo termina, la creatura torna a essere ostile, a meno che il DM non decida altrimenti." },
  "Lama Infuocata": { livello:2, scuola:"Invocazione", classi:["Druido","Stregone"], tempo:"1 Azione Bonus", gittata:"Sé stesso", danno:"3d6", tipoDanno:"Fuoco", conc:true, desc:"L'incantatore evoca una lama infuocata nella sua mano libera.\n\nLa lama ha forma e dimensioni simili a quelle di una scimitarra e permane per la durata dell'incantesimo.\n\nSe l'incantatore la lascia andare, la lama scompare, ma può essere evocata di nuovo con un'azione bonus da parte dell'incantatore.\n\nL'incantatore può usare la sua azione per effettuare un attacco in mischia con questo incantesimo con la lama infuocata. Se colpisce, il bersaglio subisce 3d6 danni da fuoco.\n\nLa lama infuocata proietta luce intensa entro un raggio di 3 metri e luce fioca per altri 3 metri.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni aumentano di 1d6 per ogni due slot oltre il 2°." },
  "Localizzare Animali o Piante": { livello:2, scuola:"Divinazione", classi:["Bardo","Druido","Ranger"], tempo:"1 Azione", gittata:"Sé stesso", rituale:true, desc:"L'incantatore descrive o nomina un tipo specifico di bestia o vegetale.\n\nConcentrandosi sulla voce della natura che echeggia attorno a lui, apprende la direzione e la distanza fino alla\n\ncreatura o al vegetale di quel tipo più vicino entro 7,5 km, se ne è presente almeno uno." },
  "Messaggero Animale": { livello:2, scuola:"Ammaliamento", classi:["Bardo","Druido","Ranger"], tempo:"1 Azione", gittata:"9m", rituale:true, desc:"Grazie a questo incantesimo, l'incantatore usa un animale per trasmettere un messaggio, scegliendo una bestia Minuscola entro gittata e che egli sia in grado di vedere (per esempio uno scoiattolo, una ghiandaia o un pipistrello). L'incantatore specifica un luogo, che deve avere già visitato, e un destinatario che corrisponda a una descrizione generica come \"un uomo o una donna che indossi l'uniforme della guardia cittadina\" o \"un nano dai capelli rossi che indossi un cappello a punta\". Pronuncia inoltre un messaggio di un massimo di venticinque parole. La bestia bersaglio viaggia per la durata dell'incantesimo verso il luogo specificato, percorrendo circa 75 km in 24 ore nel caso dl un messaggero volante, o 37,5 km nel caso di altri animali. Quando il messaggero arriva, trasmette il suo messaggio alla creatura che l'incantatore ha descritto, replicando il suono di sua scelta. li messaggero parla solo con una creatura corrispondente alla descrizione fornita dall'incantatore. Se il messaggero non giunge a destinazione prima della fine dell'incantesimo, il messaggio è perduto e la bestia si rimette in viaggio verso il punto in cui l'incantesimo è stato lanciato\n\n**Al Livelli Superiori. **Se l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3• livello o superiore, la durata dell'incantesimo aumenta di 48 ore per ogni slot di livello superiore al 2•." },
  "Senso delle Bestie": { livello:2, scuola:"Divinazione", classi:["Druido","Ranger"], tempo:"1 Azione", gittata:"Tocco", conc:true, rituale:true, desc:"Tocchi una bestia consenziente. Per la durata (concentrazione, fino a 1 ora, rituale), puoi usare la tua azione per vedere attraverso i suoi occhi e sentire attraverso le sue orecchie, continuando a farlo finché non usi un'azione per tornare ai tuoi sensi normali. Mentre percepisci attraverso la bestia, benefici di qualsiasi senso speciale posseduto dalla creatura, ma il tuo corpo è accecato e assordato." },
  "Fondersi nella Pietra": { livello:3, scuola:"Trasmutazione", classi:["Chierico","Druido"], tempo:"1 Azione", gittata:"Tocco", rituale:true, desc:"L'incantatore entra in un oggetto o in una superficie di pietra sufficientemente grande da contenere il suo intero corpo, fondendosi nella pietra assieme a tutto l'equipaggiamento che trasporta per la durata dell'incantesimo.\n\nUsando il suo movimento, egli entra nella pietra in un punto che è in grado di toccare.\n\nNulla della sua presenza rimane visibile o individuabile da qualsiasi senso non magico.\n\nFinché è fuso con la pietra, l'incantatore non può vedere cosa accade all'esterno e ogni prova di Saggezza (Percezione) che effettua per udire suoni subisce svantaggio.\n\nL'incantatore rimane cosciente del passaggio del tempo e può lanciare incantesimi su sé stesso finché è fuso nella pietra.\n\nPuò usare il suo movimento per lasciare la pietra nel punto in cui è entrato, cosa che termina l'incantesimo. Altrimenti, è impossibilitato a muoversi.\n\nGli eventuali danni minori inferti alla pietra non feriscono l'incantatore,, ma la sua distruzione parziale o un'alterazione della sua forma (se sufficiente a fare in modo che non contenga più il suo corpo) provoca l'espulsione dell'incantatore e gli infligge 6d6 danni contundenti.\n\nLa distruzione completa della pietra (o la sua trasmutazione in una sostanza diversa) provoca l'espulsione dell'incantatore e gli infligge 50 danni condundenti.\n\nQuando l'incantatore viene espulso, cade a terra prono nello spazio libero più vicino al punti in cui era entrato." },
  "Forma Gassosa": { livello:3, scuola:"Trasmutazione", classi:["Artefice","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"fino a 1 ora Una creatura consenziente, toccata dall'incantatore, muta forma, insieme a tutto ciò che indossa o trasporta, trasformandosi in una nube fosca per la durata dell'incantesimo. L'effetto svanisce se il bersaglio scende a 0 punti ferita o se effettua un'azione di Magia per terminare l'incantesimo su di sé. Mentre si trova in questa forma, una velocità di volo di 3 metri è l'unico metodo di movimento del bersaglio, che può fluttuare e può entrare nello spazio di un'altra creatura e occuparlo. Il bersaglio è resistente ai danni contundenti, perforanti e taglienti; è immune alla condizione prono; dispone di vantaggio ai tiri salvezza su Forza, Destrezza e Costituzione. Il bersaglio può passare attraverso aperture strette, tuttavia tratta i liquidi come fossero superfici solide. Il bersaglio non può parlare o manipolare oggetti e quelli che trasporta o impugna non possono essere lasciati cadere, usati o manipolati in alcun modo. Infine, il bersaglio non può attaccare o lanciare incantesimi. Utilizzo di uno slot incantesimo di livello superiore. L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 3º.\n\n**Ai Livelli Superiori.** L'incantatore può bersagliare una creatura aggiuntiva per ogni slot di livello superiore al 3º." },
  "Frecce di Fuoco": { livello:3, scuola:"Trasmutazione", classi:["Artefice","Druido","Ranger","Stregone","Mago"], tempo:"1 Azione Bonus", gittata:"Tocco", danno:"1d6", tipoDanno:"Fuoco", conc:true, desc:"Tocchi una faretra contenente frecce o dardi. Fino a un massimo di 12 munizioni nella faretra vengono pervase di fuoco magico per la durata (concentrazione, fino a 1 ora). Quando una creatura effettua un attacco con arma a distanza usando una di queste munizioni, l'attacco infligge 1d6 danni da fuoco extra al bersaglio se colpisce. La magia abbandona la munizione una volta scagliata.\n\n**Ai Livelli Superiori.** Per ogni livello di slot superiore al 3°, puoi infondere 2 munizioni aggiuntive." },
  "Parlare con le Piante": { livello:3, scuola:"Trasmutazione", classi:["Bardo","Druido","Ranger"], tempo:"1 Azione", gittata:"Sé stesso (9m)", desc:"L'incantatore infonde nei vegetali entro 9 metri da sé una parvenza di animazione e di volontà, nonché la capacità di comunicare con lui e di obbedire ai suoi comandi più semplici. L'incantatore può interrogare i vegetali sugli eventi avvenuti entro l'area dell'incantesimo nella giornata passata, ottenere informazioni sulle creature che sono transitate al suo interno, il clima e altre circostanze.\n\nL'incantatore può anche trasformare un terreno reso difficile dalla crescita vegetale (come per esempio arbusti e sottobosco) in un terreno ordinario che permane per la durata dell'incantesimo. In alternativa può trasformare un terreno ordinario dove siano presenti dei vegetali in un terreno ordinario dove siano presenti dei vegetali in un terreno difficile che permane per la durata dell'incantesimo, ordinando per esempio a rami e rampicanti di ostacolare gli inseguitori.\n\nI vegetali potrebbero essere in grado di effettuare altri compiti per conto dell'incantatore, a discrezione del DM. L'incantesimo non consente alle piante di sradicarsi e di deambulare, ma consente loro di muovere liberamente rami, rampicanti e viticci.\n\nSe una creatura vegetale si trova nell'area, l'incantatore può comunicare con essa come se entrambi condividessero un linguaggio, ma non ottiene alcuna capacità magica di influenzarla.\n\nQuesto incantesimo può fare in modo che i vegetali creati dall'incantesimo *intralciare* liberino una creatura trattenuta." },
  "Protezione dall'Energia": { livello:3, scuola:"Abiurazione", classi:["Artefice","Chierico","Druido","Mago","Ranger","Stregone"], tempo:"1 Azione", gittata:"Tocco", conc:true, desc:"Per la durata dell'incantesimo, una creatura consenziente toccata dall'incantatore dispone di resistenza a un tipo di danni scelto dall'incantatore:\n\n- acido\n\n- freddo\n\n- fulmine\n\n- fuoco\n\n- tuono" },
  "Controllare Acqua": { livello:4, scuola:"Trasmutazione", classi:["Chierico","Druido","Mago"], tempo:"1 Azione", gittata:"90m", area:"Cubo", conc:true, desc:"Finché l'incantesimo non termina, l'incantatore controlla una massa libera d'acqua in un'area a sua scelta, fino a un volume massimo pari a un cubo con spigolo di 30 metri. Può scegliere uno qualsiasi degli effetti seguenti quando lancia questo incantesimo. Con un'azione nel suo turno può ripetere lo stesso effetto o sceglierne uno diverso.\n\n**Deviare la Corrente**. L'incantatore fa scorrere l'acqua corrente all'interno dell'area in una direzione a sua scelta, anche se l'acqua deve superare degli ostacoli, risalire una parete o scorrere in altre direzioni improbabili. L'acqua nell'area si muove secondo le indicazioni dell'incantatore, ma una volta giunta oltre l'area dell'incantesimo, riprende a scorrere normalmente, secondo le condizioni del terreno. L'acqua continua a scorrere nella direzione scelta dall'incantatore finché l'incantesimo non termina o finché l'incantatore non sceglie un effetto diverso.\n\n**Gorgo**. Questo effetto richiede una massa d'acqua in un'area quadrata con lato di almeno 15 metri e profonda almeno 7,5 metri. Il gorgo forma un vortice largo 1,5 metri alla base e 15 metri in cima, e alto 7,5 metri. Ogni creatura o oggetto situato in acqua ed entro 7,5 metri dal vortice viene trascinato di 3 metri verso di esso. Una creatura può allontanarsi a nuoto dal vortice effettuando una prova di Forza (Atletica) contro la CD del tiro salvezza dell'incantesimo. Quando una creatura entra nel vortice per la prima volta in un turno o vi inizia il proprio turno, deve effettuare un tiro salvezza su Forza. Se lo fallisce, subisce 2d8 danni contundenti ed è catturata dal vortice finché l'incantesimo non termina, mentre se lo supera, subisce la metà dei danni e si libera dal vortice. Una creatura nel vortice può usare la sua azione per tentare di allontanarsi a nuoto da esso nel modo sopra descritto, ma subisce svantaggio alla prova di Forza (Atletica) richiesta per farlo. La prima volta in ogni turno che un oggetto entra nel vortice, quell'oggetto subisce 2d8 danni contundenti; questi danni vengono inferti in ogni round in cui l'oggetto rimane nel vortice.\n\n** Inondazione**. L'incantatore fa in modo che il livello di tutta l'acqua ferma nell'area si sollevi di un massimo di 6 metri. Se l'area include una riva, l'acqua crescente si riversa sulla terraferma. Se l'incantatore sceglie un'area contenuta in una vasta massa d'acqua, genera invece un'onda alta 6 metri da un lato dell'area all'altro, che si riversa poi in avanti. Ogni imbarcazione di taglia Enorme o inferiore che si trovi sul cammino viene trasportata dall'onda fino all'altro lato. Ogni imbarcazione di taglia Enorme o inferiore colpita dall'onda ha una probabilità del 25 per cento di capovolgersi. Il livello dell'acqua rimane elevato finché l'incantesimo non termina o finché l'incantatore non sceglie un effetto diverso. Se questo effetto ha prodotto un'onda, l'onda si ripete all'inizio del turno successivo dell'incantatore fintanto che l'effetto di inondazione permane.\n\n**Separare /e Acque**. L'incantatore fa in modo che l'acqua nell'area si separi per creare un varco. Il varco attraversa tutta l'area di effetto e le acque separate formano un muro su entrambi i lati. Il varco rimane finché l'incantesimo non termina o l'incantatore non sceglie un effetto diverso. Poi l'acqua si riversa lentamente all'interno del varco nel corso del round successivo, finché il livello normale dell'acqua non viene ripristinato." },
  "Dominare Bestie": { livello:4, scuola:"Ammaliamento", classi:["Druido","Stregone"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"L'incantatore tenta di soggiogare una bestia entro gittata e che egli sia in grado di vedere.\n\nQuella bestia deve superare un tiro salvezza su Saggezza, altrimenti sarà affascinata dall'incantatore per la durata dell'incantesimo.\n\nSe l'incantatore o le creature a lui amichevoli stanno combattendo contro la bestia, quest'ultima dispone di vantaggio al tiro salvezza.\n\nMentre la bestia è affascinata, l'incantatore dispone di un legame telepatico con essa finché entrambi si trovano sullo stesso piano di esistenza. L'incantatore può usare questo legame telepatico per impartire comandi alla creatura finché è cosciente (nessuna azione richiesta), ed essa farà del suo meglio per obbedire.\n\nL'incantatore può specificare un corso d'azione semplice e generico come \"attacca quella creatura\", \"corri fin laggiù\" o \"portami quell'oggetto\". Se la creatura porta a termine l'ordine e non riceve ulteriori indicazioni da parte dell'incantatore, essa si difende e si protegge al meglio delle sue capacità.\n\nL'incantatore può usare la sua azione per assumere il controllo totale e preciso del bersaglio.\n\nFino alla fine del turno successivo dell'incantatore, la creatura effettua soltanto le azioni scelte dall'incantatore e non fa niente che l'incantatore non le consenta di fare. Durante questo periodo, l'incantatore può anche fare in modo che la creatura usi una reazione, ma per farlo dovrà usare la sua stessa reazione.\n\nOgni volta che il bersaglio subisce danni, effettua un nuovo tiro salvezza su Saggezza contro l'incantesimo. Se lo supera, l'incantesimo termina.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo con uno slot incantesimo di 5° livello, la durata diventa concentrazione, fino a 10 minuti. Quando usa uno slot di 6° livello, la durata diventa concentrazione, fino a 1 ora. Quando usa uno slot incantesimo di 7° livello o superiore, la durata diventa concentrazione, fino a 8 ore." },
  "Evocare Creature Boschive": { livello:4, scuola:"Evocazione", classi:["Druido","Ranger"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"L'incantatore evoca creature fatate che appaiono in uno spazio non occupato che egli possa vedere entro gittata. Sceglie una delle seguenti opzioni per decidere cosa appare:\n\n- Una creatura folletto con grado sfida 2 o inferiore\n\n- Due creature folletto con grado sfida 1 o inferiore\n\n- Quattro creature folletto con grado sfida 1/2 o inferiore\n\n- Otto creature folletto con grado sfida 1/4 o inferiore\n\nUna creatura evocata scompare se ridotta a 0 punti ferita o alla fine dell'incantesimo.\n\nLe creature evocate sono amichevoli nei confronti dell'incantatore e dei suoi alleati. L'incantatore tira per l'iniziativa delle creature evocate come gruppo, che ha i propri turni. Le creature evocate obbediscono ai comandi verbali impartiti dall'incantatore (nessuna azione richiesta). Se l'incantatore non impartisce un comando, le creature evocate si difendono da eventuali altre creature ostili, ma altrimenti non intraprendono alcuna azione.\n\nIl DM possiede le statistiche delle creature.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo utilizzando determinati slot incantesimo di livello superiore, sceglie una delle opzioni di evocazione precedenti ed appare un numero maggiore di creature: il doppio utilizzando uno slot incantesimo di 6° livello e il triplo utilizzando uno slot incantesimo di 8° livello." },
  "Insetto Gigante": { livello:4, scuola:"Trasmutazione", classi:["Druido"], tempo:"1 Azione", gittata:"9m", conc:true, desc:"fino a 10 minuti L'incantatore evoca un millepiedi gigante, un ragno gigante o una vespa gigante (a sua scelta al momento del lancio). L'insetto si manifesta in uno spazio libero entro gittata che l'incantatore è in grado di vedere e utilizza la scheda delle statistiche dell'insetto gigante. La forma scelta dall'incantatore determina alcuni dettagli della sua scheda delle statistiche. La creatura scompare quando scende a 0 punti ferita o quando l'incantesimo termina. ed è un alleato per il personaggio e i suoi alleati. In combattimento, la creatura ha lo stesso punteggio di iniziativa dell'incantatore, ma inizia il turno immediatamente dopo il suo, obbedendo ai suoi comandi verbali (nessuna azione richiesta da parte dell'incantatore). Se l'incantatore non pronuncia comandi verbali, la creatura compie l'azione di Schivata e usa il suo movimento per sottrarsi al pericolo. Utilizzo di uno slot incantesimo di livello superiore. Usa il livello dello slot incantesimo relativo al livello dell'incantesimo nella scheda delle statistiche. Insetto gigante Bestia Grande, senza allineamento CA 11 + il livello dell'incantesimo PF 30 + 10 per ogni livello di incantesimo sopra il 4º Velocità 12 m, scalata 12 m, volo 12 m (solo vespa) 158 System Reference Document 5.2.1 MOD SALV MOD SALV MOD SALV For 17 +3 +3 Des 13 +1 +1 Cos 15 +2 +2 Int 4 −3 −3 Sag 14 +2 +2 Car 3 −4 −4 Sensi Percezione passiva 12; scurovisione 18 m Lingue comprende le lingue parlate dal personaggio GS nessuno (PE 0; BC pari al bonus di competenza del personaggio) Tratti Movimenti del ragno. L'insetto può scalare le superfici difficili, compresi i soffitti, senza effettuare una prova di caratteristica. Azioni Multiattacco. L'insetto effettua un numero di attacchi pari alla metà del livello di quest'incantesimo (arrotondando per difetto). Colpo velenoso. Tiro per colpire in mischia: Il bonus equivale al modificatore di attacco dell'incantesimo del personaggio, portata di 3 metri. Colpito: 1d6 + 3 più il livello dell'incantesimo danni perforanti e 1d4 danni da veleno. Dardo di ragnatela (solo ragno). Tiro per colpire a distanza: il bonus equivale al modificatore di attacco dell'incantesimo del personaggio, gittata di 18 metri. Colpito: 1d10 + 3 più il livello dell'incantesimo danni contundenti. Inoltre, la velocità del bersaglio è ridotta a 0 fino all'inizio del turno successivo dell'insetto. Azioni bonus Rigurgito velenoso (solo millepiedi). Tiro salvezza su Costituzione: CD del tiro salvezza sull'incantesimo, una creatura che l'insetto può vedere entro 3 metri. Fallimento: il bersaglio è avvelenato fino all'inizio del turno successivo dell'insetto.\n\n**Ai Livelli Superiori.** Usa il livello dello slot incantesimo relativo al livello dell'incantesimo nella scheda delle statistiche. Insetto gigante Bestia Grande, senza allineamento CA 11 + il livello dell'incantesimo PF 30 + 10 per ogni livello di incantesimo sopra il 4º Velocità 12 m, scalata 12 m, volo 12 m (solo vespa) 158 System Reference Document 5.2.1 MOD SALV MOD SALV MOD SALV For 17 +3 +3 Des 13 +1 +1 Cos 15 +2 +2 Int 4 −3 −3 Sag 14 +2 +2 Car 3 −4 −4 Sensi Percezione passiva 12; scurovisione 18 m Lingue comprende le lingue parlate dal personaggio GS nessuno (PE 0; BC pari al bonus di competenza del personaggio) Tratti Movimenti del ragno. L'insetto può scalare le superfici difficili, compresi i soffitti, senza effettuare una prova di caratteristica. Azioni Multiattacco. L'insetto effettua un numero di attacchi pari alla metà del livello di quest'incantesimo (arrotondando per difetto). Colpo velenoso. Tiro per colpire in mischia: Il bonus equivale al modificatore di attacco dell'incantesimo del personaggio, portata di 3 metri. Colpito: 1d6 + 3 più il livello dell'incantesimo danni perforanti e 1d4 danni da veleno. Dardo di ragnatela (solo ragno). Tiro per colpire a distanza: il bonus equivale al modificatore di attacco dell'incantesimo del personaggio, gittata di 18 metri. Colpito: 1d10 + 3 più il livello dell'incantesimo danni contundenti. Inoltre, la velocità del bersaglio è ridotta a 0 fino all'inizio del turno successivo dell'insetto. Azioni bonus Rigurgito velenoso (solo millepiedi). Tiro salvezza su Costituzione: CD del tiro salvezza sull'incantesimo, una creatura che l'insetto può vedere entro 3 metri. Fallimento: il bersaglio è avvelenato fino all'inizio del turno successivo dell'insetto." },
  "Contagio": { livello:5, scuola:"Necromanzia", classi:["Chierico","Druido"], tempo:"1 Azione", gittata:"Tocco", desc:"Il tocco dell'incantatore trasmette una malattia. L'incantatore effettua un attacco in mischia con questo incantesimo contro una creatura entro la sua portata. Se colpisce, contamina la creatura con una malattia a sua scelta tra quelle descritte di seguito.\n\nAlla fine di ogni suo turno, il bersaglio deve effettuare un tiro salvezza su Costituzione. Dopo avere fallito tre di questi tiri salvezza, gli effetti della malattia permangono per la durata dell'incantesimo e la creatura smette di effettuare questi tiri salvezza. Dopo avere superato tre di questi tiri salvezza, la creatura si riprende dalla malattia e l'incantesimo termina. Dal momento che questo incantesimo induce una malattia naturale nel suo bersaglio, ogni effetto che rimuove una malattia o migliora gli effetti di una malattia è applicabile al bersaglio.\n\n**Carne Putrefatta.** La carne della creatura si decompone. La creatura subisce svantaggio alle prove di Carisma e vulnerabilità a tutti i danni.\n\n**Devastazione Vischiosa.** La creatura inizia a perdere sangue inesorabilmente e subisce svantaggio alle prove di Costituzione e ai tiri salvezza su Costituzione. Inoltre, ogni volta che la creatura subisce danni, è stordita fino alla fine del suo turno successivo.\n\n**Febbre Lurida.** Il corpo della creatura brucia di febbre. La creatura subisce svantaggio alle prove di Forza, ai tiri salvezza su Forza e ai tiri per colpire che utilizzano la Forza.\n\n**Fuoco Mentale**. La mente della creatura è febbricitante. La creatura subisce svantaggio alle prove di Intelligenza e ai tiri salvezza su Intelligenza, e si comporta come se fosse sotto gli effetti dell'incantesimo confusione durante il combattimento.\n\n**lnfermità Accecante.** La mente della creatura è scossa dal dolore e i suoi occhi diventano lattiginosi. La creatura subisce svantaggio alle prove di Saggezza, ai tiri salvezza su Saggezza ed è accecata.\n\n**Tremarella.** La creatura è colta da violenti brividi, subisce svantaggio alle prove di Destrezza, ai tiri salvezza su Destrezza e ai tiri per colpire che utilizzano la Destrezza." },
  "Guscio Antivita": { livello:5, scuola:"Abiurazione", classi:["Druido"], tempo:"1 Azione", gittata:"Sé stesso (3m)", conc:true, desc:"Una scintillante barriera si estende verso l'esterno dalla posizione dell'incantatore in un raggio di 3 metri e si sposta insieme ad esso, rimandendo centrata sulla sua posizione e respingendo le creature diverse da non-morti e costrutti. La barriera permane per la durata.\n\nLa barriera impedisce ad una creatura influenzata di passare o estendersi attraverso di essa. Una creatura influenzata può lanciare incantesimi o effettuare attacchi con armi a distanza o con portata attraverso la barriera.\n\nSe l'incantatore si sposta in maniera tale che una creatura influenzata sia costretta a passare attraverso la barriera, l'incantesimo ha termine." },
  "Reincarnazione": { livello:5, scuola:"Trasmutazione", classi:["Druido"], tempo:"1 Ora", gittata:"Tocco", desc:"L'incantatore tocca un umanoide morto o una parte di un umanoide morto. Purché la creatura non sia morta da più di 10 giorni, l'incantesimo forma un nuovo corpo adulto per quell'umanoide e poi richiama la sua anima all'interno di quel corpo. Se l'anima del bersaglio non è consenziente o libera di tornare, l'incantesimo fallisce.\n\nL'incantesimo produce un nuovo corpo in cui la creatura possa vivere, cosa che probabilmente costringe la creatura a cambiare razza. Il DM tira un d100 e consulta la tabella seguente per determinare quale forma assume la creatura quando torna in vita; in alternativa, il DM può scegliere la forma.\n\nd100\nRazza\n\n01-04\nDragonide\n\n05-13\nNano delle colline\n\n14-21\nNano delle montagne\n\n22-25\nElfo oscuro\n\n26-34\nElfo alto\n\n35-42\nElfo dei boschi\n\n43-46\nGnomo delle foreste\n\n47-52\nGnomo delle rocce\n\n53-56\nMezzelfo\n\n57-60\nMezzorco\n\n61-68\nHalfling piedelesto\n\n69-76\nHalfling tozzo\n\n77-96\nUmano\n\n97-00\nTiefling\n\nLa creatura reincarnata ricorda la sua vita e le sue esperienze passate. Conserva le capacità che possedeva nella sua forma originale, ma sostituisce la razza originale con quella nuova e cambia i tratti razziali di conseguenza." },
  "Trasmutare Roccia": { livello:5, scuola:"Trasmutazione", classi:["Artefice","Druido","Mago"], tempo:"1 Azione", gittata:"36m", area:"Cubo", desc:"Scegli un'area di pietra o fango che possa essere contenuta in un cubo di 12 metri visibile entro gittata (27 metri). Trasformi la pietra in fango, o il fango in pietra:\n\n- **Da Pietra a Fango:** La pietra non magica diventa fango viscoso profondo. L'area diventa terreno difficile, e ogni 1,5 metri di movimento costano 6 metri. Una creatura presente nell'area quando si trasforma deve superare un tiro salvezza su Forza o sprofondare e rimanere trattenuta.\n- **Da Fango a Pietra:** Il fango diventa pietra solida. Ogni creatura nel fango deve superare un tiro salvezza su Destrezza, altrimenti viene intrappolata nella pietra (CA 17, 25 PF per liberarsi)." },
  "Camminare nel Vento": { livello:6, scuola:"Trasmutazione", classi:["Druido"], tempo:"1 Minuto", gittata:"9m", desc:"L’incantatore e fino a dieci creature consenzienti a sua scelta entro gittata assumono una forma gassosa per la durata dell’incantesimo, apparendo come sbuffi di nuvole. Finché il bersaglio ha queste sembianze, ha una velocità di volo di 90 metri e può fluttuare; è immune alla condizione {prono}; ed è resistente ai danni contundenti, perforanti e taglienti. Le uniche azioni che può effettuare in questa forma sono l’azione {Scatto} o un’azione di Magia per iniziare a riassumere la propria forma normale. La trasformazione richiede 1 minuto, durante il quale il bersaglio ha la condizione {stordito}. Fino al termine dell’incantesimo, il bersaglio può tornare alla forma di nuvola, cosa che richiede nuovamente un’azione di Magia seguita da 1 minuto di trasformazione.\n\nSe una creatura è in forma gassosa e sta volando quando l’effetto termina, scende di 18 metri per round per 1 minuto finché non atterra, senza subire danni. Se non riesce ad atterrare entro 1 minuto, cade per la distanza rimanente." },
  "Festino degli Eroi": { livello:6, scuola:"Evocazione", classi:["Chierico","Druido"], tempo:"10 Minuti", gittata:"9m", desc:"L'incantatore evoca un grande banchetto, completo di sontuose pietanze e bevande. Pasteggiare al banchetto richiede 1 ora, al termine della quale il banchetto scompare; gli effetti benefici del banchetto non si applicano finché quell'ora non è trascorsa. Fino a un massimo di altre dodici creature possono partecipare al banchetto.\n\nUna creatura che partecipa al banchetto ottiene vari benefici: viene curata da tutte le malattie e dai veleni, diventa immune ai veleni e alla condizione di spaventato, dispone di vantaggio a tutti i tiri salvezza su Saggezza, il suo massimo dei punti ferita aumenta di 2d10 e ottiene quello stesso numero di punti ferita. Questi benefici durano per 24 ore." },
  "Muovere la Terra": { livello:6, scuola:"Trasmutazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"36m", conc:true, desc:"L'incantatore sceglie un'area di terreno grande al massimo 12 metri per lato e situata entro gittata.\n\nPuò modellare l'argilla, il terriccio o la sabbia entro l'area nella maniera che preferisce per la durata dell'incantesimo.\n\nL'incantatore può aumentare o ridurre l'elevazione del terreno, creare o riempire una fossa, erigere o spianare una parete, innalzare una colonna.\n\nL'estensione di tali cambiamenti non può superare la metà della dimensione più grande dell'area.\n\nQuindi, se influenza un quadrato con lato di 12 metri, può creare una colonna alta fino a 6 metri, aumentare o ridurre l'elevazione del terreno di un massimo di 6 metri, scavare una fossa della profondità massima di 6 metri e così via.\n\nServono 10 minuti prima che queste alterazioni siano completate.\n\nAlla fine di ogni 10 minuti trascorsi a concentrarsi sull'incantesimo, l'incantatore può scegliere una nuova area di terreno da influenzare.\n\nDal momento che la trasformazione del terreno si completa gradualmente, le creature nell'area solitamente non restano intrappolate o ferite dal movimento del terreno.\n\nQuesto incantesimo non può manipolare la pietra naturale o le costruzioni in pietra.\n\nLe rocce e le strutture si sposteranno per adattarsi al nuovo terreno.\n\nSe l'incantatore modella il terreno in un modo che renderebbe la struttura instabile, quella struttura potrebbe crollare.\n\nAnalogamente questo incantesimo non influenza la crescita vegetale.\n\nLa terra spostata sposta con sé ogni vegetale presente." },
  "Muro di Spine": { livello:6, scuola:"Evocazione", classi:["Druido"], tempo:"1 Azione", gittata:"36m", danno:"7d8", tipoDanno:"Perforante", conc:true, desc:"L'incantatore crea un fitto muro di rovi, resistente, flessibile ed erto di spine affilate.\n\nIl muro appare su una superficie solida entro gittata e permane per la durata dell'incantesimo.\n\nIl muro può essere lungo fino a 18 metri, alto 3 metri e spesso 1,5 metri, oppure può essere un muro circolare del diametro di 6 metri, alto fino a 6 metri e spesso 1,5 metri.\n\nIl muro blocca la linea di vista.\n\nQuando il muro appare, ogni creatura entro la sua area deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 7d8 danni perforanti, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nUna creatura può muoversi attraverso il muro, anche se lentamente e dolorosamente.\n\nPer ogni 30 cm di muro che attraversa, la creatura deve spendere 120 cm di movimento.\n\nInoltre, la prima volta che una creatura entra nel muro in un turno o vi termina il proprio turno, deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 7d8 danni taglienti, mentre se lo supera, subisce solo al metà di quei danni.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, entrambi i tipi di danno aumentano di 1d8 per ogni slot di livello superiore al 6°" },
  "Scopri la Via": { livello:6, scuola:"Divinazione", classi:["Bardo","Chierico","Druido"], tempo:"1 Minuto", gittata:"Sé stesso", conc:true, desc:"Questo incantesimo consente all'incantatore di scoprire il percorso fisico più breve e diretto verso un determinato luogo fisso che gli sia familiare e che si trovi su suo stesso piano di esistenza. Se l'incantatore nomina una destinazione su un altro piano di esistenza, una destinazione che si muove (come ad esempio una fortezza mobile) o una destinazione troppo generica (come per esempio la tana di un drago verde), l'incantesimo fallisce.\n\nPer la durata dell'incantesimo, fintato che l'incantatore si trova sullo stesso piano di esistenza della destinazione, egli sa quanto al destinazione è lontana e in che direzione si trova. Mentre viaggia verso quella destinazione, ogni volta che gli si presentano più sentieri tra cui scegliere lungo il cammino, l'incantatore determina automaticamente il sentiero più breve e più diretto (ma non necessariamente il più sicuro) che lo porterà a destinazione." },
  "Inversione della Gravità": { livello:7, scuola:"Trasmutazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"30m", area:"Cilindro", conc:true, desc:"Questo incantesimo inverte la gravità all'interno di un cilindro del raggio di 15 metri e alto 30 metri, centrato su un punto situato entro gittata.\n\nTutte le creature e gli oggetti che non sono in qualche modo ancorati al terreno all'interno dell'area cadono verso l'alto e arrivano in cima all'area quando l'incantesimo viene lanciato.\n\nUna creatura può effettuare un tiro salvezza su Destrezza per afferrare un oggetto ancorato entro portata, evitando in questo modo la caduta.\n\nSe un oggetto solido di qualche tipo (come per esempio un soffitto) viene urtato durante questa caduta, gli oggetti e le creature subiscono un impatto identico a quello che subirebbero durante una normale caduta verso il basso.\n\nSe un oggetto o una creatura arriva in cima all'area senza colpire niente, rimane lassù a oscillare leggermente per la durata dell'incantesimo.\n\nAlla fine della durata, gli oggetti e le creature influenzate ricadono a terra." },
  "Miraggio Arcano": { livello:7, scuola:"Illusione", classi:["Bardo","Druido","Mago"], tempo:"10 Minuti", gittata:"Vista", desc:"Fai sì che un pezzo di terreno a gittata, in un&rsquo;area quadrata fino a 1,5 chilometri, appaia, risuoni e odori come qualche altro tipo di terreno. La conformazione generale del terreno rimane tuttavia la stessa. Campi aperti o una strada possono essere trasformati in un acquitrino, colline, un crepaccio o qualche altro tipo di terreno difficile o invalicabile.\n\nUn laghetto può essere trasformato in una radura erbosa, un precipizio in una lieve pendenza, un burrone cosparso di rocce in una strada ampia e liscia.Allo stesso modo, puoi modificare l&rsquo;aspetto delle strutture, o aggiungerne dove non ve ne sono. L&rsquo;incantesimo non camuffa, occulta né aggiunge creature.\n\nL&rsquo;illusione comprende elementi uditivi, visivi, tattili e olfattivi, così da poter trasformare un terreno sgombro in terreno difficile (o viceversa) o impedire altrimenti il movimento nell'area. Qualsiasi pezzo di terreno illusorio (come una pietra o un bastone), che venga rimosso dall'area dell&rsquo;incantesimo, svanisce immediatamente.\n\nLe creature con visione del vero possono vedere oltre l&rsquo;illusione e distinguere la vera forma del terreno; tuttavia, gli altri elementi dell&rsquo;illusione rimangono, così, sebbene la creatura sia consapevole della presenza dell&rsquo;illusione, vi può comunque interagire fisicamente." },
  "Rigenerazione": { livello:7, scuola:"Trasmutazione", classi:["Bardo","Chierico","Druido"], tempo:"1 Minuto", gittata:"Tocco", danno:"4d8+15", tipoDanno:"Cura", desc:"L'incantatore tocca una creatura e amplifica le sue capacità curative naturali. Il bersaglio recupera 4d8+15 punti ferita. Per la durata dell'incantesimo, il bersaglio recupera 1 punto ferita all'inizio di ogni suo turno (10 punti ferita al minuto).\n\nSe al bersaglio sono state recise parti del corpo (dita, gambe, coda e così via) quelle parti vengono rigenerate dopo 2 minuti. Se l'incantatore è in possesso della parte recisa e l'appoggia al moncherino, l'incantesimo riunisce istantaneamente l'arto reciso al moncherino." },
  "Spostamento Planare": { livello:7, scuola:"Abiurazione", classi:["Chierico","Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Tocco", desc:"L'incantatore e un massimo di otto creature consenzienti che si tengono per mano formando un cerchio vengono trasportati su un piano di esistenza diverso. L'incantatore può specificare la destinazione o averne una vaga descrizione, per poi apparire nel luogo esatto o nelle sue vicinanze, a discrezione del DM.\n\nIn alternativa, se l'incantatore conosce la sequenza dei simboli di un cerchio di teletrasporto su un altro piano, l'incantesimo lo conduce nel punto esatto. Nel caso il cerchio sia troppo piccolo per contenere tutte le creature, esse appaiono nello spazio libero più vicino\n\nL'incantesimo può essere utilizzato per bandire una creatura non consenziente su un altro piano di esistenza. In questo caso è necessario effettuare in tiro per colpire con un'arma corpo a corpo sulla creatura. L'incantatore sceglie una creatura entro la sua portata ed effettua un attacco in mischia con questo incantesimo contro di essa. Se colpisce, la creatura deve effettuare un tiro salvezza su Carisma. Se lo fallisce, viene trasportata in un luogo casuale sul piano di esistenza specificato dall'incantatore. Una creatura trasportata in questo modo dovrà trovare da sola il modo di tornare sul piano di esistenza attuale dell'incantatore." },
  "Tempesta di Fuoco": { livello:7, scuola:"Invocazione", classi:["Chierico","Druido","Stregone"], tempo:"1 Azione", gittata:"45m", danno:"7d10", tipoDanno:"Fuoco", desc:"Appaino fino a dieci cubi di lato 3 metri, che puoi collocare a tuo piacimento. Ogni cubo deve toccare almeno la faccia di un altro cubo. Ogni creatura nell'area dei cubi effettua un tiro salvezza sulla Destrezza. Nel caso fallisca, subisce 7d10 danni da fuoco , o la metà nel caso riesca.\n\nIl fuoco danneggia gli oggetti nell'area e incendia quelli infiammabili che non sono indossati o trasportati. E' possibile isolare le piante dall'effetto dell'incantesimo." },
  "Turbine": { livello:7, scuola:"Invocazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"90m", danno:"10d6", tipoDanno:"Contundente", conc:true, desc:"Un vortice d'aria rombante con raggio di 3 metri e alto fino a 9 metri compare in un punto visibile a terra entro gittata (90 metri). Dura per la durata (concentrazione, fino a 1 minuto).\n\nOgni creatura che entra nel turbine per la prima volta in un turno o vi inizia il turno deve superare un tiro salvezza su Destrezza o subire 10d6 danni contundenti ed essere risucchiata e trattenuta nel turbine. Con un'azione puoi muovere il turbine fino a 9 metri in qualsiasi direzione." },
  "Forme Animali": { livello:8, scuola:"Trasmutazione", classi:["Druido"], tempo:"1 Azione", gittata:"9m", conc:true, desc:"La magia dell'incantatore trasforma gli altri in bestie. L'incantatore sceglie un qualsiasi numero di creature consenzienti che possa vedere ed entro gittata. Ogni bersaglio viene trasformato nella forma di una bestia di taglia Grande o più piccola con un grado sfida di 4 o inferiore. Nei turni successivi, l'incantatore può usare la propria azione per trasformare le creature influenzate in nuove forme.\n\nLa trasformazione permane per ogni bersaglio attraverso la durata dell'incantesimo oppure finchè un bersaglio viene ridotto a 0 punti ferita o muore.\n\nL'incantatore può scegliere una forma differente per ciascun bersaglio. Le statistiche di gioco di un bersaglio vengono sostituite dalle statistiche della creatura scelta, tuttavia il bersaglio mantiene il proprio allineamento e i propri punteggi di Intelligenza, Saggezza e Carisma. Il bersaglio ottiene i punti ferita della sua nuova forma e quando torna alla propria forma naturale ritorna al numero di punti ferita che aveva prima della trasformazione. Se il bersaglio si ritrasforma per essere stato ridotto a 0 punti ferita, ogni danno in eccesso viene trasferito alla forma naturale. Fintanto che il danno in eccesso non riduca la forma naturale del bersaglio a 0 punti ferita, esso non viene reso incosciente. Il bersaglio è limitato nelle azioni che può intraprendere dalla natura della sua nuova forma e non può parlare o lanciare incantesimi.\n\nL'equipaggiamento del bersaglio si fonde alla nuova forma. Il bersaglio non può attivare, impugnare o altrimenti beneficiare di alcun oggetto del proprio equipaggiamento." },
  "Antipatia/Simpatia": { livello:8, scuola:"Ammaliamento", classi:["Bardo","Druido","Mago"], tempo:"1 Ora", gittata:"18m", desc:"Questo incantesimo attira o repelle un tipo di creatura. L'incantatore sceglie un bersaglio entro gittata, che può trattarsi di un oggetto o di una creatura di taglia Enorme o inferiore, o di un'area della grandezza massima di un cubo con spigolo di 60 metri. Dopodiché specifica un tipo di creatura intelligente, come i draghi rossi, i goblin o i vampiri. L'incantatore infonde nel bersaglio un'aura che attira o respinge le creature specificate per la durata dell'incantesimo, scegliendo antipatia o simpatia come effetto dell'aura.\n\n**Antipatia.** L'ammaliamento suscita nelle creature del tipo designato dall'incantatore il desiderio impellente di abbandonare l'area ed evitare il bersaglio. Quando una tale creatura vede il bersaglio o giunge entro 18 metri da esso, deve superare un tiro salvezza su Saggezza, altrimenti diventa spaventata. La creatura rimane spaventata fintanto che è in grado di vedere il bersaglio o rimane entro 18 metri da esso. Finché è spaventata dal bersaglio, deve usare il suo movimento per muoversi verso il punto sicuro più vicino da cui non vedrà più il bersaglio. Se la creatura si allontana a più di 18 metri dal bersaglio e non è più in grado di vederlo, cessa di essere spaventata, ma lo diventa di nuovo se torna a vedere il bersaglio o a trovarsi entro 18 metri da esso.\n\n**Simpatia.** L'ammaliamento fa si che le creature specificate provino il desiderio impellente di avvicinarsi al bersaglio finché si trovano entro 18 metri da esso o sono in grado di vederlo. Quando una tale creatura vede il bersaglio o giunge entro 18 metri da esso, deve superare un tiro salvezza su Saggezza o usare il suo movimento in ogni suo turno per entrare nell'area o muoversi entro la portata del bersaglio. Una volta fatto questo, la creatura non può più muoversi volontariamente per allontanarsi dal bersaglio. Se il bersaglio infligge danni a una creatura inftuenzata o le nuoce in altri modi, essa può effettuare un tirosalvezza per terminare l'effetto come descritto sotto.\n\n**Terminare l'Effetto. **Se una creatura influenzata termina il suo turno oltre 18 metri dal bersaglio o non è in grado di vederlo, effettua un tiro salvezza su Saggezza. Se to supera, non è più influenzata dal bersaglio e capisce che la sensazione di ripugnanza o di attrazione era magica. Inoltre, una creatura influenzata dall'incantesimo ha diritto a un altro tiro salvezza su Saggezza ogni 24 ore finché l'incantesimo permane. Una creatura che supera un tiro salvezza contro questo effetto è immune a esso per 1 minuto, dopodiché può esserne influenzata di nuovo." },
  "Controllare il Clima": { livello:8, scuola:"Trasmutazione", classi:["Chierico","Druido","Mago"], tempo:"10 Minuti", gittata:"Sé stesso (8 km)", conc:true, desc:"L'incantatore assume il controllo del tempo atmosferico entro un raggio di 7,5 km per la durata dell'incantesimo. Deve trovarsi all'esterno per lanciare questo incantesimo. Se si muove in un luogo in cui non dispone di una linea diretta fino al cielo, l'incantesimo termina prematuramente. Quando l'incantatore lancia l'incantesimo, cambia le condizioni atmosferiche attuali determinate dal DM in base al clima e alla stagione. L'incantatore può cambiare le precipitazioni, le temperature e il vento. Occorrono 1d4 x 10 minuti prima che le nuove condizioni abbiano effetto. Quando questo accade, l'incantatore può cambiare di nuovo le condizioni. Quando l'incantesimo termina, il tempo atmosferico torna gradualmente alla normalità. Quando l'incantatore cambia le condizioni atmosferiche, trova la condizione attuale nelle tabelle sottostanti e le cambia di un grado verso l'alto o verso il basso. Quando cambia il vento, può cambiarne anche la direzione.\n\n**Precipitazioni**\n\n- Sereno\n- Poco Nuvoloso\n- Nuvoloso o Nebbia\n- Pioggia, Grandine o Neve\n- Pioggia torrenziale, grandine fitta o tormenta**Temperature**\n\n- Caldo insopportabile\n- Caldo\n- Temperato\n- Fresco\n- Freddo\n- Freddo artico**Vento**\n\n- Calmo\n- Vento moderato\n- Vento forte\n- Burrasca\n- Tempesta" },
  "Esplosione Solare": { livello:8, scuola:"Invocazione", classi:["Chierico","Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"45m", area:"Sfera", danno:"12d6", tipoDanno:"Radiante", desc:"Un luminoso bagliore solare si espande in un raggio di 18 metri centrato su di un punto entro portata a scelta dell'incantatore. Ogni creatura situata in quella luce deve effettuare un tiro salvezza Costituzione. Se lo fallisce, una creatura subisce 12d6 danni radianti e viene accecata per 1 minuto. Se lo supera, subisce la metà del danno e non viene accecata. Non-morti e gelatine hanno svantaggio a questo tiro salvezza.\n\nUna creatura accecata da questo incantesimo effettua un altro tiro salvezza Costituzione alla fine di ognuno dei propri turni. Se lo supera, non è più accecata.\n\nQuesto incantesimo disperde qualsiasi oscurità creata da un incantesimo nella propria area d'effetto." },
  "Terremoto": { livello:8, scuola:"Trasmutazione", classi:["Chierico","Druido","Stregone"], tempo:"1 Azione", gittata:"150m", area:"Cerchio", conc:true, desc:"L'incantatore crea una scossa sismica in un punto del terreno situato entro gittata e che egli sia in grado di vedere. Per la durata dell'incantesimo, un intenso tremito scuote il terreno entro un raggio di 30 metri centrato su quel punto, coinvolgendo le creature e le strutture a contatto con il terreno in quell'area.\n\nIl terreno nell'area diventa terreno difficile. Ogni creatura sul terreno che si stia concentrando deve superare un tiro salvezza su Costituzione, se lo fallisce la sua concentrazione è interrotta.\n\nQuando l'incantatore lancia questo incantesimo e alla fine di ogni turno da lui trascorso a concentrarsi su di esso, ogni creatura sul terreno nell'area deve effettuare un tiro salvezza su Destrezza. In caso di fallimento, cade a terra prona.\n\nQuesto incantesimo può avere effetti aggiuntivi a seconda del terreno nell'area, come determinato dal DM.\n\n**Crepe:** In tutta l'area dell'incantesimo si aprono delle crepe a partire dall'inizio del turno successivo dell'incantatore a quello in cui l'incantesimo è stato lanciato. Un totale di 1d6 crepe si aprono nell'area dell'incantesimo in punti scelti dal DM. Ciascuna è profonda 1d10 x 3 metri, larga 3 metri e si estende da un bordo dell'area dell'incantesimo al bordo opposto. Una creatura che si trovi in un punto in cui si apre una fessura deve passare un tiro salvezza su Destrezza o vi cadrà dentro. Se la creatura supera il tiro salvezza, riesce a spostarsi assieme al bordo della crepa quando questa viene a crearsi. Una fessura che si apre sotto una struttura la fa automaticamente crollare (vedi sotto).\n\n**Strutture:** La scossa sismica infligge 50 danni contundenti a qualsiasi struttura a contatto con il terreno nell'area in cui è stato lanciato l'incantesimo e all'inizio di ogni turno dell'incantatore finché l'incantesimo non termina. Se una struttura scende a 0 punti ferita, essa crolla e potrebbe infliggere danni alle creature vicine. Una creatura situata entro una distanza pari alla metà dell'altezza della struttura deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 5d6 danni contundenti, cade a terra prona ed è seppellita dai detriti. Per liberarsi deve usare un'azione per effettuare una prova di Forza (Atletica) con CD 20. Il DM può aumentare o ridurre la CD, in base alla natura dei detriti. In caso di tiro salvezza superato, la creatura subisce soltanto la metà di quei danni, non cade a terra prona e non viene seppellita." },
  "Tsunami": { livello:8, scuola:"Evocazione", classi:["Druido"], tempo:"1 Minuto", gittata:"Vista", danno:"6d10", tipoDanno:"Contundente", conc:true, desc:"Un muro d’acqua si materializza in un punto a scelta dell'incantatore entro gittata. Il muro può avere dimensioni massime di 90 metri di lunghezza, 90 metri di altezza e 15 metri di spessore, e permane per tutta la durata dell'incantesimo.\n\nQuando appare, ogni creatura nell'area effettua un tiro salvezza su Forza, subendo 6d10 danni contundenti in caso di fallimento o la metà in caso di successo.\n\nAll'inizio di ogni turno dell'incantatore dopo l'apparizione del muro, esso si sposta di 15 metri allontanandosi dall'incantatore, trascinando con sé eventuali creature al suo interno. Qualsiasi creatura di taglia Enorme o inferiore che si trovi nel muro o il cui spazio venga attraversato dal muro quando si muove deve superare un tiro salvezza su Forza o subire 5d10 danni contundenti. Una creatura può subire questi danni solo una volta per round. Alla fine del turno, l'altezza del muro si riduce di 15 metri e i danni inflitti nei round successivi diminuiscono di 1d10. Quando il muro raggiunge 0 metri di altezza, l'incantesimo termina.\n\nUna creatura immersa nel muro può muoversi nuotando, ma a causa della forza dell’onda deve superare una prova di [[/check ability=str skill=ath dc=@attributes.spell.dc]] contro la CD dell'incantesimo per riuscire a muoversi. Se fallisce, non può muoversi. Una creatura che esce dal muro cade a terra.\n\n**Nota per Foundry**\n\nIl valore di utilizzi limitati dell'incantesimo tiene traccia dei round rimanenti (inizialmente 6), che vengono ripristinati tramite l’attività **Create Tsunami**.\n\nL’attività **Start of Turn Effects** consuma un utilizzo per rappresentare il passare di un round e usa il conteggio aggiornato per i tiri danno." },
  "Mutare Forma": { livello:9, scuola:"Trasmutazione", classi:["Druido","Mago"], tempo:"1 Azione", gittata:"Sé stesso", conc:true, desc:"L'incantatore assume la forma di una creatura diversa per la durata dell'incantesimo.\n\nLa nuova forma può essere quella di qualsiasi creatura con un grado di sfida pari o inferiore al livello dell'incantatore.\n\nLa creatura non può essere un costrutto o un non morto e deve essere un tipo di creatura che l'incantatore abbia visto almeno una volta.\n\nL'incantatore si trasforma in un normale esemplare di quella creatura, privo di livelli di classe e del tratto \"Incantesimi\".\n\nLe statistiche di gioco vengono sostituite dalle statistiche della creatura scelta, ma l'incantatore conserva il suo allineamento e i suoi punteggi di Intelligenza, Seggezza e Carisma.\n\nConserva inoltre tutte le sue competenze nelle abilità e nei tiri salvezza, oltre a ottenere quelle della creatura.\n\nSe la creatura possiede una competenza che anche l'incantatore possiede e il bonus elencato nelle sue statistiche è superiore a quello dell'incantatore, quest'ultimo usa il bonus della creatura al posto del proprio.\n\nL'incantatore non può usare nessuna azione leggendaria o di tana nella nuova forma.\n\nL'incantatore assume i punti ferita e i Dadi Vita della nuova forma, e quando riassume la sua forma normale, ritorna al numero di punti ferita che possedeva prima di essere trasformato.\n\nSe riassume la forma normale per essere sceso a 0 punti ferita, ogni eventuale danno in eccesso si trasferisce alla sua forma normale.\n\nFintanto che i danni in eccesso non portano la forma normale dell'incantatore a 0 punti ferita, l'incantatore non cade privo di sensi.\n\nL'incantatore conserva il beneficio degli eventuali privilegi fornitigli dalla sua classe, razza o altre fonti, e può usarli, purché la sua nuova forma glielo consenta fisicamente.\n\nNon può usare alcun senso speciale che possieda (come per esempio la scurovisione), a meno che la sua nuova forma non lo possieda a sua volta.\n\nPuò parlare solo se la creatura è normalmente in grado di parlare.\n\nQuando l'incantatore si trasforma, sceglie se lasciare cadere a terra il suo equipaggiamento, se tale equipaggiamento si fonde nella sua nuova forma o se indossarlo.\n\nL'equipaggiamento indossato funziona normalmente, ma spetta al DM decidere se è pratico o meno che la nuova forma indossi ogni determinato oggetto di equipaggiamento, in base alla forma e alla taglia della creatura.\n\nL'equipaggiamento dell'incantatore non cambia taglia o forma per adattarsi alla nuova forma, e ogni oggetto di equipaggiamento che la nuova forma non può indossare deve cadere a terra o fondersi nella nuova forma dell'incantatore.\n\nL'equipaggiamento fuso alla nuova forma non ha alcun effetto in quello stato.\n\nPer la durata dell'incantesimo, l'incantatore può usare la sua azione per assumere una forma diversa seguendo le stesse regole e restrizioni relative alla forma originale, con una eccezione: se la nuova forma possiede più punti ferita rispetto ai punti ferita attuali dell'incantatore, i punti ferita di quest'ultimo rimangono al suo valore attuale." },
  "Previsione": { livello:9, scuola:"Divinazione", classi:["Bardo","Druido","Mago","Stregone","Warlock"], tempo:"1 Minuto", gittata:"Tocco", desc:"L'incantatore tocca una creatura consenziente e le conferisce una capacità limitata di prevedere il futuro prossimo. Per la durata dell'incantesimo, il bersaglio non può essere sorpreso e dispone di vantaggio ai tiri per colpire, alle prove di caratteristica e ai tiri salvezza. Inoltre, le altre creature subiscono svantaggio ai tiri per colpire contro il bersaglio per la durata dell'incantesimo.\n\nQuesto incantesimo termina immediatamente se l'incantatore lo lancia di nuovo prima che la sua durata termini." },
  "Tempesta di Vendetta": { livello:9, scuola:"Invocazione", classi:["Druido"], tempo:"1 Azione", gittata:"Vista", area:"Sfera", conc:true, desc:"L'incantatore genera una minacciosa nube tempestosa, che si espande fino a un raggio di 110 metri centrato su un punto che egli sia in grado di vedere. L'area è scossa da tuoni, fulmini e venti forti. Ogni creatura situata sotto la nube (a non più di 1.500 metri sotto di essa) nel momento in cui compare deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 2d6 danni da tuono e diventa assordata per 5 minuti.\n\nPer ogni round in cui l'incantatore mantiene la concentrazione su questo incantesimo, la tempesta produce ulteriori effetti nel suo turno.\n\n**Round 2.** Dalla nube cade una pioggia acida. Ogni creatura e oggetto sotto di essa subisce 1d6 danni da acido.\n\n**Round 3.** L'incantatore invoca sei fulmini che scendono dalla nube e colpiscono sei creature o oggetti a sua scelta situati sotto la nube. Una determinata creatura o oggetto può essere colpita da più di un fulmine. Una creatura colpita deve effettuare un tiro salvezza su Destrezza. Se lo fallisce subisce 10d6 danni da fulmine, mentre se lo supera ne subisce la metà.\n\n**Round 4.** Dalla nube cade una violenta grandinata. Ogni creatura sotto la nube subisce 2d6 danni contundenti.\n\n**Round 5-10.** L'area sotto la nube è attraversata da raffiche di vento e pioggia gelida. L'area diventa terreno difficile e pesantemente oscurato e ogni creatura al suo interno subisce 1d6 danni da freddo. Gli attacchi con le armi a distanza sono impossibili. Il vento e la pioggia contano come gravi distrazioni al fine di mantenere la concentrazione sugli incantesimi. Infine raffiche di vento forte disperdono automaticamente nebbia, foschia e fenomeni simili nell'area, comuni o magici che siano." },
  "Amicizia": { livello:0, scuola:"Ammaliamento", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso", conc:true, desc:"Per la durata (concentrazione, fino a 1 minuto), hai vantaggio a tutte le prove di Carisma dirette a una creatura di tua scelta che non sia ostile nei tuoi confronti. Quando l'incantesimo ha termine, la creatura si rende conto che hai usato la magia per influenzare il suo umore e diventa ostile verso di te. Una creatura incline alla violenza potrebbe attaccarti, mentre un'altra potrebbe cercare vendetta in altro modo (a discrezione del DM)." },
  "Infestazione": { livello:0, scuola:"Evocazione", classi:["Druido","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"9m", danno:"1d6", tipoDanno:"Veleno", desc:"Fai sciamare acari, zecche, pulci e altri parassiti su una creatura visibile entro gittata (9 metri). Il bersaglio deve effettuare un tiro salvezza su Costituzione. Se fallisce, subisce 1d6 danni da veleno e si sposta di 1,5 metri in una direzione casuale (tira 1d4: 1 = nord, 2 = sud, 3 = est, 4 = ovest) se la sua velocità non è 0. Questo movimento non provoca attacchi di opportunità.\n\n**Potenziamento per i Trucchetti.** I danni aumentano di 1d6 al 5° livello (2d6), all'11° livello (3d6) e al 17° livello (4d6)." },
  "Parola di Radiosità": { livello:0, scuola:"Invocazione", classi:["Chierico"], tempo:"1 Azione", gittata:"Sé stesso (1,5m)", danno:"1d6", tipoDanno:"Radiante", desc:"Pronunci una parola sacra e una radiosità accecante erompe da te. Ogni creatura a tua scelta che puoi vedere entro 1,5 metri deve superare un tiro salvezza su Costituzione, altrimenti subisce 1d6 danni radianti.\n\n**Potenziamento per i Trucchetti.** I danni aumentano di 1d6 quando raggiungi il 5° livello (2d6), l'11° livello (3d6) e il 17° livello (4d6)." },
  "Allarme": { livello:1, scuola:"Abiurazione", classi:["Artefice","Mago","Ranger"], tempo:"1 min", gittata:"9m", rituale:true, desc:"ore L'incantatore predispone un allarme che segnala un'intrusione. Sceglie una porta, una finestra o un'area entro gittata che non sia più ampia di un cubo con spigolo di 6 metri. Fino al termine dell'incantesimo, un allarme avverte l'incantatore tutte le volte che una creatura tocca o entra nell'area protetta. Al momento del lancio dell'incantesimo, l'incantatore designa quali creature non faranno scattare l'allarme. Inoltre, sceglie se l'allarme è acustico o mentale. Allarme acustico. L'allarme produce il suono di una campanella per 10 secondi entro 18 metri dall'area protetta. Allarme mentale. Un suono nella mente avverte l'incantatore se questi si trova entro 1,5 chilometri dall'area protetta. Il suono sveglia l'incantatore se sta dormendo." },
  "Disco Fluttuante di Tenser": { livello:1, scuola:"Evocazione", classi:["Mago"], tempo:"1 Azione", gittata:"9m", rituale:true, desc:"Questo incantesimo crea un piano circolare e orizzontale di forza, del diametro di 90 cm e dello spessore di 2,5 cm, che fluttua a 90 cm dal terreno in uno spazio libero a scelta dell'incantatore, situato entro gittata e che egli sia in grado di vedere. Il disco permane per la durata dell'incantesimo e può sostenere fino a 250 kg. Se si aggiunge ulteriore peso, l'incantesimo termina e tutto ciò che si trovava sul disco cade a terra.\n\nIl disco è immobile finché l'incantatore si trova entro 6 metri da esso. Se l'incantatore si allontana dal disco a più di 6 metri, il disco lo segue in modo da rimanere entro 6 metri da lui. Può muoversi sul terreno dissestato, lungo scalinate, pendii e così via, ma non può superare un cambio di elevazione pari o superiore a 3 metri. Per esempio, il disco non potrebbe muoversi oltre una fossa profonda 3 metri e non potrebbe uscire da quella fossa se fosse stato creato sul fondo.\n\nSe l'incantatore si muove a più di 30 metri dal disco (solitamente perché il disco non può aggirare un ostacolo per seguirlo), l'incantesimo termina." },
  "Intimorire": { livello:1, scuola:"Necromanzia", classi:["Mago","Warlock"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"Svegli il terrore viscerale nella mente di una creatura visibile entro gittata (18 metri). Il bersaglio deve effettuare un tiro salvezza su Saggezza. Se fallisce, diventa spaventato da te per la durata dell'incantesimo (concentrazione, fino a 1 minuto). Il bersaglio può ripetere il tiro salvezza alla fine di ogni suo turno, terminando l'effetto su di sé con un successo. Non ha effetto su costrutti o non morti.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot di 2° livello o superiore, puoi bersagliare una creatura aggiuntiva per ogni slot superiore al 1°." },
  "Onda di Caos": { livello:1, scuola:"Invocazione", classi:["Stregone"], tempo:"1 Azione", gittata:"36m", danno:"2d8+1d6", tipoDanno:"Caotico", desc:"Scagli un dardo ondeggiante di energia caotica contro una creatura entro gittata (36 metri). Effettui un attacco con incantesimo a distanza contro il bersaglio: se colpisci, subisce 2d8 + 1d6 danni. Scegli uno dei d8 per determinare il tipo di danno: 1 = acido, 2 = freddo, 3 = fuoco, 4 = forza, 5 = fulmine, 6 = veleno, 7 = psichico, 8 = tuono.\n\nSe ottieni lo stesso numero su entrambi i d8, l'energia caotica balza dal bersaglio a una seconda creatura a tua scelta entro 9 metri da esso. Effettui un nuovo tiro per colpire contro il nuovo bersaglio e tiri nuovamente i danni, con la possibilità di balzare ancora se ottieni di nuovo lo stesso numero sui due d8.\n\n**Ai Livelli Superiori.** Quando lanci questo incantesimo usando uno slot di 2° livello o superiore, il danno aumenta di 1d6 per ogni slot superiore al 1°." },
  "Raggio di Infermità": { livello:1, scuola:"Necromanzia", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"18m", danno:"2d8", tipoDanno:"Veleno", desc:"L'incantatore proietta un raggio di energia verdastra verso una creatura entro gittata, effettuando un attacco a distanza con incantesimo contro il bersaglio. Se il colpo va a segno, il bersaglio subisce 2d8 danni da veleno ed è avvelenato fino al termine del turno successivo dell'incantatore. Utilizzo di uno slot incantesimo di livello superiore. I danni aumentano di 1d8 per ogni slot di livello superiore al 1º.\n\n**Ai Livelli Superiori.** I danni aumentano di 1d8 per ogni slot di livello superiore al 1º." },
  "Unto": { livello:1, scuola:"Evocazione", classi:["Artefice","Mago","Stregone"], tempo:"1 Azione", gittata:"18m", area:"Quadrato 3m", desc:"minuto Una patina di unto non infiammabile ricopre un'area di terreno di 3 metri per lato centrata su un punto entro gittata che diventa terreno difficile per la durata dell'incantesimo. Quando l'unto compare, ogni creatura nell'area deve superare un tiro salvezza su Destrezza, altrimenti cade a terra prona. Anche una creatura che 200 System Reference Document 5.2.1 entra nell'area o vi termina il proprio turno deve superare lo stesso tiro salvezza, altrimenti cade prona." },
  "Cecità/Sordità": { livello:2, scuola:"Necromanzia", classi:["Bardo","Chierico","Mago","Stregone"], tempo:"1 Azione", gittata:"9m", desc:"L'incantatore può accecare o assordare un nemico, scegliendo una creatura entro gittata e che egli sia in grado di vedere. Quella creatura deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, è accecata o assordata (a scelta dell'incantatore) per la durata dell'incantesimo. Alla fine di ogni suo turno può effettuare un nuovo tiro salvezza su Costituzione. Se lo supera, l'incantesimo termina.\n\n**Al Livelli Superiori****.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, può bersagliare una creatura aggiuntiva per ogni slot superiore al 2°." },
  "Fiamma Perenne": { livello:2, scuola:"Invocazione", classi:["Artefice","Chierico","Mago"], tempo:"1 Azione", gittata:"Tocco", desc:"non viene dissolto Una fiamma si sprigiona da un oggetto toccato dall'incantatore. L'effetto proietta luce intensa in un raggio di 6 metri e luce fioca per ulteriori 6 metri. L'effetto è quello di una fiamma comune, ma non genera calore e non utilizza combustibile. La fiamma può essere coperta o nascosta, ma non soffocata o estinta." },
  "Freccia Acida di Melf": { livello:2, scuola:"Invocazione", classi:["Artefice","Mago"], tempo:"1 Azione", gittata:"27m", danno:"4d4", tipoDanno:"Acido", desc:"Una freccia verde scintillante vola fino a un bersaglio entro gittata ed esplode generando uno spruzzo d'acido.\n\nL'incantatore effettua un attacco a distanza con questo incantesimo contro il bersaglio. Se colpisce, il bersaglio subisce immediatamente 4d4 danni da acido e 2d4 danni da acido alla fine del suo turno successivo. Se manca, la freccia spruzza di acido il bersaglio infliggendo la metà dei danni iniziali e nessun danno alla fine del turno successivo.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 3° livello o superiore, i danni (sia quelli iniziali che quelli successivi) aumentano di 1d4 per ogni slot di livello superiore al 2°." },
  "Riposo Inviolato": { livello:2, scuola:"Necromanzia", classi:["Chierico","Druido","Mago"], tempo:"1 Azione", gittata:"Tocco", rituale:true, desc:"giorni L'incantatore tocca un cadavere o altri resti. Per la durata dell'incantesimo, il bersaglio è protetto dalla decomposizione e non può diventare un non morto. Inoltre, l'incantesimo estende il limite di tempo entro cui rianimare il bersaglio dalla morte, in quanto i giorni trascorsi sotto l'influenza di questo incantesimo non contano al fine di determinare il limite di tempo di incantesimi come rianimare morti." },
  "Capanna di Leomund": { livello:3, scuola:"Invocazione", classi:["Bardo","Mago"], tempo:"1 min", gittata:"Sé stesso (sfera 3m)", rituale:true, desc:"Una cupola di forza immobile del raggio di 3 metri si forma intorno e sopra di te, restando stazionaria per la durata. L&rsquo;incantesimo termina se lasci l&rsquo;area.\n\nNove creature di taglia Media o inferiore possono entrare nella cupola insieme a te. L&rsquo;incantesimo fallisce se l&rsquo;area include una creatura più grande o più di dieci creature. Le creature e gli oggetti all&rsquo;interno della cupola, quando lanci questo incantesimo, la possono attraversare liberamente. Tutte le altre creature e oggetti sono proibiti dall&rsquo;attraversarla. Incantesimi e altri effetti magici non possono estendersi oltre la cupola o attraversarla. L&rsquo;atmosfera all&rsquo;interno dello spazio è confortevole e asciutta, quale che sia il clima all&rsquo;esterno.\n\nFino al termine dell&rsquo;incantesimo, puoi comandare che l&rsquo;interno diventi illuminato fioco o buio. La cupola è opaca dall&rsquo;esterno, di qualsiasi colore tu scelga, ma è trasparente dall&rsquo;interno." },
  "Glifo di Interdizione": { livello:3, scuola:"Abiurazione", classi:["Artefice","Bardo","Chierico","Mago"], tempo:"1 ora", gittata:"Tocco", desc:"Quando l’incantatore lancia questo incantesimo, traccia un glifo da cui in seguito si sprigionerà un effetto magico. Il glifo può essere tracciato su una superficie (come un tavolo, una sezione di pavimento o una parete) o all'interno di un oggetto che può essere chiuso (come un libro, una pergamena o un forziere del tesoro), al fine di nasconderlo. Il glifo può coprire un’area massima del diametro di 3 metri. Se la superficie o l’oggetto viene spostato per più di 3 metri dal punto in cui l’incantatore ha lanciato questo incantesimo, il glifo si infrange e l’incantesimo termina senza essere innescato. Il glifo è pressoché invisibile e richiede una prova di Intelligenza (Indagare) contro la CD del tiro salvezza dell’incantesimo per essere individuato. L’incantatore decide cosa innesca il glifo quando lancia l’incantesimo. Nel caso dei glifi tracciati su una superficie, gli inneschi più comuni includono toccare il glifo, camminare sul glifo, rimuovere un oggetto che copre il glifo, giungere ad una certa distanza dal glifo o manipolare l’oggetto su cui il glifo è stato tracciato. Nel caso di un glifo tracciato su un oggetto, gli inneschi più comuni includono aprire quell'oggetto, giungere entro una certa distanza dall'oggetto, vedere o leggere il glifo. Una volta innescato il glifo, questo incantesimo termina. L’incantatore può affinare ulteriormente l’innesco in modo che l’incantesimo si attivi solo in certe circostanze o in base a certe caratteristiche fisiche (come per esempio l’altezza o il peso), il tipo della creatura (per esempio, l’interdizione potrebbe essere regolata per influenzare le aberrazioni o i drow) o l’allineamento. L’incantatore può anche stabilire le condizioni per quelle creature che non innescano il glifo, come per esempio quelle che pronunceranno una certa parola d’ordine. Quando l’incantatore traccia il glifo, può scegliere tra glifo magico e rune esplosive.\n\n**Glifo Magico: **L’incantatore può custodire un incantesimo preparato di 3° livello o inferiore all'interno del glifo lasciandolo come parte della procedura di creazione del glifo. L’incantesimo deve bersagliare una singola creatura o un’area. L’incantesimo custodito non ha alcun effetto immediato quando viene lanciato in questo modo. Quando il glifo si innesca, l’incantesimo custodito viene lanciato. Se l’incantesimo ha un bersaglio, bersaglia la creatura che ha innescato il glifo. Se l’incantesimo influenza un’area, l’area è centrata su quella creatura. Se l’incantesimo evoca creature ostili o crea oggetti o trappole dannose, ciò che viene creato o evocato appare nel punto più vicino possibile all'intruso e lo attacca. Se l’incantesimo richiede concentrazione, permane fino alla fine della sua durata.\n\n**Rune Esplosive: **Quando questo glifo viene innescato, diffonde un’ondata di energia magica in una sfera del raggio di 6 metri centrata su di esso. La sfera si diffonde oltre gli angoli. Ogni creatura entro l’area deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 5d8 danni da acido, freddo, fulmine, fuoco o tuono (a scelta dell’incantatore al momento della creazione del glifo), mentre se lo supera, subisce soltanto la metà di quei danni.\n\n** ****Ai Livelli Superiori: **Quando l’incantatore crea un glifo magico, può custodire qualsiasi incantesimo di livello pari o inferiore al livello dello slot usato per il glifo di interdizione. Se l’incantatore lancia questo incantesimo usando uno slot incantesimo di 4° livello o superiore, i danni di un glifo rune esplosive aumentano di 1d8 per ogni slot di livello superiore al 3°." },
  "Fingere Morte": { livello:3, scuola:"Necromanzia", classi:["Bardo","Chierico","Druido","Mago"], tempo:"1 Azione", gittata:"Tocco", rituale:true, desc:"Tocchi una creatura consenziente e la poni in uno stato catalettico indistinguibile dalla morte per la durata di 1 ora. Fino al termine dell'incantesimo, il bersaglio appare morto a tutte le ispezioni fisiche e agli incantesimi di divinazione. È accecato e incapacitato, la sua velocità è 0, ottiene resistenza a tutti i danni tranne psichici ed è immune a veleno e malattie." },
  "Non Rilevabile": { livello:3, scuola:"Abiurazione", classi:["Bardo","Mago","Ranger"], tempo:"1 Azione", gittata:"Tocco", desc:"Per la durata dell'incantesimo, l'incantatore nasconde un bersaglio da lui toccato dalle magie di divinazione. Il bersaglio può essere una creatura consenziente o un luogo o un oggetto non più grande di 3 metri in ogni dimensione. Il bersaglio non può essere bersagliato da alcuna magia di divinazione né percepito dai sensori di scrutamento magico." },
  "Nube Assassina": { livello:5, scuola:"Evocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"36m", area:"Sfera 6m", danno:"5d8", tipoDanno:"Veleno", conc:true, desc:"L'incantatore crea una sfera di velenosa nebbia giallo-verdastra del raggio di 6 metri, centrata su un punto a sua scelta entro gittata.\n\nLa nebbia si diffonde oltre gli angoli e permane per la durata dell'incantesimo o finché un vento forte non la disperde, terminando l'incantesimo.\n\nLa sua aera è pesantemente oscurata.\n\nQuando una creatura entra nell'area dell'incantesimo per la prima volta in un turno o inizia il proprio turno al suo interno, deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 5d8 danni da veleno, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nLe creature sono influenzate dall'incantesimo anche se trattengono il respiro o non hanno bisogno di respirare.\n\nLa nebbia si muove allontanandosi di 3 metri dall'incantatore all'inizio di ogni turno di quest'ultimo, strisciando lungo il terreno.\n\nI vapori sono più pesanti dell'aria e rimangono al livello del terreno; possono persino scendere nelle aperture.\n\n**Ai Livelli Superiori**. Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, i danni aumentano di 1d8 per ogni slot di livello superiore al 5°." },
  "Animare Oggetti": { livello:5, scuola:"Trasmutazione", classi:["Artefice","Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"36m", conc:true, desc:"fino a 1 minuto Gli oggetti si animano su ordine dell'incantatore. L'incantatore sceglie un numero di oggetti non magici entro gittata che non siano indossati o trasportati, fissati su una superficie o di dimensioni Mastodontiche. Il numero massimo di oggetti è uguale al suo modificatore di caratteristica da incantatore; per questo numero, un bersaglio di taglia Media o inferiore conta come un oggetto, un bersaglio di taglia Grande conta come due e un ­bersaglio Enorme conta come tre. Ogni bersaglio si anima e diventa un costrutto provvisto di gambe che utilizza la scheda delle statistiche dell'oggetto animato; questa creatura è sotto il controllo dell'incantatore fino al termine dell'incantesimo o finché non viene ridotta a 0 punti ferita. Ogni creatura creata con questo incantesimo diventa un alleato per l'incantatore e i suoi alleati. In combattimento, la creatura ha lo stesso punteggio di iniziativa dell'incantatore, ma inizia il turno immediatamente dopo il suo. Fino al termine dell'incantesimo, come azione bonus, l'incantatore può comandare mentalmente qualsiasi creatura creata con questo incantesimo, a patto che si trovi entro 150 metri da sé (se controlla varie creature, l'incantatore può comandarne più di una allo stesso momento, impartendo lo stesso comando a ciascuna di loro). Se invece non impartisce alcun comando, la creatura effettua l'azione Schivata e si sposta solo per evitare di subire danni. Quando la creatura scende a 0 punti ferita, riassume la sua forma di oggetto, a cui vengono trasferiti eventuali danni rimanenti. Utilizzo di uno slot incantesimo di livello superiore. I danni da Schianto della creatura aumentano 125 System Reference Document 5.2.1 di 1d4 (taglia Media o inferiore), 1d6 (taglia Grande) o 1d12 (taglia Enorme) per ogni slot di livello superiore al 5º. Oggetto animato Costrutto Enorme o inferiore, senza allineamento CA 15 PF 10 (taglia Media o inferiore), 20 (taglia Grande), 40 (taglia Enorme) Velocità 9 m MOD SALV MOD SALV MOD SALV For 16 +3 +3 Des 10 +0 +0 Cos 10 +0 +0 Int 3 −4 −4 Sag 3 −4 −4 Car 1 −5 −5 Immunità affascinato, avvelenato, indebolimento, paralizzato, psichico, spaventato, veleno Sensi Percezione passiva 6; vista cieca 9 m Lingue comprende le lingue parlate dal personaggio GS nessuno (PE 0; BC pari al bonus di competenza del personaggio) Azioni Schianto. Tiro per colpire in mischia: il bonus equivale al modificatore di attacco dell'incantesimo del personaggio, portata di 1,5 m Colpito: danni da forza pari a 1d4 + 3 (taglia Media o inferiore), 2d6 + 3 + il modificatore di caratteristica da incantatore dell'incantatore (taglia Grande) o 2d12 + 3 + il modificatore di caratteristica da incantatore dell'incantatore (taglia Enorme).\n\n**Ai Livelli Superiori.** I danni da Schianto della creatura aumentano 125 System Reference Document 5.2.1 di 1d4 (taglia Media o inferiore), 1d6 (taglia Grande) o 1d12 (taglia Enorme) per ogni slot di livello superiore al 5º. Oggetto animato Costrutto Enorme o inferiore, senza allineamento CA 15 PF 10 (taglia Media o inferiore), 20 (taglia Grande), 40 (taglia Enorme) Velocità 9 m MOD SALV MOD SALV MOD SALV For 16 +3 +3 Des 10 +0 +0 Cos 10 +0 +0 Int 3 −4 −4 Sag 3 −4 −4 Car 1 −5 −5 Immunità affascinato, avvelenato, indebolimento, paralizzato, psichico, spaventato, veleno Sensi Percezione passiva 6; vista cieca 9 m Lingue comprende le lingue parlate dal personaggio GS nessuno (PE 0; BC pari al bonus di competenza del personaggio) Azioni Schianto. Tiro per colpire in mischia: il bonus equivale al modificatore di attacco dell'incantesimo del personaggio, portata di 1,5 m Colpito: danni da forza pari a 1d4 + 3 (taglia Media o inferiore), 2d6 + 3 + il modificatore di caratteristica da incantatore dell'incantatore (taglia Grande) o 2d12 + 3 + il modificatore di caratteristica da incantatore dell'incantatore (taglia Enorme)." },
  "Circolo di Teletrasporto": { livello:5, scuola:"Evocazione", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 min", gittata:"3m", desc:"Quando l'incantatore lancia l'incantesimo, traccia un cerchio del diametro di 3 metri dotato di simboli che collegano il suo luogo a un cerchio di teletrasporto permanente a sua scelta, di cui gli è nota la sequenza di simboli e che si trovi sul suo stesso piano di esistenza. All'interno del cerchio tracciato dall'incantatore si apre un portale scintillante che resta aperto fino alla fine del turno successivo dell'incantatore. Ogni creatura che entra nel portale appare istantaneamente entro 1,5 metri dal cerchio di destinazione, o nello spazio libero più vicino, se quello spazio è occupato.\n\nMolti dei più importanti templi, gilde e altri luoghi simili possiedono un cerchio di teletrasporto permanente tracciato da qualche parte entro i loro confini. A ogni cerchio di questo tipo è abbinata una sequenza di simboli unica, una serie di rune magiche disposte secondo uno schema particolare. Quando l'incantatore ottiene per la prima volta la capacità di lanciare questo incantesimo, apprende la sequenza di simboli abbinata a due destinazioni situate sul Piano Materiale, determinate dal DM. L'incantatore può apprendere ulteriori sequenze di simboli nel corso delle sue avventure. Per imparare a memoria una nuova sequenza di simboli ha bisogno di studiarla per 1 minuto.\n\nL'incantatore può creare un cerchio di teletrasporto permanente lanciando questo incantesimo sullo stesso luogo ogni giorno per un anno. Non è obbligato a usare il cerchio di teletrasporto quando lo lancia in questo modo" },
  "Creazione": { livello:5, scuola:"Illusione", classi:["Artefice","Bardo","Mago","Stregone"], tempo:"1 min", gittata:"9m", desc:"L'incantatore chiama a sé dei filamenti di sostanza d'ombra dalla Coltre Oscura per creare un oggetto non vivente di materia vegetale entro gittata: stoffa, corda, legno o altri materiali simili.\n\nPuò usare questo incantesimo anche per creare oggetti fatti di minerali come pietra, cristallo o metallo.\n\nL'oggetto creato non deve essere più grande di un cubo con spigolo di 1,5 metri e deve avere una forma e un materiale che l'incantatore abbia già visto in precedenza.\n\nLa durata dipende dal materiale dell'oggetto.\n\nSe l'oggetto è composto da più materiali, si usa la durata più breve.\n\nMateriale\nDurata\n\nMateria vegetale\n1 giorno\n\nPietra o cristallo\n12 ore\n\nMetalli preziosi\n1 ora\n\nGemme\n10 minuti\n\nAdamantio o mithral\n1 minuto\n\nL'uso di qualsiasi materiale creato da questo incantesimo come componente materiale di un altro incantesimo provoca il fallimento di quell'incantesimo.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 6° livello o superiore, lo spigolo del cubo aumenta di 1,5 metri per ogni slot di livello superiore al 5°." },
  "Legame Planare": { livello:5, scuola:"Abiurazione", classi:["Bardo","Chierico","Druido","Mago"], tempo:"1 ora", gittata:"18m", desc:"Con questo incantesimo, l'incantatore tenta di vincolare un celestiale, un elementale, un folletto o un immondo e di metterlo al suo servizio. La creatura deve trovarsi entro gittata per l'intero lancio dell'incantesimo. (Solitamente la creatura viene prima evocata al centro di un *cerchio magico* invertito per tenerlo intrappolato mentre questo incantesimo viene lanciato.) Completato il lancio, il bersaglio deve effettuare un tiro salvezza su Carisma. Se lo fallisce, è obbligato a servire l'incantatore per la durata dell'incantesimo. Se la creatura è stata evocata o creata da un altro incantesimo, la durata di quell'incantesimo viene estesa per corrispondere alla durata di questo.\n\nUna creatura vincolata deve eseguire le istruzioni dell'incantatore al meglio delle sue capacità. L'incantatore potrebbe ordinare alla creatura di accompagnarlo in un'avventura, di proteggere un luogo o di trasmettere un messaggio. La creatura obbedisce alla lettera alle sue istruzioni, ma se è ostile nei confronti dell'incantatore lotterà per interpretare a modo suo le parole di quest'ultimo e perseguire i suoi obiettivi personali. Se la creatura porta a termine le istruzioni dell'incantatore prima che l'incantesimo termini, si reca da lui per riferirgli di ciò che ha fatto, se si trova sul suo stesso piano di esistenza. Se l'incantatore si trova su un piano di esistenza diverso, la creatura torna nel luogo in cui è stata vincolata e vi rimane finché l'incantesimo non termina.\n\n**Ai Livelli Superiori.** Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di un livello superiore, la durata aumenta a 10 giorni con uno slot di 6° livello, a 30 giorni con uno slot di 7° livello, a 180 giorni con uno slot di 8° livello e a un anno e un giorno con uno slot di 9° livello." },
  "Disintegrazione": { livello:6, scuola:"Trasmutazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"18m", danno:"10d6+40", tipoDanno:"Forza", desc:"Un sottile raggio verde si sprigiona dall'indice dell'incantatore fino a un bersaglio situato entro gittata e che egli sia in grado di vedere.\n\nIl bersaglio può essere una creatura, un oggetto o una creazione di forza magica, come il muro creato da un @Compendium[world.tutti-gli-incantesimi.4oJ61FLdXMIKuzsu]{Muro di Forza}.\n\nUna creatura bersagliata da questo incantesimo deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 10d6 + 40 danni da forza.\n\nSe questi danni riducono il bersaglio a 0 punti ferita, il bersaglio è disintegrato.\n\nUna creatura disintegrata e tutto ciò che essa indossa e trasporta (tranne gli oggetti magici) si riduce in un cumulo di sottile polvere grigia. La creatura può essere riportata in vita soltanto tramite un incantesimo @Compendium[world.tutti-gli-incantesimi.CaQMve39xhmZlNUr]{Desiderio} o @Compendium[world.tutti-gli-incantesimi.GFOuQ9CwxjyvsnA2]{Resurrezione Pura}.\n\nQuesto incantesimo disintegra automaticamente un oggetto non magico di taglia Grande o inferiore o una creazione di forza magica.\n\nSe il bersaglio è un oggetto o una creazione di forza magica di taglia Enorme o superiore, questo incantesimo disintegra una parte di esso grande quanto un cubo con spigolo di 3 metri.\n\nUn oggetto magico non è influenzato da questo incantesimo.\n\n**Ai Livelli Superiori. **Quando l'incantatore lancia questo incantesimo usando uno slot incantesimo di 7° livello o superiore, i danni aumentano di 3d6 per ogni slot di livello superiore al 6°." },
  "Globo di Invulnerabilità": { livello:6, scuola:"Abiurazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"Sé stesso (sfera 3m)", conc:true, desc:"Un immobile e tenuemente scintillante barriera prende forma in un raggio di 3 metri intorno all'incantatore e permane per la durata.\n\nQualsiasi incantesimo di 5° livello o inferiore lanciato dall'esterno della barriera non può influenzare le creature od oggetti al suo interno, persino se l'incantesimo viene lanciato utilizzando uno slot incantesimo di livello superiore. Un incantesimo di questo tipo può prendere come bersaglio creature ed oggetti all'interno della barriera, ma l'incantesimo non ha alcun effetto su di essi. In maniera analoga, l'area all'interno della barriera viene esclusa dall'area d'effetto di quegli incantesimi.\n\n***Ai Livelli Superiori. ***Quando l'incantatore lancia questo incantesimo utilizzando uno slot incantesimo di 7° livello o superiore, la barriera blocca incantesimi di un livello superiore per ogni livello di slot superiore al 6°." },
  "Ferire": { livello:6, scuola:"Necromanzia", classi:["Chierico"], tempo:"1 Azione", gittata:"18m", danno:"14d6", tipoDanno:"Necrotico", desc:"L'incantatore rilascia una virulenta malattia contro una creatura che sia visibile ed entro gittata. Il bersaglio deve effettuare un tiro salvezza Costituzione. Se lo fallisce, subisce 14d6 danni necrotici oppure la metà di quel danno se lo supera. Il danno non può ridurre i punti ferita del bersaglio a meno di 1.\n\nSe il bersaglio fallisce il tiro salvezza, i suoi punti ferita massimi sono ridotti per 1 ora di un ammontare pari al danno necrotico subito. Qualsiasi effetto che rimuova una malattia permette ad una creatura di recuperare i punti ferita massimi normali prima che passi quel tempo." },
  "Contingenza": { livello:6, scuola:"Invocazione", classi:["Mago"], tempo:"10 min", gittata:"Sé stesso", desc:"L’incantatore sceglie un incantesimo di livello pari o inferiore a 5 che sia in grado di lanciare, che abbia un tempo di lancio di un’azione e che possa avere come bersaglio l’incantatore stesso. Lancia l’incantesimo, chiamato incantesimo contingente, come parte del lancio di *Contingenza*, consumando gli slot incantesimo per entrambi. L’incantesimo contingente, tuttavia, non ha effetto finché non si verificano determinati inneschi che l’incantatore descrive nel momento in cui lancia i due incantesimi. Per esempio, un lancio di *Contingenza* con *Respirare sott’acqua* potrebbe stabilire che *Respirare sott’acqua* avrà effetto quando l’incantatore sarà sommerso nell’acqua o in un liquido simile.\n\nChe l’incantatore lo desideri o meno, l’incantesimo contingente ha effetto nel momento in cui gli inneschi vengono soddisfatti per la prima volta, poi *Contingenza* termina.\n\nL’incantesimo contingente ha effetto solamente sull’incantatore, nonostante normalmente possa essere lanciato su altri bersagli. L’incantatore può utilizzare un solo incantesimo *Contingenza* alla volta. Se l’incantatore lancia nuovamente questo incantesimo, l’effetto di un altro incantesimo *Contingenza* su di sé termina. Inoltre, *Contingenza* termina qualora la sua componente materiale non si trovi sulla persona dell’incantatore.\n\n**Nota Foundry**\n\nL’attività “crea contingenza” è configurata per incantare opzionalmente una Pergamena che tenga traccia e serva come incantesimo innescato. Crea una pergamena di incantesimo facendo clic destro su un incantesimo nella tua lista, consuma uno slot incantesimo del livello della pergamena creata e incanta la pergamena." },
  "Dito della Morte": { livello:7, scuola:"Necromanzia", classi:["Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", danno:"7d8+30", tipoDanno:"Necrotico", desc:"L'incantatore trasmette un flusso di energia negativa attraverso una creatura entro gittata e che egli sia in grado di vedere, provocandole un dolore lancinante.\n\nIl bersaglio deve effettuare un tiro salvezza su Costituzione. Se lo fallisce, subisce 7d8 + 30 danni necrotici, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nUn umanoide ucciso da questo incantesimo si anima all'inizio del turno successivo dell'incantatore come zombi permanentemente al suo comando: obbedirà ai suoi ordini verbali al meglio delle sue capacità." },
  "Teletrasporto": { livello:7, scuola:"Evocazione", classi:["Bardo","Mago","Stregone"], tempo:"1 Azione", gittata:"3m", desc:"Questo incantesimo trasporta immediatamente l'incantatore e un massimo di otto creature consenzienti a sua scelta, situate entro gittata e che egli sia in grado di vedere, oppure un singolo oggetto entro gittata e che egli sia in grado di vedere, in una destinazione a sua scelta.\n\nSe bersaglia un oggetto, quell'oggetto deve essere interamente contenuto in un cubo con spigolo di 3 metri e non può essere impugnato o trasportato da una creatura non consenziente.\n\nLa destinazione scelta deve essere nota all'incantatore e deve trovarsi sul suo stesso piano di esistenza.\n\nla familiarità dell'incantatore nei confronti della destinazione determina se l'incantatore riesce a raggiungerla.\n\nIl DM tira un d100 e consulta la tabella.\n\nd100\nErrore\nArea Simile\nFuori Bersaglio\nSul Bersaglio\n\nCerchio permanente\n-\n-\n-\n01-100\n\nOggetto Associato\n-\n-\n-\n01-100\n\nMolto Familiare\n01-05\n06-13\n14-24\n25-100\n\nVisto per caso\n01-33\n34-43\n44-53\n54-100\n\nVisto una volta\n01-43\n44-53\n54-73\n74-100\n\nDescrizione\n01-43\n44-53\n54-73\n74-100\n\nFalsa Destinazione\n01-50\n51-100\n-\n-\n\n**Familiarità**. \"Cerchio permanente\" indica un cerchio di teletrasporto permanente di cui l'incantatore conosce la sequenza di simboli. \"Oggetto associato\" significa che l'incantatore è in possesso di un oggetto prelevato della destinazione desiderata da non più di sei mesi, come un libro dalla biblioteca di un mago, lenzuola da un alloggio reale o un frammento di marmo della tomba segreta di un lich. \"Molto familiare\" è un luogo in cui l'incantatore ha visitato molto spesso, un luogo che ha studiato attentamente o un luogo che può vedere quando lancia l'incantesimo. \"Visto per caso\" è un luogo che l'incantatore ha visto più di una volta ma con cui non ha molta familiarità. \"Visto una volta\" è un posto che l'incantatore ha visto una volta, probabilmente usando la magia. \"Descrizione\" è un luogo di cui l'ubicazione e apparenza sono noti all'incantatore grazie la descrizione di qualcun altro o forse grazie ad una mappa. \"Falsa Destinazione\" è un luogo che non esiste. Forse l'incantatore ha cercato di scrutare il rifugio segreto di un nemico ma ha visto un illusione, oppure tenta di teletrasportarsi in un luogo familiare che non esiste più.\n\n**Sul Bersaglio.** L'incantatore e il suo gruppo (o l'oggetto bersaglio) compaiono dove l'incantatore vuole.\n\n**Fuori dal Bersaglio.** L'incantatore e il suo gruppo (o l'oggetto bersaglio) compaiono a una distanza casuale dalla destinazione in una direzione casuale. La distanza dal bersaglio è 1d10 x 1d10 percento della distanza da percorrere. Ad esempio, se un incantatore ha provato a percorrere 180 km, arriva fuori bersaglio e ottiene un 5 e 3 sui due d10, allora sarebbe fuori bersaglio del 15 percento o 27 km. Il DM determina la direzione fuori bersaglio in modo casuale tirando un d8, dove l'1 corrisponde al nord, 2 al nord-est, 3 all'est e così via ad indicare i punti cardinali. Se l'incantatore voleva teletrasportarsi in una città costiera e finisse per 27 km in mare, potrebbe essere nei guai.\n\n**Area simile**. L'incantatore e il suo gruppo (o l'oggetto bersaglio) arrivano in un'area diversa che è visivamente o tematicamente simile all'area bersaglio. Per esempio: se è diretto al suo laboratorio personale, potrebbe finire nel laboratorio di un altro mago o in un negozio di sostanze alchemiche che contiene molti strumenti e materiali simili a quelli del suo laboratorio. In genere appare nel luogo simile più vicino, ma dal momento che l'incantesimo non ha limiti di gittata, in teoria potrebbe finire in un qualsiasi punto del piano.\n\n**Errore**. La magia imprevedibile dell'incantesimo rende il viaggio più difficile. Ogni creatura si teletrasportata (o l'oggetto bersaglio) subisce danni da forza 3d10 e il DM ripete il tiro sulla tabella per determinare dove arriverà (potrebbe verificare più di un errore, nel qual caso i danni vengono applicati ogni volta)." },
  "Palla di Fuoco Ritardata": { livello:7, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"45m", danno:"12d6", tipoDanno:"Fuoco", conc:true, desc:"Un raggio di luce gialla si sprigiona dall'incantatore per poi condensarsi in un punto a sua scelta entro gittata, formando una sfera scintillante che permane per la durata dell'incantesimo. Al termine dell'incantesimo, la sfera esplode e ogni creatura all'interno di una sfera del raggio di 6 metri centrata su quel punto effettua un tiro salvezza su Destrezza. In caso di fallimento, la creatura subisce una quantità di danni da fuoco pari al totale dei danni accumulati, o la metà dei danni in caso di successo.\n\nI danni base dell'incantesimo sono pari a 12d6 e aumentano di 1d6 ogni volta che termina il turno dell'incantatore e l'incantesimo è ancora attivo.\n\nSe una creatura tocca la sfera scintillante prima del termine dell'incantesimo, effettua un tiro salvezza su Destrezza. In caso di fallimento, l'incantesimo termina, causando l'esplosione della sfera. In caso di successo, la creatura può lanciare la sfera fino a una distanza di 12 metri: se entra nello spazio di una creatura o si scontra con un oggetto solido, l'incantesimo termina, facendo esplodere la sfera.\n\nQuando la sfera esplode, gli oggetti infiammabili all'interno dell'esplosione che non sono indossati o trasportati iniziano a bruciare.\n\n**Utilizzo di uno slot incantesimo di livello superiore.** I danni base aumentano di 1d6 per ogni slot di livello superiore al 7º.\n\n**Foundry Note**\n\nIl valore di utilizzi limitati di questo incantesimo tiene traccia del numero di round trascorsi dal lancio iniziale e parte da 0.\n\nL'attività **Aumento Danni a Fine Turno** incrementa tale valore di 1.\n\nL'attività **Innesca Esplosione** calcola il totale dei danni in base agli utilizzi limitati.\n\nSe preferisci una gestione manuale, puoi usare la finestra del Bonus Situazionale di **Innesca Esplosione** per aggiungere i d6 extra e ignorare l'attività **Aumento Danni a Fine Turno**." },
  "Gabbia di Forza": { livello:7, scuola:"Invocazione", classi:["Bardo","Mago","Warlock"], tempo:"1 Azione", gittata:"30m", desc:"Un immobile e invisibile prigione di forma cubica composta di energia magica prende forma attorno ad un area entro gittata a scelta dell'incantatore. La prigione può essere una gabbia o una scatola solida, a discrezione dell'incantatore.\n\nLa prigione a forma di gabbia può essere lunga fino a 6 metri per lato ed è composta da barre del diametro di 1,5 cm spaziate fra di loro di 1,5 cm.\n\nLa prigione a forma di scatola può essere lunga fino a 3 metri per lato, creando una barriera solida che impedisce il passaggio di qualsiasi materia attraverso di essa e bloccando qualsiasi incantesimo lanciato verso l'interno o verso l'esterno di quell'area.\n\nQuando l'incantatore lancia l'incantesimo, qualsiasi creatura che si trovi completamente all'interno dell'area della gabbia viene intrappolata. Le creature solo parzialmente all'interno dell'area, o quelle troppo grandi per poter essere contenute all'interno dell'area, vengono allontanate dal centro dell'area finchè non se ne trovano completamente all'esterno.\n\nUna creatura all'interno della gabbia non può uscirne attraverso mezzi non-magici. Se la creatura prova ad utilizzare teletrasporto o viaggio interplanare per uscire dalla gabbia, deve prima effettuare un tiro salvezza su Carisma. Con un successo, la creatura può usare quella magia per uscire dalla gabbia. Con un fallimento, la creatura non può uscire e consuma l'utilizzo dell'incantesimo o abilità senza alcun effetto. La gabbia si estende anche nel Piano Etereo, bloccando lo spostamento etereo.\n\nQuesto incantesimo non può essere dissolto dall'incantesimo @Compendium[world.tutti-gli-incantesimi.DCQ9iVOQYgosgW8u]{Dissolvi Magie}" },
  "Forma Eterea": { livello:7, scuola:"Trasmutazione", classi:["Bardo","Chierico","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"Sé stesso", desc:"L'incantatore mette i piedi nelle regioni di confine del Piano Etereo, nell'area dove si sovrappone con il suo piano attuale. L'incantatore rimane nei Confini Eterei per la durata oppure finchè effettua un'azione per dissolvere l'incantesimo. Durante questo periodo, si può spostare in qualsiasi direzione. Se l'incantatore si sposta verso l'alto o il basso, ogni metro di movimento costa un metro extra. L'incantatore è in grado di vedere e sentire il piano dal quale proviene, ma ogni cosa appare grigia e non può vedere oltre 18 metri di distanza.\n\nMentre si trova nel Piano Etereo, l'incantatore può influenzare ed essere influenzato solo da creature presenti in quel piano. Le creature che non si trovano nel Piano Etereo non possono percepire o interagire con l'incantatore, a meno che un'abilità speciale o incantesimo garantisca loro la capacità di farlo.\n\nL'incantatore ignora tutti gli oggetti ed effetti che non si trovano nel Piano Etereo, permettendogli di muoversi attraverso oggetti che percepisce nel piano dal quale proviene.\n\nQuando l'incantesimo termina, l'incantatore torna immediatamente al piano dal quale è partito nel punto in cui si trova attualmente. Se l'incantatore occupa lo stesso spazio di un oggetto solido o una creatura quando ciò accade, viene subito spinto verso il più vicino spazio libero che possa occupare e subisce danni da forza pari al doppio dei metri di cui viene spostato.\n\nQuesto incantesimo non ha effetto se viene lanciato mentre l'incantatore si trova nel Piano Etereo o in un piano che non sia confinante con esso, come uno dei Piani Esterni.\n\n***Ai Livelli Superiori.*** Se questo incantesimo viene lanciato utilizzando uno slot incantesimo di 8° livello o superiore, possono essere scelte come bersaglio fino ad altre tre creature consenzienti (incantatore incluso) per ogni livello di slot incantesimo oltre il 7°. Le creature devono trovarsi entro 3 metri dall'incantatore quando l'incantesimo viene lanciato." },
  "Labirinto": { livello:8, scuola:"Evocazione", classi:["Mago"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"L'incantatore esilia una creatura entro gittata e che egli sia in grado di vedere su un semipiano labirintico.\n\nIl bersaglio rimane laggiù per la durata dell'incantesimo o finché non fugge dal labirinto.\n\nIl bersaglio può usare la sua azione per tentare di fuggire.\n\nQuando lo fa, effettua una prova di Intelligenza con CD 20. Se ha successo, riesce a fuggire e l'incantesimo termina (un Minotauro o un demone goristro hanno successo automaticamente).\n\nQuando l'incantesimo termina, il bersaglio ricompare nello spazio che ha lasciato o, se quello spazio è occupato, nello spazio libero più vicino." },
  "Nube Incendiaria": { livello:8, scuola:"Invocazione", classi:["Druido","Mago","Stregone"], tempo:"1 Azione", gittata:"45m", area:"Sfera 6m", danno:"10d8", tipoDanno:"Fuoco", conc:true, desc:"Una nube turbinante di fumo mista a un nugolo di tizzoni incandescenti appare in una sfera del raggio di 6 metri centrata su un punto entro gittata.\n\nLa nube si diffonde oltre gli angoli ed è pesantemente oscurata.\n\nPermane per la durata dell'incantesimo o finché un vento moderato o superiore (almeno 15 km all'ora) non la disperde.\n\nQuando la nube appare, ogni creatura al suo interno deve effettuare un tiro salvezza su Destrezza. Se lo fallisce, subisce 10d8 danni da fuoco, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nUna creatura deve effettuare questo tiro salvezza anche quando entra nell'area dell'incantesimo per la prima volta in un turno o vi termina il proprio turno.\n\nLa nube si muove di 3 metri allontanandosi direttamente dall'incantatore, in una direzione a scelta di quest'ultimo all'inizio di ogni suo turno." },
  "Mente Vuota": { livello:8, scuola:"Abiurazione", classi:["Bardo","Mago"], tempo:"1 Azione", gittata:"Tocco", desc:"Finché l'incantesimo non termina, una creatura consenziente toccata dall'incantatore è immune ai danni psichici, a qualsiasi effetto che percepirebbe le sue emozioni o leggerebbe i suoi pensieri, agli incantesimi di divinazione e alla condizione di affascinato.\n\nL'incantesimo neutralizza perfino gli incantesimi @Compendium[world.tutti-gli-incantesimi.CaQMve39xhmZlNUr]{Desiderio} e gli incantesimi o effetti di potenza analoga usati per influenzare la mente del bersaglio o ottenere informazioni su quel bersaglio." },
  "Clone": { livello:8, scuola:"Necromanzia", classi:["Mago"], tempo:"1 ora", gittata:"Tocco", desc:"Questo incantesimo sviluppa un duplicato inerte di una creatura vivente come misura di sicurezza contro la morte. Questo clone si sviluppa all'interno di un involucro sigillato e raggiunge la taglia completa e la maturità dopo 120 giorni; l'incantatore può anche scegliere che il clone sia una versione più giovane della stessa creatura. li clone rimane inerte e permane a tempo indeterminato, fintanto che il suo involucro rimane indisturbato. In un qualsiasi momento dopo che il clone è giunto a maturazione, se la creatura originale muore, la sua anima si trasferisce nel clone, purché quell'anima sia libera e disposta a tornare. Il clone è fisicamente identico all'originale e possiede la personalità, i ricordi e le capacità dell'originale, ma non il suo equipaggiamento. I resti fisici della creatura originale, se ancora esistono, diventano inerti e non possono più essere riportati in vita, dal momento che l'anima della creatura si trova altrove." },
  "Sciame di Meteore": { livello:9, scuola:"Invocazione", classi:["Mago","Stregone"], tempo:"1 Azione", gittata:"1,6 km", danno:"20d6+20d6", tipoDanno:"Fuoco/Contundente", desc:"Globi rocciosi infuocati precipitano a terra in quattro punti diversi situati entro gittata e che l'incantatore sia in grado di vedere.\n\nOgni creatura situata entro una sfera del raggio di 12 metri centrata su ogni punto scelto dall'incantatore deve effettuare un tiro salvezza su Destrezza.\n\nLa sfera si diffonde oltre gli angoli.\n\nSe una creatura fallisce il tiro salvezza, subisce 20d6 danni da fuoco e 20d6 danni contundenti, mentre se lo supera, subisce soltanto la metà di quei danni.\n\nUna creatura entro l'area di più esplosioni infuocate ne subisce l'effetto una volta sola.\n\nL'incantesimo infligge danni ad oggetti nell'area e incendia gli oggetti infiammabili che non sono indossati o trasportati." },
  "Muro Prismatico": { livello:9, scuola:"Abiurazione", classi:["Bardo","Mago"], tempo:"1 Azione", gittata:"18m", desc:"Un piano di luce dai numerosi colori scintillanti forma un muro opaco verticale (che può misurare fino a 27 metri di lunghezza, 9 metri di altezza e 2,5 cm di spessore), centrato su un punto entro gittata e che l'incantatore sia in grado di vedere.\n\nIn alternativa, l'incantatore può modellare il muro in una sfera del diametro massimo di 9 metri centrata su un punto a sua scelta entro gittata.\n\nIl muro rimane al suo posto per la durata dell'incantesimo.\n\nSe l'incantatore posiziona il muro in modo che passi attraverso uno spazio occupato da una creatura l'incantesimo fallisce e sia l'azione dell'incantatore che il suo slot incantesimo vanno sprecati.\n\nIl muro emana luce intensa entro un raggio di 30 metri e luce fioca per altri 30 metri.\n\nL'incantatore e le creature da lui designate al momento del lancio dell'incantesimo possono passare attraverso il muro o rimanervi accanto senza subire danni.\n\nSe un'altra creatura in grado di vedere il muro giunge entro 6 metri da esso o vi comincia il proprio turno, deve superare un tiro salvezza su Costituzione, altrimenti è accecata per 1 minuto.\n\nIl muro è composto da sette strati, ognuno di un colore diverso. Quando una creatura tenta di protendersi oltre il muro o di attraversarlo, lo fa di uno strato alla volta, fino ad attraversare tutti gli strati del muro.\n\nQuando si protende o attraversa ogni strato, deve effettuare un tiro salvezza su Destrezza, altrimenti sarà influenzata dalle proprietà di quello strato, come descritto di seguito.\n\nIl muro può essere distrutto, anche in questo caso uno strato alla volta, procedendo in ordine dal rosso al viola, tramite un modo specifico per ogni strato.\n\nQuando uno strato è distrutto, resta distrutto per la durata dell'incantesimo.\n\nUn incantesimo Campo Anti-Magia non ha alcun effetto sul muro e Dissolvi Magie può influenzare solo lo strato viola.\n\n- **Rosso**. La creatura subisce 10d6 danni da fuoco se fallisce il tiro salvezza, o soltanto la metà di quei danni se lo supera. Finché questo strato è al suo posto, gli attacchi a distanza non magici non possono attraversare il muro. Lo strato può essere distrutto infliggendogli almeno 25 danni da freddo.\n\n- **Arancione**. La creatura subisce 10d6 danni da acido se fallisce il tiro salvezza, o soltanto la metà di quei danni se lo supera. Finché questo strato è al suo posto, gli attacchi a distanza magici non possono attraversare il muro. Lo strato può essere distrutto da un vento forte.\n\n- **Giallo**. La creatura subisce 10d6 danni da fulmine se fallisce il tiro salvezza, o soltanto la metà di quei danni se lo supera. Questo strato può essere distrutto infliggendogli almeno 60 danni da forza.\n\n- **Verde**. La creatura subisce 10d6 danni da veleno se fallisce il tiro salvezza, o soltanto la metà di quei danni se lo supera. Un incantesimo passapareti o un altro incantesimo di livello pari o superiore in grado di aprire un portale su una superficie solida distrugge questo strato.\n\n- **Blu**. La creatura subisce 10d6 danni da freddo se fallisce il tiro salvezza, o soltanto la metà di quei danni se lo supera. Questo strato può essere distrutto infliggendogli almeno 25 danni da fuoco.\n\n- **Indaco**. In caso di tiro salvezza fallito, la creatura è trattenuta. Deve effettuare un tiro salveza su Costituzione alla fine di ogni suo turno. Se supera il tiro salvezza tre volte, l'incantesimo termina. Se lo fallisce tre volte, si trasforma in pietra permanentemente ed è soggetta alla condizione di pietrificato. Non è necessario che i successi e i fallimenti siano consecutivi; si tiene conto di entrambi finché il bersaglio non ne accumula tre di un tipo. Finché questo strato è al suo posto, non è possibile lanciare incantesimi attraverso il muro. Questo strato è distrutto da una luce intensa emanata da un incantesimo Luce Diurna o un incantesimo analogo di livello pari o superiore.\n\n- **Viola**. In caso di tiro salvezza fallito, la creatura è accecata. Deve quindi effettuare un tiro salvezza su Saggezza all'inizio del turno successivo dell'incantatore. Se lo supera, non è più accecata, mentre se lo fallisce, viene trasportata su un altro piano di esistenza a scelta del DM, e non è più accecata (solitamente una creatura che si trova su un piano diverso dal suo piano di origine viene esiliata sul suo piano di origine, mentre le altre creature solitamente vengono inviate sul Piano Astrale o sul Piano Etereo). Questo strato è distrutto da un incantesimo Dissolvi Magie o da un incantesimo simile di livello pari o superiore che sia in grado di porre termine agli incantesimi e agli effetti magici." },
  "Metamorfosi Pura": { livello:9, scuola:"Trasmutazione", classi:["Bardo","Mago","Warlock"], tempo:"1 Azione", gittata:"9m", conc:true, desc:"L'incantatore sceglie una creatura o un oggetto non magico situato entro gittata e che egli sia in grado di vedere e trasforma la creatura in una creatura diversa o in un oggetto, oppure trasforma l'oggetto in una creatura (l'oggetto non deve essere indossato o trasportato da un'altra creatura). La trasformazione permane per la durata dell'incantesimo, o finché il bersaglio non scende a O punti ferita o non muore. Se l'incantatore si concentra su questo incantesimo per l'intera durata, la trasformazione permane finché non viene dissolta.\n\nQuesto incantesimo non ha effetto su un mutaforma o su una creatura con O punti ferita. Una creatura non consenziente può effettuare un tiro salvezza su Saggezza. Se lo supera, non è influenzata da questo incantesimo.\n\n**Creatura in Creatura. **Se l'incantatore trasforma una creatura in un altro tipo di creatura, la nuova forma può essere di qualsiasi tipo a scelta dell'incantatore, purché il suo grado di sfida sia pari o inferiore a quello del bersaglio (o del suo livello, se il bersaglio non possiede un grado di sfida). Le statistiche di gioco del bersaglio, inclusi i punteggi di caratteristica mentali, vengono sostituite dalle statistiche della nuova forma. Il bersaglio mantiene il suo allineamento e la sua personalità.\n\nIl bersaglio assume i punti ferita della sua nuova forma. Quando torna alla sua forma normale, torna al numero di punti ferita che possedeva prima della trasformazione. Se riassume la sua forma normale per essere sceso a O punti ferita, ogni eventuale danno in eccesso si trasferisce alla sua forma normale. Fintanto che i danni in eccesso non portano la forma normale della creatura a O punti ferita, essa non cade priva di sensi.\n\nLe azioni della creatura sono limitate a quelle che la natura della sua nuova forma le consente di effettuare: non può parlare, lanciare incantesimi o effettuare qualsiasi altra azione che richieda l'uso delle mani o della parola, a meno che la sua nuova forma non sia in grado di compiere tali azioni.\n\nL'equipaggiamento del bersaglio si fonde nella nuova forma. La creatura non può attivare, usare o impugnare gli oggetti del suo equipaggiamento, né trarne benefici in altri modi.\n\n**Oggetto In Creatura. **L'incantatore può trasformare un oggetto in una qualsiasi creatura, fintanto che la taglia della creatura non è superiore alla taglia dell'oggetto e il grado di sfida della creatura è pari o inferiore a 9. La creatura è amichevole nei confronti dell'incantatore e dei suoi compagni e agisce a ogni turno dell'incantatore, che decide quale azione effettua e come si muove. È il DM a possedere le sue statistiche e a risolvere le sue azioni e il suo movimento.\n\nSe l'incantesimo diventa permanente, l'incantatore non controlla più la creatura, che potrebbe rimanere amichevole o meno nei suoi confronti, in base a come è stata trattata.\n\n**Creatura In Oggetto.** Se l'incantatore trasforma una creatura in oggetto, tutto ciò che la creatura trasporta e indossa si fonde in quella forma. Le statistiche della creatura diventano quelle dell'oggetto e la creatura non ricorderà nulla del tempo trascorso in questa forma quando l'incantesimo sarà terminato ed essa tornerà alla sua forma normale" },
  "Portale": { livello:9, scuola:"Evocazione", classi:["Chierico","Mago","Stregone"], tempo:"1 Azione", gittata:"18m", conc:true, desc:"fino a 1 minuto L'incantatore evoca un portale che collega uno spazio libero entro gittata che egli è in grado di vedere a un luogo preciso su un piano di esistenza differente. Il portale è un'apertura circolare, del diametro variabile tra 1,5 e 6 metri a scelta dell'incantatore e può essere orientato in qualsiasi direzione. Il portale permane per la durata dell'incantesimo e la sua destinazione è visibile attraverso di esso. Il portale ha un lato anteriore e un lato posteriore su ogni piano dove appare e i viaggi sono possibili solo attraversandolo dalla parte anteriore. Tutto ciò che lo attraversa è trasportato immediatamente sull'altro piano, apparendo nello spazio libero più vicino al portale. Divinità e altri sovrani planari possono impedire che i portali creati tramite questo incantesimo si aprano in loro presenza o nei loro domini. Quando lancia questo incantesimo, l'incantatore può pronunciare il nome di una creatura specifica (pseudonimi, titoli o soprannomi non funzionano). Se la creatura nominata si trova su un piano diverso da quello in cui si trova l'incantatore, il portale si apre nelle immediate vicinanze della creatura, trasportandola fino allo spazio libero più vicino sul lato del portale in cui si trova l'incantatore. L'incantatore non ottiene alcun potere speciale sulla creatura, che è libera di agire come il GM ritiene più appropriato: potrebbe andarsene, attaccarlo o aiutarlo." },
  "Guarigione di Massa": { livello:9, scuola:"Invocazione", classi:["Chierico"], tempo:"1 Azione", gittata:"18m", danno:"700", tipoDanno:"Guarigione", desc:"L'incantatore può ripristinare fino a 700 punti ferita, divisi tra qualsiasi numero di creature che riesce a vedere. Le creature sono anche guarite da tutte le malattie, dalla cecità e dalla sordità. Questo incantesimo non ha effetto su non morti o costrutti." },
  "Proiezione Astrale": { livello:9, scuola:"Necromanzia", classi:["Chierico","Mago","Warlock"], tempo:"1 ora", gittata:"3m", desc:"L'incantatore e fino a un massimo di otto creature consenzienti entro gittata proiettano i loro corpi astrali sul Piano Astrale (l'incantesimo fallisce e il lancio è sprecato se l'incantatore si trova già su quel piano).\n\nIl corpo materiale che l'incantatore si lascia indietro cade privo di sensi ed entra in uno stato di animazione sospesa; non ha bisogno di cibo o di aria e non invecchia.\n\nIl corpo astrale dell'incantatore assomiglia alla sua forma mortale in quasi ogni modo, replicandone le statistiche di gioco e le proprietà. La differenza principale consiste nell'aggiunta di un cordone argentato che parte dalle sue scapole e fluttua alle sue spalle, diventando invisibile dopo circa 30 cm. Questo cordone tiene ancorato l'incantatore al suo corpo materiale. Fintanto che il cordone rimane intatto, l'incantatore è in grado di trovare la via del ritorno. Se il cordone viene reciso (cosa che accade quando un effetto lo dichiara specificatamente), l'anima e il corpo dell'incantatore si separano e l'incantatore muore sul colpo.\n\nLa forma astrale dell'incantatore può viaggiare liberamente per il Piano Astrale e può passare attraverso i portali di quel piano che conducono a qualsiasi altro piano. Se l'incantatore si sposta su un nuovo piano o torna sul piano dove si trovava quando aveva lanciato questo incantesimo, il suo corpo e le sue proprietà vengono trasportati lungo il cordone argentato, consentendo all'incantatore di rientrare nel suo corpo nel momento in cui accede al nuovo piano.\n\nLa forma astrale dell'incantatore è un'incarnazione separata.\n\nQualsiasi danno o altro effetto che si applichi a essa non ha effetto sul suo corpo fisico e non persiste quando la forma astrale vi fa ritorno.\n\nL'incantesimo permane per l'incantatore e i suoi compagni fino a quando l'incantatore usa la sua azione per terminarlo.\n\nQuando l'incantesimo termina, la creatura influenzata fa ritorno al suo corpo fisico e si sveglia.\n\nL'incantesimo potrebbe terminare prematuramente per l'incantatore o uno dei suoi compagni. Un incantesimo Dissolvi Magie usato con successo contro una forma astrale o un corpo fisico termina l'incantesimo per quella creatura.\n\nSe il corpo originale o la forma astrale di una creatura scende a 0 punti ferita, l'incantesimo termina per quella creatura.\n\nSe l'incantesimo termina e il cordone argentato è intatto, il cordone trascina la forma astrale della creatura all'interno del suo corpo, cosa che pone fine allo stato di animazione sospesa.\n\nSe l'incantatore fa ritorno al suo corpo prematuramente, i suoi compagni rimangono nelle loro forme astrali e devono trovare da soli il modo di rientrare nei loro corpi, solitamente scendendo a 0 punti ferita." },
  "Parola del Potere Uccidere": { livello:9, scuola:"Ammaliamento", classi:["Bardo","Mago","Stregone","Warlock"], tempo:"1 Azione", gittata:"18m", desc:"L'incantatore pronuncia una parola del potere che può uccidere istantaneamente una creatura entro gittata e che egli sia in grado di vedere. Se la creatura scelta possiede 100 punti ferita o meno, muore. Altrimenti, l'incantesimo non ha effetto." },
};

